/* ── B. ÉTAT GLOBAL DE L'APPLICATION ────────────────────────────────
   Ces variables mémorisent ce qui est affiché à l'écran.
   Toute modification doit être suivie d'un appel à renderSB()
   et/ou renderContent() / renderAuthorContent() pour mettre à jour l'UI.  */
// Ordre d'affichage des notions (sidebar, recherche, quiz…). Explicite plutôt
// que Object.keys(D) : on réordonne sans déplacer les gros blocs de D.
// ⚠ Doit contenir EXACTEMENT les 17 clés de D (une absente = notion masquée).
const KEYS=["conscience","inconscient","devoir","liberte","bonheur","religion",
  "langage","art","technique","travail","justice","etat","nature","raison",
  "science","verite","temps"];
let cur=KEYS[0];             // notion active (ex: "conscience")
let curTab='auteurs';        // onglet actif dans la vue notion
let curConceptSubTab='concepts'; // sous-onglet de l'onglet Concepts : 'concepts' | 'liens'
let curExempleSubTab='exemples';  // sous-onglet de l'onglet Exemples : 'exemples' | 'accroches'
let sbMode='notions';        // mode sidebar : 'notions' | 'auteurs' | 'concepts'
let curAuthor=null;          // auteur actif (chaîne = nom exact dans AM/AI)
let curAuthorTab='idees';    // onglet actif dans la fiche auteur

/* ── C. DONNÉES — MÉTADONNÉES AUTEURS ───────────────────────────────
   const AM  (Author Metadata) : informations biographiques et philosophiques
   de chaque auteur, indépendantes des notions.
   Clé = nom exact de l'auteur (doit correspondre à la propriété n dans D).
   Propriétés :
     bio       → courte biographie (dates, nationalité, apport principal)
     courant   → courant philosophique (utilisé pour la couleur via CC)
     periode   → siècle(s) d'activité
     themes    → liste de concepts-clés propres à cet auteur (affichés et
                 linkifiés dans la fiche auteur — c'est ce que tu as corrigé)
     dialogues → relations avec d'autres auteurs, chacune avec :
                   dir    = "oppose" | "prolonge" | "repond"
                   auteur = nom de l'interlocuteur
                   sujet  = thème du dialogue (court)
                   desc   = explication de la relation (affichée dans
                            l'onglet Dialogues de la fiche auteur)         */
const AM={
"Descartes":{bio:"Philosophe et mathématicien français (1596–1650). Fondateur du rationalisme moderne, il cherche à atteindre des vérités certaines par le doute méthodique.",courant:"Rationalisme",periode:"XVIIe siècle",themes:["cogito","dualisme corps/âme","méthode","maîtrise de la nature","certitude"],dialogues:[{dir:"oppose",auteur:"Hume",sujet:"certitudes de la raison",desc:"Hume montre qu'aucune relation causale n'est nécessaire : ce que Descartes tenait pour certain n'est qu'une habitude psychologique."},{dir:"oppose",auteur:"Freud",sujet:"transparence de la conscience",desc:"Freud renverse le cogito : le moi n'est pas maître en sa propre maison — l'inconscient détermine nos actes à notre insu."},{dir:"prolonge",auteur:"Spinoza",sujet:"rationalisme",desc:"Spinoza radicalise Descartes en éliminant le dualisme corps/âme et en identifiant Dieu, la Nature et la Substance."}]},
"Freud":{bio:"Neurologue autrichien (1856–1939), fondateur de la psychanalyse. Il découvre l'inconscient comme instance psychique déterminant nos actes à notre insu.",courant:"Psychanalyse",periode:"XIXe–XXe siècle",themes:["inconscient","ça/moi/surmoi","refoulement","rêve","pulsions"],dialogues:[{dir:"oppose",auteur:"Descartes",sujet:"souveraineté du cogito",desc:"Le cogito cartésien suppose que la conscience est transparente à elle-même — Freud montre que ce présupposé est faux."},{dir:"repond",auteur:"Sartre",sujet:"liberté et inconscient",desc:"Sartre refuse l'inconscient freudien : la censure doit avoir conscience de ce qu'elle refoule, ce qui la rend de 'mauvaise foi'."},{dir:"prolonge",auteur:"Nietzsche",sujet:"critique du sujet rationnel",desc:"Nietzsche annonce Freud en montrant que nos motivations réelles sont masquées par des rationalisations."}]},
"Sartre":{bio:"Philosophe français (1905–1980), chef de file de l'existentialisme. Sa thèse centrale : l'existence précède l'essence — l'homme se définit uniquement par ses actes.",courant:"Existentialisme / Phénoménologie",periode:"XXe siècle",themes:["liberté radicale","mauvaise foi","existence précède l'essence","intersubjectivité","engagement"],dialogues:[{dir:"oppose",auteur:"Freud",sujet:"inconscient et liberté",desc:"Sartre refuse l'inconscient : admettre des forces qui nous déterminent à notre insu, c'est être de mauvaise foi."},{dir:"repond",auteur:"Bourdieu",sujet:"déterminisme social et liberté",desc:"Bourdieu répond à Sartre : la liberté n'est pas pure spontanéité — elle est conditionnée par les structures sociales, mais leur connaissance la rend possible."},{dir:"prolonge",auteur:"Hegel",sujet:"conscience de soi",desc:"Sartre hérite de Hegel la structure de la conscience (pour-soi/en-soi) mais refuse la réconciliation dialectique finale."}]},
"Hegel":{bio:"Philosophe allemand (1770–1831), figure majeure de l'idéalisme. Sa dialectique (thèse/antithèse/synthèse) est une méthode pour comprendre le devenir de l'Esprit dans l'histoire.",courant:"Idéalisme allemand",periode:"XVIIIe–XIXe siècle",themes:["dialectique","maître/esclave","Esprit","liberté objective","État éthique"],dialogues:[{dir:"oppose",auteur:"Kant",sujet:"liberté et institutions",desc:"Kant place la liberté dans la raison individuelle ; Hegel la situe dans les institutions concrètes (famille, société civile, État)."},{dir:"oppose",auteur:"Marx",sujet:"moteur de l'histoire",desc:"Marx 'retourne' Hegel sur ses pieds : ce n'est pas l'Esprit mais les conditions matérielles qui font l'histoire."},{dir:"repond",auteur:"Rousseau",sujet:"volonté générale",desc:"Hegel reprend la volonté générale de Rousseau mais la réalise dans l'État comme vie éthique concrète, non comme contrat abstrait."}]},
"Kant":{bio:"Philosophe allemand (1724–1804), auteur des trois Critiques. Sa 'révolution copernicienne' : c'est le sujet qui structure l'expérience possible, non l'inverse.",courant:"Idéalisme transcendantal",periode:"XVIIIe siècle",themes:["impératif catégorique","autonomie morale","beau sans concept","génie","devoir"],dialogues:[{dir:"repond",auteur:"Hume",sujet:"fondements de la connaissance",desc:"Hume réveille Kant de son 'sommeil dogmatique' — en réponse, Kant montre que la causalité est une catégorie a priori de l'entendement."},{dir:"oppose",auteur:"Mill",sujet:"fondements de la morale",desc:"Mill fonde la morale sur le bonheur ; Kant refuse tout fondement empirique — le devoir est inconditionnel, indépendant des conséquences."},{dir:"oppose",auteur:"Aristote",sujet:"bonheur et morale",desc:"Aristote fait du bonheur la fin ultime ; Kant les sépare radicalement — le bonheur ne peut fonder la morale."}]},
"Marx":{bio:"Philosophe et économiste allemand (1818–1883). Fondateur du matérialisme historique : les rapports de production déterminent la superstructure sociale, juridique et idéologique.",courant:"Matérialisme historique",periode:"XIXe siècle",themes:["aliénation","plus-value","infrastructure/superstructure","lutte des classes","dépérissement de l'État"],dialogues:[{dir:"oppose",auteur:"Hegel",sujet:"moteur de l'histoire",desc:"Marx renverse Hegel : ce n'est pas l'Esprit mais les conditions matérielles qui font l'histoire ('retourner Hegel sur ses pieds')."},{dir:"oppose",auteur:"Nozick",sujet:"justice et propriété",desc:"Nozick défend la propriété individuelle absolue ; Marx voit dans la propriété privée la source même de l'exploitation."},{dir:"prolonge",auteur:"Engels",sujet:"matérialisme dialectique",desc:"Engels co-construit le marxisme avec Marx et développe l'analyse de l'État comme instrument de domination de classe."}]},
"Rousseau":{bio:"Philosophe genevois (1712–1778). Il théorise le contrat social et la volonté générale, et soutient que l'homme est naturellement bon mais corrompu par la société.",courant:"Lumières / Contractualisme",periode:"XVIIIe siècle",themes:["contrat social","volonté générale","liberté civile","état de nature","inégalité"],dialogues:[{dir:"oppose",auteur:"Hobbes",sujet:"état de nature",desc:"Hobbes voit l'état de nature comme une guerre de tous contre tous ; Rousseau le voit comme un état de bonheur naturel corrompu par la propriété."},{dir:"oppose",auteur:"Locke",sujet:"propriété et contrat",desc:"Locke fonde le contrat pour protéger la propriété naturelle ; Rousseau voit dans la propriété l'origine de l'inégalité."},{dir:"prolonge",auteur:"Kant",sujet:"autonomie et loi",desc:"Kant s'inspire de Rousseau pour penser l'autonomie morale : se donner sa propre loi, c'est obéir à la loi qu'on s'est prescrite."}]},
"Hobbes":{bio:"Philosophe anglais (1588–1679). Il théorise un État souverain absolu (le Léviathan) comme seul garant de la paix civile contre la violence de l'état de nature.",courant:"Contractualisme / Absolutisme",periode:"XVIIe siècle",themes:["état de nature","Léviathan","contrat social","sécurité","guerre de tous contre tous"],dialogues:[{dir:"oppose",auteur:"Rousseau",sujet:"nature humaine",desc:"Rousseau renverse Hobbes : l'homme n'est pas naturellement violent — c'est la société et la propriété qui le corrompent."},{dir:"oppose",auteur:"Locke",sujet:"étendue du contrat",desc:"Locke limite le contrat aux droits naturels à préserver ; Hobbes exige l'abandon total de la liberté naturelle au souverain."}]},
"Locke":{bio:"Philosophe anglais (1632–1704). Père du libéralisme politique, il défend les droits naturels inaliénables et la légitimité de la révolution contre un gouvernement tyrannique.",courant:"Empirisme / Libéralisme",periode:"XVIIe siècle",themes:["droits naturels","contrat révocable","propriété","identité mémorielle","tolérance"],dialogues:[{dir:"oppose",auteur:"Hobbes",sujet:"souveraineté",desc:"Hobbes veut un souverain absolu irrévocable ; Locke pose que le contrat est révocable si le gouvernement viole les droits naturels."},{dir:"prolonge",auteur:"Mill",sujet:"libéralisme",desc:"Mill hérite de Locke le souci de protéger les libertés individuelles contre l'État et la tyrannie de la majorité."}]},
"Nietzsche":{bio:"Philosophe allemand (1844–1900). Critique radical de la morale chrétienne et du rationalisme occidental. Il annonce la 'mort de Dieu' et propose la figure du 'surhomme'.",courant:"Généalogie / Philosophie de la vie",periode:"XIXe siècle",themes:["volonté de puissance","mort de Dieu","éternel retour","généalogie de la morale","travail comme police"],dialogues:[{dir:"oppose",auteur:"Kant",sujet:"morale universelle",desc:"Kant fonde une morale universelle ; Nietzsche la déconstruit par la généalogie : les valeurs morales expriment des rapports de force."},{dir:"prolonge",auteur:"Schopenhauer",sujet:"volonté",desc:"Nietzsche hérite de Schopenhauer la centralité de la volonté, mais la réinterprète positivement comme volonté de puissance."},{dir:"oppose",auteur:"Freud",sujet:"inconscient",desc:"Nietzsche anticipe Freud en montrant les rationalisations masquant nos motivations réelles, mais sans le cadre clinique."}]},
"Spinoza":{bio:"Philosophe néerlandais (1632–1677). Il développe un panthéisme rationnel : Dieu est identique à la Nature. Sa philosophie vise la libération par la connaissance.",courant:"Rationalisme / Panthéisme",periode:"XVIIe siècle",themes:["Dieu-Nature","liberté comme nécessité comprise","conatus","déterminisme","Éthique"],dialogues:[{dir:"prolonge",auteur:"Descartes",sujet:"rationalisme",desc:"Spinoza radicalise le rationalisme cartésien en éliminant le dualisme et en construisant une éthique more geometrico."},{dir:"oppose",auteur:"Sartre",sujet:"liberté",desc:"Sartre affirme une liberté absolue ; Spinoza montre que le libre arbitre est une illusion née de l'ignorance des causes."},{dir:"prolonge",auteur:"Engels",sujet:"liberté et nécessité",desc:"Engels reprend Spinoza : la liberté consiste dans la connaissance des nécessités naturelles, non dans leur absence."}]},
"Hannah Arendt":{bio:"Philosophe politique américano-allemande (1906–1975). Elle analyse les régimes totalitaires et la condition humaine moderne. Son concept de 'banalité du mal' est central.",courant:"Phénoménologie / Philosophie politique",periode:"XXe siècle",themes:["banalité du mal","labor/work/action","culture de masse","totalitarisme","permanence de l'œuvre"],dialogues:[{dir:"oppose",auteur:"Marx",sujet:"travail",desc:"Marx voit dans le travail la source de l'émancipation ; Arendt distingue le labor (aliénant, cyclique) du work (créateur) et de l'action (politique)."},{dir:"repond",auteur:"Kant",sujet:"jugement moral",desc:"Arendt reprend Kant pour penser le jugement politique : juger sans règle universelle, comme dans le jugement esthétique."}]},
"Bourdieu":{bio:"Sociologue français (1930–2002). Il analyse les mécanismes de reproduction sociale et développe les concepts d'habitus, de capital culturel et de violence symbolique.",courant:"Sociologie critique",periode:"XXe siècle",themes:["habitus","capital culturel","violence symbolique","reproduction sociale","goût de classe"],dialogues:[{dir:"oppose",auteur:"Sartre",sujet:"liberté et déterminisme",desc:"Sartre affirme une liberté radicale ; Bourdieu montre que nos choix sont conditionnés par l'habitus — mais la connaissance des déterminismes ouvre un espace de liberté."},{dir:"prolonge",auteur:"Marx",sujet:"domination",desc:"Bourdieu prolonge Marx en ajoutant la dimension symbolique : la domination culturelle reproduit les inégalités de classe."}]},
"Platon":{bio:"Philosophe grec (v. 428–348 av. J.-C.), disciple de Socrate. Il développe la théorie des Idées : le monde sensible n'est que l'ombre d'un monde intelligible parfait.",courant:"Idéalisme platonicien",periode:"Antiquité grecque",themes:["théorie des Idées","justice","âme","cité idéale","imitation (mimésis)"],dialogues:[{dir:"oppose",auteur:"Aristote",sujet:"nature des Idées",desc:"Aristote refuse les Idées séparées de Platon : la forme est immanente à la matière concrète, non transcendante."},{dir:"repond",auteur:"Rousseau",sujet:"contrat et cité",desc:"Rousseau hérite de Platon l'idée que l'État forme les citoyens, mais en renversant la hiérarchie : c'est le peuple qui est souverain."}]},
"Aristote":{bio:"Philosophe grec (384–322 av. J.-C.), disciple de Platon. Sa philosophie est empirique et encyclopédique — il fonde la logique, l'éthique et la politique sur l'observation du réel.",courant:"Empirisme antique / Aristotélisme",periode:"Antiquité grecque",themes:["eudaimonia","vertu","forme/matière","animal politique","technê / main"],dialogues:[{dir:"oppose",auteur:"Platon",sujet:"théorie des Idées",desc:"Platon sépare le monde sensible du monde intelligible ; Aristote ancre les formes dans la matière concrète."},{dir:"oppose",auteur:"Kant",sujet:"bonheur et morale",desc:"Aristote fait du bonheur (eudaimonia) la fin ultime ; Kant sépare radicalement bonheur et devoir moral."}]},
"Mill":{bio:"Philosophe et économiste britannique (1806–1873). Chef de file de l'utilitarisme, il défend aussi les libertés individuelles contre la 'tyrannie de la majorité'.",courant:"Utilitarisme / Libéralisme",periode:"XIXe siècle",themes:["principe de non-nuisance","bonheur du plus grand nombre","liberté d'expression","utilitarisme","plaisirs inférieurs/supérieurs"],dialogues:[{dir:"oppose",auteur:"Kant",sujet:"fondements de la morale",desc:"Kant fonde la morale sur le devoir rationnel ; Mill la fonde sur les conséquences (bonheur produit)."},{dir:"prolonge",auteur:"Locke",sujet:"libertés individuelles",desc:"Mill hérite de Locke et radicalise la défense des libertés individuelles, notamment la liberté d'expression absolue."}]},
"Hans Jonas":{bio:"Philosophe allemand (1903–1993). Face aux risques de la technique moderne, il propose une éthique de la responsabilité orientée vers la préservation de la vie future.",courant:"Éthique de la responsabilité",periode:"XXe siècle",themes:["principe responsabilité","heuristique de la peur","générations futures","irréversible","technique"],dialogues:[{dir:"repond",auteur:"Kant",sujet:"éthique",desc:"Jonas prolonge Kant mais l'adapte : l'impératif catégorique doit intégrer les effets à long terme sur la biosphère."},{dir:"oppose",auteur:"Descartes",sujet:"maîtrise de la nature",desc:"Descartes veut nous rendre 'maîtres et possesseurs de la nature' ; Jonas montre que cette maîtrise crée des responsabilités nouvelles et inédites."}]},
"Heidegger":{bio:"Philosophe allemand (1889–1976). Sa question centrale est celle du sens de l'Être. Il analyse la technique moderne comme un mode de dévoilement réduisant le réel à un 'fonds disponible'.",courant:"Ontologie / Phénoménologie existentiale",periode:"XXe siècle",themes:["être-là (Dasein)","technique comme dévoilement","fonds disponible","authenticité","finitude"],dialogues:[{dir:"prolonge",auteur:"Nietzsche",sujet:"nihilisme",desc:"Heidegger voit en Nietzsche l'achèvement de la métaphysique occidentale — le nihilisme que Nietzsche annonce, Heidegger le diagnostique."},{dir:"oppose",auteur:"Descartes",sujet:"rapport à la nature",desc:"Descartes inaugure la domination de la nature ; Heidegger montre que la technique moderne en est l'aboutissement — mise à disposition totale du réel."}]},
"Simondon":{bio:"Philosophe français (1924–1989). Il développe une philosophie des objets techniques dépassant à la fois la technophobie et l'enthousiasme naïf.",courant:"Philosophie de la technique",periode:"XXe siècle",themes:["individuation","culture technique","aliénation par méconnaissance","objet technique","organisateur permanent"],dialogues:[{dir:"oppose",auteur:"Heidegger",sujet:"rapport à la technique",desc:"Heidegger voit dans la technique une menace ontologique ; Simondon propose une réconciliation par la connaissance du fonctionnement réel des machines."},{dir:"repond",auteur:"Marx",sujet:"aliénation",desc:"Marx voit l'aliénation dans les rapports de production ; Simondon la localise dans la méconnaissance — comprendre les machines, c'est s'émanciper."}]},
"Weil":{bio:"Philosophe et militante française (1909–1943). Elle combine engagement politique (usines, guerre d'Espagne) et réflexion sur le travail, l'enracinement et la condition ouvrière.",courant:"Philosophie sociale / Mysticisme",periode:"XXe siècle",themes:["condition ouvrière","enracinement","travail non servile","devoir de l'ingénieur","attention"],dialogues:[{dir:"prolonge",auteur:"Marx",sujet:"aliénation ouvrière",desc:"Weil hérite de Marx la critique de l'aliénation ouvrière, mais l'ancre dans une expérience vécue des usines et une dimension spirituelle."},{dir:"repond",auteur:"Nietzsche",sujet:"travail et sens",desc:"Nietzsche critique le culte du travail ; Weil cherche, elle, les conditions d'un travail non servile porteur de sens."}]},
"Weber":{bio:"Sociologue et économiste allemand (1864–1920). Il analyse les fondements de la légitimité politique et le processus de rationalisation des sociétés modernes.",courant:"Sociologie compréhensive",periode:"XIXe–XXe siècle",themes:["monopole violence légitime","légitimité (3 types)","éthique de conviction/responsabilité","rationalisation","bureaucratie"],dialogues:[{dir:"oppose",auteur:"Marx",sujet:"moteur de l'histoire",desc:"Marx voit l'économie comme déterminant ultime ; Weber montre que les idées (notamment religieuses) peuvent aussi être motrices — cf. L'éthique protestante."}]},
"Tocqueville":{bio:"Historien et philosophe politique français (1805–1859). Observateur lucide de la démocratie américaine, il met en garde contre le despotisme doux des démocraties modernes.",courant:"Libéralisme politique",periode:"XIXe siècle",themes:["despotisme doux","égalité des conditions","individualisme démocratique","liberté civile","participation citoyenne"],dialogues:[{dir:"prolonge",auteur:"Mill",sujet:"tyrannie de la majorité",desc:"Mill et Tocqueville convergent : la démocratie menace la liberté non seulement par la loi mais par la pression sociale de la majorité."},{dir:"repond",auteur:"Rousseau",sujet:"démocratie réelle",desc:"Rousseau idéalise la volonté générale ; Tocqueville montre les dérives concrètes des démocraties réelles."}]},
"Schopenhauer":{bio:"Philosophe allemand (1788–1860). Il développe un pessimisme métaphysique fondé sur la 'volonté de vivre' — force aveugle et insatiable à l'origine de toute souffrance.",courant:"Pessimisme / Volontarisme",periode:"XIXe siècle",themes:["volonté de vivre","pessimisme","désir insatiable","art comme salut","ascèse"],dialogues:[{dir:"oppose",auteur:"Aristote",sujet:"bonheur",desc:"Aristote croit au bonheur comme fin accessible ; Schopenhauer montre que la satisfaction est toujours provisoire — le désir est infini."},{dir:"prolonge",auteur:"Nietzsche",sujet:"volonté",desc:"Nietzsche hérite de Schopenhauer la centralité de la volonté, mais la réinterprète positivement comme volonté de puissance."}]},
"Épicure":{bio:"Philosophe grec (341–270 av. J.-C.), fondateur de l'épicurisme. Sa philosophie vise l'ataraxie (paix de l'âme) par le calcul raisonné des désirs et la retraite dans le jardin.",courant:"Épicurisme",periode:"Antiquité grecque",themes:["ataraxie","aponie","classification des désirs","amitié","mort sans crainte"],dialogues:[{dir:"oppose",auteur:"Aristote",sujet:"vie bonne",desc:"Aristote fait du bonheur une activité vertueuse engagée dans la cité ; Épicure préfère le retrait dans le jardin et l'amitié."},{dir:"oppose",auteur:"Kant",sujet:"morale et bonheur",desc:"Kant refuse que le bonheur fonde la morale ; Épicure en fait au contraire le guide suprême de toute conduite de vie."}]},
"Rawls":{bio:"Philosophe politique américain (1921–2002). Sa Théorie de la justice propose un modèle fondé sur le 'voile d'ignorance' et le principe de différence.",courant:"Libéralisme égalitaire",periode:"XXe siècle",themes:["voile d'ignorance","principe de différence","équité","désobéissance civile légitime","justice comme équité"],dialogues:[{dir:"oppose",auteur:"Nozick",sujet:"redistribution",desc:"Nozick défend la propriété absolue et refuse toute redistribution ; Rawls admet les inégalités si elles bénéficient aux plus défavorisés."},{dir:"prolonge",auteur:"Kant",sujet:"universalisme moral",desc:"Le voile d'ignorance de Rawls est un dispositif kantien : trouver des principes que tout agent rationnel pourrait universaliser."}]},
"Nozick":{bio:"Philosophe américain (1938–2002), défenseur du libertarianisme. Il soutient que l'État minimal est le seul légitime et que toute redistribution viole les droits individuels.",courant:"Libertarianisme",periode:"XXe siècle",themes:["État minimal","droits individuels","propriété","anti-redistribution","titres légitimes"],dialogues:[{dir:"oppose",auteur:"Rawls",sujet:"redistribution",desc:"Rawls justifie la redistribution par le voile d'ignorance ; Nozick y voit une violation des droits — on ne peut pas prendre à Pierre pour donner à Paul."},{dir:"oppose",auteur:"Marx",sujet:"propriété",desc:"Marx voit dans la propriété privée la source de l'exploitation ; Nozick en fait au contraire le fondement inviolable de la justice."}]},
"Amartya Sen":{bio:"Économiste et philosophe indien (né en 1933), prix Nobel d'économie 1998. Il développe l'approche par les capabilités et une conception comparative de la justice.",courant:"Libéralisme égalitaire / Approche par les capabilités",periode:"XXe–XXIe siècle",themes:["capabilités","justice comparative","injustices réparables","démocratie et délibération","développement comme liberté"],dialogues:[{dir:"oppose",auteur:"Rawls",sujet:"justice idéale vs comparative",desc:"Rawls cherche les principes de LA société juste (transcendantal) ; Sen privilégie la réduction concrète des injustices réelles (comparatif)."},{dir:"oppose",auteur:"Robert Nozick",sujet:"la flûte et le mérite",desc:"Avec l'exemple des trois enfants et de la flûte, Sen montre que le titre du producteur (Carla, cher à Nozick) n'est qu'une raison parmi d'autres, face au besoin (Bob) et à la compétence (Anne)."}]},
"Bergson":{bio:"Philosophe français (1859–1941). Il développe une philosophie de la durée et de l'élan vital, en opposition au mécanisme et au déterminisme scientiste.",courant:"Vitalisme / Philosophie de la durée",periode:"XIXe–XXe siècle",themes:["durée","élan vital","homo faber","mémoire","intuition"],dialogues:[{dir:"oppose",auteur:"Descartes",sujet:"mécanisme",desc:"Descartes réduit le corps à une machine ; Bergson oppose à ce mécanisme la durée vécue, irréductible à l'espace et au calcul."},{dir:"prolonge",auteur:"Aristote",sujet:"évolution et finalité",desc:"Bergson reprend l'idée d'une finalité dans la nature mais la dynamise : l'élan vital est créateur, imprévisible, non téléologique."}]},
"Hume":{bio:"Philosophe écossais (1711–1776), figure centrale de l'empirisme. Il montre que nos certitudes rationnelles (causalité, substance, moi) ne sont que des habitudes psychologiques.",courant:"Empirisme / Scepticisme",periode:"XVIIIe siècle",themes:["causalité comme habitude","bundle theory du moi","scepticisme","raison esclave des passions","induction"],dialogues:[{dir:"oppose",auteur:"Descartes",sujet:"certitudes rationnelles",desc:"Descartes fonde des certitudes sur la raison pure ; Hume montre que toute connaissance vient de l'expérience et que la causalité n'est qu'une habitude."},{dir:"prolonge",auteur:"Locke",sujet:"empirisme",desc:"Hume radicalise l'empirisme de Locke en appliquant le même scepticisme à la notion de substance et au moi lui-même."}]},
"Merleau-Ponty":{bio:"Philosophe français (1908–1961). Il développe une phénoménologie du corps vécu, montrant que la perception est toujours déjà corporelle et engagée dans le monde.",courant:"Phénoménologie du corps",periode:"XXe siècle",themes:["corps vécu","perception","chair du monde","intersubjectivité","art et expression"],dialogues:[{dir:"prolonge",auteur:"Sartre",sujet:"phénoménologie",desc:"Merleau-Ponty partage avec Sartre l'héritage husserlien mais critique son dualisme implicite — le corps n'est pas pure facticité."},{dir:"repond",auteur:"Descartes",sujet:"dualisme corps/âme",desc:"Contre le dualisme cartésien, Merleau-Ponty montre que le corps est le sujet de la perception — être-au-monde est d'abord corporel."}]},
"Engels":{bio:"Philosophe et économiste allemand (1820–1895). Co-fondateur du marxisme avec Marx, il développe le matérialisme dialectique et l'analyse de l'État comme instrument de domination.",courant:"Matérialisme dialectique",periode:"XIXe siècle",themes:["matérialisme dialectique","État et domination","liberté et nécessité","origine de la famille","anti-Dühring"],dialogues:[{dir:"prolonge",auteur:"Marx",sujet:"matérialisme historique",desc:"Engels co-construit le marxisme avec Marx et l'étend à la dialectique de la nature entière."},{dir:"prolonge",auteur:"Spinoza",sujet:"liberté et nécessité",desc:"Engels reprend Spinoza : la liberté consiste dans la connaissance des nécessités naturelles — 'on commande à la nature en lui obéissant'."}]},
"Thoreau":{bio:"Écrivain et philosophe américain (1817–1862). Partisan du retour à la nature (Walden) et inventeur du concept de désobéissance civile contre les lois injustes.",courant:"Transcendantalisme / Anarchisme pacifiste",periode:"XIXe siècle",themes:["désobéissance civile","nature","simplicité volontaire","résistance non-violente","conscience morale"],dialogues:[{dir:"prolonge",auteur:"Rawls",sujet:"désobéissance civile",desc:"Rawls formalise en théorie politique ce que Thoreau pratiquait : la désobéissance civile est légitime contre les lois injustes, sous conditions."},{dir:"repond",auteur:"Platon",sujet:"obéissance aux lois",desc:"Platon (Criton) exige d'obéir même à une loi injuste ; Thoreau s'y oppose radicalement : obéir à une loi injuste, c'est en être complice."}]},
"La Boétie":{bio:"Humaniste français (1530–1563). Son unique grand texte analyse le mécanisme de la servitude volontaire : pourquoi des millions d'hommes obéissent-ils librement à un seul tyran ?",courant:"Humanisme de la Renaissance",periode:"XVIe siècle",themes:["servitude volontaire","tyrannie","résistance passive","habitude","liberté politique"],dialogues:[{dir:"prolonge",auteur:"Thoreau",sujet:"désobéissance",desc:"Thoreau et La Boétie convergent : la résistance ne nécessite pas de combattre — cesser d'obéir suffit à faire tomber la tyrannie."},{dir:"repond",auteur:"Hobbes",sujet:"obéissance politique",desc:"Hobbes légitime l'obéissance absolue au souverain ; La Boétie en dénonce le mystère — pourquoi obéit-on librement à ce qui nous opprime ?"}]},
"D'Holbach":{bio:"Philosophe français des Lumières (1723–1789). Il défend un matérialisme et un athéisme radical : la nature obéit à des lois mécaniques, et la liberté humaine est une illusion.",courant:"Matérialisme / Athéisme des Lumières",periode:"XVIIIe siècle",themes:["déterminisme physique","matérialisme","athéisme","liberté illusoire","nature mécaniste"],dialogues:[{dir:"oppose",auteur:"Descartes",sujet:"dualisme et liberté",desc:"Descartes maintient la liberté de l'âme ; D'Holbach étend le mécanisme cartésien à l'homme entier — il n'y a plus de place pour le libre arbitre."},{dir:"prolonge",auteur:"Spinoza",sujet:"déterminisme",desc:"D'Holbach radicalise le déterminisme spinoziste en un matérialisme physique sans Dieu ni Substance."}]},
"Épictète":{bio:"Philosophe stoïcien grec (v. 50–135 ap. J.-C.), ancien esclave. Il enseigne que la liberté intérieure est possible même dans les pires conditions extérieures.",courant:"Stoïcisme",periode:"Antiquité gréco-romaine",themes:["dichotomie du contrôle","liberté intérieure","représentations","indifférents","sagesse stoïcienne"],dialogues:[{dir:"prolonge",auteur:"Kant",sujet:"liberté intérieure",desc:"Kant et Épictète convergent : la vraie liberté est intérieure, réside dans la maîtrise de sa volonté, non dans les circonstances extérieures."},{dir:"oppose",auteur:"Sartre",sujet:"liberté en situation",desc:"Sartre dit qu'on est toujours libre de se projeter autrement ; Épictète est plus radical : la liberté ne concerne que ce qui dépend strictement de nous."}]},
"Lafargue":{bio:"Journaliste et militant politique franco-cubain (1842–1911), gendre de Marx. Son pamphlet 'Le Droit à la paresse' dénonce le culte du travail.",courant:"Socialisme / Critique du travail",periode:"XIXe siècle",themes:["droit à la paresse","culte du travail","exploitation ouvrière","temps libre","émancipation"],dialogues:[{dir:"prolonge",auteur:"Marx",sujet:"exploitation",desc:"Lafargue pousse la critique marxiste jusqu'au bout : si le travail aliène, c'est le travail lui-même qu'il faut refuser, pas seulement son exploitation."},{dir:"repond",auteur:"Nietzsche",sujet:"travail et contrôle",desc:"Nietzsche voit le travail comme 'meilleure des polices' ; Lafargue converge : le travail est l'instrument d'une exploitation intériorisée."}]},
"Arendt":{bio:"Voir 'Hannah Arendt'.",courant:"",periode:"",themes:[],dialogues:[]},
"Anders":{bio:"Philosophe et écrivain autrichien (1902–1992). Il développe une philosophie de la technique fondée sur la 'honte prométhéenne' de l'homme face à ses propres machines.",courant:"Philosophie de la technique / Philosophie de l'existence",periode:"XXe siècle",themes:["honte prométhéenne","genre mortel","Hiroshima","obsolescence de l'homme","technique et puissance"],dialogues:[{dir:"prolonge",auteur:"Hans Jonas",sujet:"responsabilité technique",desc:"Anders et Jonas partagent la même anxiété face à la technique nucléaire — mais Anders va plus loin : l'homme est devenu ontologiquement obsolète face à ses machines."},{dir:"prolonge",auteur:"Heidegger",sujet:"technique et humanité",desc:"Anders hérite de Heidegger la critique de la technique, mais l'ancre dans l'événement concret d'Hiroshima plutôt que dans l'ontologie."}]},
"Baudrillard":{bio:"Sociologue et philosophe français (1929–2007). Il analyse la société de consommation comme un système de signes qui remplace la réalité par des simulacres.",courant:"Philosophie de la culture / Postmodernisme",periode:"XXe siècle",themes:["simulation","simulacre","société de consommation","hyperréalité","objets et rêves"],dialogues:[{dir:"prolonge",auteur:"Marx",sujet:"critique de la société marchande",desc:"Baudrillard prolonge Marx : la marchandise n'est plus seulement un rapport social — elle est devenue signe, simulation, hyperréalité."},{dir:"repond",auteur:"Simondon",sujet:"objets techniques",desc:"Simondon analyse les objets techniques pour mieux les comprendre ; Baudrillard analyse la société de consommation pour en montrer le caractère illusoire."}]},
"Ricœur":{bio:"Philosophe français (1913–2005). Il développe une herméneutique de soi et de l'identité narrative, cherchant à réconcilier interprétation et réflexion.",courant:"Herméneutique / Phénoménologie",periode:"XXe siècle",themes:["identité narrative","idem/ipse","herméneutique","récit de soi","mémoire"],dialogues:[{dir:"prolonge",auteur:"Freud",sujet:"récit et inconscient",desc:"Ricœur voit dans la cure analytique une forme d'herméneutique du soi — reconstruire une identité narrative à partir des fragments du passé."},{dir:"repond",auteur:"Hume",sujet:"identité du moi",desc:"Hume dissout le moi en un flux de perceptions ; Ricœur répond : l'identité narrative permet de maintenir une unité sans substance fixe."}]},
"Alain":{bio:"Philosophe français (1868–1951), professeur emblématique de la Troisième République. Il développe une philosophie de la résistance à la puissance et de la formation du sujet par le travail.",courant:"Rationalisme républicain",periode:"XIXe–XXe siècle",themes:["résistance aux pouvoirs","formation du sujet","travail manuel","bonheur","propos"],dialogues:[{dir:"prolonge",auteur:"Kant",sujet:"autonomie morale",desc:"Alain hérite de Kant le souci de l'autonomie : le citoyen doit résister aux pouvoirs, y compris aux passions et aux émotions."},{dir:"prolonge",auteur:"Hegel",sujet:"conscience de soi et autrui",desc:"Alain prolonge Hegel : c'est des autres que nous tenons la première connaissance de nous-mêmes."}]},
"Pascal":{bio:"Mathématicien, physicien et philosophe français (1623–1662). Sa pensée oscille entre l'apologétique chrétienne et une lucidité radicale sur la condition humaine ('roseau pensant').",courant:"Augustinisme / Apologétique",periode:"XVIIe siècle",themes:["roseau pensant","divertissement","misère et grandeur de l'homme","pari","cœur et raison"],dialogues:[{dir:"repond",auteur:"Descartes",sujet:"raison et finitude",desc:"Descartes fonde tout sur la raison ; Pascal montre ses limites — le cœur a ses raisons que la raison ne connaît point."},{dir:"prolonge",auteur:"Nietzsche",sujet:"divertissement et travail",desc:"Pascal analyse le divertissement comme fuite de soi ; Nietzsche prolonge cette idée en montrant que le travail est la 'meilleure des polices'."}]},
"Saussure":{bio:"Linguiste suisse (1857–1913), fondateur de la linguistique structurale. Son Cours de linguistique générale (reconstitué par ses étudiants) pose les bases de la sémiologie moderne.",courant:"Structuralisme / Linguistique",periode:"XIXe–XXe siècle",themes:["signifiant/signifié","arbitraire du signe","langue comme système","synchronie/diachronie","valeur différentielle"],dialogues:[{dir:"prolonge",auteur:"Benveniste",sujet:"signe et symbole",desc:"Benveniste prolonge et nuance Saussure en distinguant signal et symbole, réservant le symbole à l'espèce humaine."},{dir:"prolonge",auteur:"Hegel",sujet:"langage et pensée",desc:"Hegel avait posé que la pensée se réalise dans le mot ; Saussure montre que la langue structure la pensée en la découpant."}]},
"Benveniste":{bio:"Linguiste français d'origine syrienne (1902–1976). Spécialiste de linguistique générale et de linguistique indo-européenne, il développe une réflexion sur la subjectivité dans le langage.",courant:"Linguistique / Phénoménologie du langage",periode:"XXe siècle",themes:["signal/symbole","subjectivité dans le langage","énonciation","personne grammaticale","intersubjectivité"],dialogues:[{dir:"prolonge",auteur:"Saussure",sujet:"arbitraire et symbole",desc:"Benveniste nuance Saussure : le lien n'est pas arbitraire pour le locuteur natif (il est motivé psychologiquement). Et distingue signal/symbole."},{dir:"repond",auteur:"Aristote",sujet:"logos et animal",desc:"Aristote distinguait logos et phone ; Benveniste formalise cette distinction avec signal/symbole."}]},
"Jakobson":{bio:"Linguiste et théoricien de la littérature russo-américain (1896–1982). Co-fondateur du Cercle linguistique de Moscou et de Prague. Il développe un modèle de la communication à six facteurs.",courant:"Structuralisme / Linguistique",periode:"XXe siècle",themes:["6 fonctions du langage","modèle de communication","phonologie","poétique","fonction poétique"],dialogues:[{dir:"prolonge",auteur:"Saussure",sujet:"structuralisme",desc:"Jakobson prolonge le structuralisme saussurien en l'appliquant à la poétique et à la communication."},{dir:"repond",auteur:"Bergson",sujet:"langage et communication",desc:"Bergson souligne les limites communicationnelles du langage ; Jakobson en fait une richesse en multipliant les fonctions."}]},
"Austin":{bio:"Philosophe britannique (1911–1960), fondateur de la philosophie du langage ordinaire. Sa distinction performatif/constatif révolutionne la conception du langage.",courant:"Philosophie analytique du langage",periode:"XXe siècle",themes:["performatif/constatif","actes de langage","conditions de félicité","langage ordinaire","dire c'est faire"],dialogues:[{dir:"prolonge",auteur:"Wittgenstein",sujet:"langage ordinaire",desc:"Austin s'inscrit dans la tradition de Wittgenstein du second Tractatus : la signification est dans l'usage."},{dir:"repond",auteur:"Jakobson",sujet:"fonctions du langage",desc:"Jakobson catalogue les fonctions ; Austin montre que le langage peut être une action à part entière, pas seulement de la communication."}]},
"Watzlawick":{bio:"Psychologue et théoricien de la communication austro-américain (1921–2007). Membre de l'École de Palo Alto, il développe une pragmatique de la communication humaine.",courant:"Pragmatique de la communication / Psychologie systémique",periode:"XXe siècle",themes:["injonction paradoxale","double bind","métacommunication","pragmatique","communication pathologique"],dialogues:[{dir:"prolonge",auteur:"Bateson",sujet:"double bind",desc:"Watzlawick prolonge Bateson : le double bind (double contrainte) est à l'origine de certaines pathologies psychiques."},{dir:"repond",auteur:"Benveniste",sujet:"limites de la communication",desc:"Benveniste montre que le langage humain est symbolique ; Watzlawick montre que cette complexité crée des paradoxes communicationnels."}]},
"Boroditsky":{bio:"Linguiste cognitive américaine (née en 1975). Ses recherches expérimentales montrent que la langue maternelle influence profondément la cognition : perception du temps, de l'espace, des couleurs, de la causalité.",courant:"Linguistique cognitive / Relativisme linguistique",periode:"XXe–XXIe siècle",themes:["relativisme linguistique","Sapir-Whorf","espace et langue","genre grammatical","temps et langue"],dialogues:[{dir:"prolonge",auteur:"Saussure",sujet:"langue et pensée",desc:"Saussure pose que la langue découpe la pensée ; Boroditsky le démontre expérimentalement avec des données cognitives."},{dir:"repond",auteur:"Chomsky",sujet:"universaux linguistiques",desc:"Chomsky défend une grammaire universelle innée ; Boroditsky montre la profonde diversité cognitive liée aux langues."}]},
"Orwell":{bio:"Écrivain et journaliste britannique (1903–1950). Ses romans 1984 et La Ferme des animaux sont des analyses politiques du totalitarisme sous forme littéraire.",courant:"Littérature politique / Socialisme démocratique",periode:"XXe siècle",themes:["novlangue","totalitarisme","propagande","langage et pouvoir","doublethink"],dialogues:[{dir:"prolonge",auteur:"Hegel",sujet:"langage et pensée",desc:"Hegel pose que c'est dans les mots que nous pensons ; Orwell tire la conséquence politique : contrôler les mots, c'est contrôler la pensée."},{dir:"prolonge",auteur:"Hannah Arendt",sujet:"totalitarisme",desc:"Arendt analyse le totalitarisme politiquement ; Orwell le représente littérairement et insiste sur le rôle du langage dans sa propagation."}]},
"Cassin":{bio:"Philosophe et philologue française (née en 1947). Directrice de recherche au CNRS, elle développe une réflexion sur les 'intraduisibles' philosophiques et la politique de la mémoire.",courant:"Philosophie du langage / Philologie",periode:"XXe–XXIe siècle",themes:["intraduisibles","logos/phone","politique de la mémoire","sophistique","traduction philosophique"],dialogues:[{dir:"prolonge",auteur:"Aristote",sujet:"logos et politique",desc:"Aristote distingue logos (parole politique) et phone (voix animale) ; Cassin prolonge en montrant que cette distinction est elle-même culturellement marquée."},{dir:"repond",auteur:"Benveniste",sujet:"langue et pensée",desc:"Benveniste analyse la subjectivité dans le langage ; Cassin élargit à la dimension interculturelle des concepts philosophiques."}]},
"Popper":{bio:"Philosophe des sciences austro-britannique (1902–1994). Il développe le principe de falsifiabilité (réfutabilité) comme critère de démarcation entre science et non-science.",courant:"Épistémologie critique",periode:"XXe siècle",themes:["falsifiabilité","conjectures et réfutations","société ouverte","démocratie","critique du totalitarisme"],dialogues:[{dir:"oppose",auteur:"Kuhn",sujet:"progrès scientifique",desc:"Kuhn voit le progrès par révolutions de paradigmes ; Popper par conjectures et réfutations cumulatives."},{dir:"oppose",auteur:"Marx",sujet:"scientificité",desc:"Popper juge le marxisme non-scientifique car non-réfutable : toute contre-évidence est réinterprétée pour confirmer la théorie."}]},
"Kuhn":{bio:"Historien et philosophe des sciences américain (1922–1996). Sa notion de 'paradigme' et de 'révolution scientifique' a transformé l'épistémologie.",courant:"Histoire et philosophie des sciences",periode:"XXe siècle",themes:["paradigme","révolution scientifique","incommensurabilité","science normale","communauté scientifique"],dialogues:[{dir:"oppose",auteur:"Popper",sujet:"progrès scientifique",desc:"Popper voit la science comme progrès rationnel cumulatif ; Kuhn montre des ruptures paradigmatiques incommensurables."},{dir:"prolonge",auteur:"Gaston Bachelard",sujet:"ruptures épistémologiques",desc:"Bachelard avait déjà analysé les 'obstacles épistémologiques' ; Kuhn formalise cette rupture dans la notion de révolution."}]},
"Tristan Tzara":{bio:"Poète et écrivain franco-roumain (1896–1963), fondateur du dadaïsme. Auteur du Manifeste Dada (1918) et de la 'recette' pour faire un poème dadaïste : découper un journal, mettre les mots dans un sac, les tirer au hasard.",courant:"Dadaïsme",periode:"XXe siècle",themes:["poésie aléatoire","anti-art","langage comme matériau","hasard créateur","collage"],dialogues:[{dir:"prolonge",auteur:"André Breton",sujet:"avant-gardes",desc:"Le surréalisme de Breton prolonge le dadaïsme de Tzara — mais Breton institutionnalise un mouvement et théorise l'écriture automatique, là où Dada cultivait la rupture."},{dir:"oppose",auteur:"Saussure",sujet:"langage utilitaire",desc:"Tzara fait du langage un matériau pur, libéré de la fonction référentielle décrite par Saussure. La poésie dadaïste démontre que le langage peut être fin en soi."}]},
"André Breton":{bio:"Poète et écrivain français (1896–1966), fondateur du surréalisme. Auteur du Manifeste du surréalisme (1924). Il théorise l'écriture automatique comme accès direct à l'inconscient.",courant:"Surréalisme",periode:"XXe siècle",themes:["écriture automatique","inconscient créateur","cadavre exquis","hasard objectif","révolte"],dialogues:[{dir:"prolonge",auteur:"Freud",sujet:"inconscient comme source créative",desc:"Breton transforme l'inconscient freudien (objet clinique) en moteur poétique : l'écriture automatique vise à laisser parler l'inconscient sans censure rationnelle."},{dir:"prolonge",auteur:"Tristan Tzara",sujet:"avant-gardes",desc:"Le surréalisme prolonge le dadaïsme — mais en lui donnant une théorie (l'écriture automatique) et un programme (révolution poétique et politique)."}]},
"Georges Perec":{bio:"Écrivain français (1936–1982), membre majeur de l'OULIPO (Ouvroir de Littérature Potentielle, fondé par Queneau et Le Lionnais en 1960). La Disparition (1969) est un roman écrit sans la lettre 'e'.",courant:"OULIPO / Littérature à contraintes",periode:"XXe siècle",themes:["lipogramme","contrainte créatrice","palindrome","jeux littéraires","langage comme matériau"],dialogues:[{dir:"prolonge",auteur:"Tristan Tzara",sujet:"langage comme matériau",desc:"Tzara libérait le langage par le hasard, Perec par la contrainte radicale. Deux faces d'un même refus de la fonction utilitaire du langage."},{dir:"oppose",auteur:"André Breton",sujet:"hasard vs contrainte",desc:"Le surréalisme cultive le hasard et l'automatisme ; l'OULIPO impose au contraire des règles formelles strictes. Pourtant les deux démarches révèlent que le langage peut être fin en soi."}]},
"Stephen Jay Gould":{bio:"Paléontologue et historien des sciences américain (1941–2002). Théoricien des équilibres ponctués en évolution, il propose le principe NOMA (Non-Overlapping Magisteria) sur les rapports entre science et religion.",courant:"Histoire et philosophie des sciences",periode:"XXe siècle",themes:["NOMA","équilibres ponctués","évolution","science et religion","contingence évolutive"],dialogues:[{dir:"oppose",auteur:"Freud",sujet:"religion comme illusion",desc:"Freud voit la religion comme illusion à dépasser ; Gould la voit comme magistère légitime du sens, irréductible mais distinct du magistère scientifique."},{dir:"repond",auteur:"Nietzsche",sujet:"mort de Dieu et science",desc:"Là où Nietzsche annonce la mort de Dieu et le triomphe scientifique, Gould plaide pour une coexistence pacifique des deux ordres — chacun dans son domaine."}]},
"Tzara":{bio:"Voir 'Tristan Tzara'.",courant:"",periode:"",themes:[],dialogues:[]},
"Breton":{bio:"Voir 'André Breton'.",courant:"",periode:"",themes:[],dialogues:[]},
"Perec":{bio:"Voir 'Georges Perec'.",courant:"",periode:"",themes:[],dialogues:[]},
"Russell":{bio:"Philosophe, logicien et mathématicien britannique (1872–1970). Co-auteur des Principia Mathematica avec Whitehead, prix Nobel de littérature (1950), militant pacifiste. Critique radical de la religion (« Pourquoi je ne suis pas chrétien »), théoricien du problème de l'induction et de la « théière de Russell » comme image du fardeau de la preuve.",courant:"Philosophie analytique / Empirisme logique",periode:"XIXe–XXe siècle",themes:["problème de l'induction","théière de Russell","logique","athéisme rationnel","science et religion"],dialogues:[{dir:"oppose",auteur:"Pascal",sujet:"pari et croyance",desc:"Pascal défend le pari de la foi ; Russell renverse la charge de la preuve avec sa « théière » : c'est à celui qui affirme une entité (Dieu) d'en apporter la preuve, non à celui qui la nie."},{dir:"prolonge",auteur:"Hume",sujet:"problème de l'induction",desc:"Russell radicalise la critique humienne de l'induction : aucune accumulation finie d'observations ne prouve une régularité future. Toute connaissance empirique est conjecturale."},{dir:"repond",auteur:"Popper",sujet:"science et conjecture",desc:"Popper hérite du problème russellien : si l'induction ne prouve rien, c'est la réfutabilité (et non la confirmation) qui définit la science."}]},
"William James":{bio:"Philosophe et psychologue américain (1842–1910), figure majeure du pragmatisme. Frère du romancier Henry James. Son Pragmatisme (1907) propose une conception instrumentale de la vérité : une idée est vraie en tant qu'elle est utile, opérante, féconde — non par adéquation abstraite à un réel inaccessible.",courant:"Pragmatisme",periode:"XIXe–XXe siècle",themes:["pragmatisme","vérité instrumentale","Variétés de l'expérience religieuse","flux de conscience","volonté de croire"],dialogues:[{dir:"oppose",auteur:"Descartes",sujet:"critère de vérité",desc:"Descartes fonde le vrai sur l'évidence claire et distincte ; James sur l'efficacité pratique — la vérité n'est pas une propriété statique du jugement, c'est ce qui « marche »."},{dir:"prolonge",auteur:"Nietzsche",sujet:"perspectivisme",desc:"Comme Nietzsche, James refuse la vérité métaphysique absolue — mais sans céder au relativisme : la vérité reste contraignante (par ses conséquences pratiques), seulement elle n'est plus contemplation."}]},
"James":{bio:"Voir 'William James'.",courant:"",periode:"",themes:[],dialogues:[]},
"Einstein":{bio:"Physicien théoricien germano-américain (1879–1955), auteur de la théorie de la relativité restreinte (1905) et générale (1915), prix Nobel de physique 1921 (effet photoélectrique). Au-delà de la physique, il a beaucoup écrit sur la philosophie, la paix et la « religion cosmique » — un sentiment d'émerveillement face à l'ordre rationnel du monde, sans Dieu personnel.",courant:"Physique théorique / Spinozisme moderne",periode:"XIXe–XXe siècle",themes:["relativité","religion cosmique","spinozisme","unification","déterminisme"],dialogues:[{dir:"prolonge",auteur:"Spinoza",sujet:"Dieu = Nature",desc:"Einstein revendique son spinozisme : pas de Dieu personnel mais une admiration rationnelle de l'ordre du monde — « Je crois au Dieu de Spinoza, qui se révèle dans l'harmonie de tout ce qui existe. »"},{dir:"repond",auteur:"Pascal",sujet:"sentiment religieux et science",desc:"Pour Einstein, le sentiment religieux le plus haut naît de la science elle-même — non du « Dieu sensible au cœur » de Pascal mais de la stupeur devant l'intelligibilité du cosmos."}]},
"Augustin":{bio:"Théologien et philosophe romain d'Afrique du Nord (354–430), Père et docteur de l'Église. Ses Confessions inaugurent l'autobiographie spirituelle ; sa Cité de Dieu fonde la philosophie chrétienne de l'histoire.",courant:"Patristique / Augustinisme",periode:"Antiquité tardive",themes:["foi","sentiment de finitude","amour de Dieu","libre arbitre","cité de Dieu","intériorité","temps comme distentio animi"],dialogues:[{dir:"prolonge",auteur:"Platon",sujet:"intériorité et vérité",desc:"Augustin christianise le platonisme : la vérité ne se trouve pas hors de soi mais dans l'intériorité (« in interiore homine habitat veritas »)."},{dir:"oppose",auteur:"Pascal",sujet:"finitude et grâce",desc:"Pascal hérite de l'augustinisme (Port-Royal) la centralité du sentiment de finitude et de la grâce — mais radicalise le pari face à l'incertitude rationnelle."},{dir:"oppose",auteur:"Feuerbach",sujet:"projection religieuse",desc:"Augustin affirme que l'âme cherche Dieu ; Feuerbach renverse : c'est l'homme qui projette en Dieu ses propres aspirations infinies."}]},
"Thomas d'Aquin":{bio:"Théologien et philosophe italien dominicain (1224–1274). Sa Somme théologique (1266-1274) est la grande synthèse scolastique du christianisme et de l'aristotélisme. Docteur de l'Église, dit « Docteur angélique ».",courant:"Scolastique / Thomisme",periode:"Moyen Âge",themes:["raison et foi","cinq voies","analogie","loi naturelle","philosophia ancilla theologiae","aristotélisme chrétien"],dialogues:[{dir:"prolonge",auteur:"Aristote",sujet:"métaphysique et causes",desc:"Thomas christianise Aristote : il reprend la métaphysique aristotélicienne pour démontrer rationnellement l'existence de Dieu (cinq voies)."},{dir:"oppose",auteur:"Descartes",sujet:"autonomie de la raison",desc:"Thomas subordonne la philosophie à la théologie ; Descartes affirme l'autonomie de la raison philosophique vis-à-vis de la foi."},{dir:"oppose",auteur:"Augustin",sujet:"raison et foi",desc:"Augustin : « crois pour comprendre » ; Thomas : la raison naturelle peut atteindre certaines vérités sur Dieu de manière autonome (cinq voies)."}]},
"Feuerbach":{bio:"Philosophe allemand (1804–1872), élève critique de Hegel. Sa thèse de la projection religieuse fait de la théologie une anthropologie déguisée — Dieu = essence humaine projetée hors de soi. Inspirera directement Marx.",courant:"Hégélianisme de gauche / Matérialisme anthropologique",periode:"XIXe siècle",themes:["aliénation religieuse","projection","essence humaine","matérialisme anthropologique","critique de Hegel","sensualisme"],dialogues:[{dir:"prolonge",auteur:"Hegel",sujet:"aliénation",desc:"Feuerbach hérite de Hegel le concept d'aliénation, mais le retourne contre la religion : ce n'est pas l'Esprit qui s'aliène, c'est l'homme qui s'aliène en Dieu."},{dir:"prolonge",auteur:"Marx",sujet:"critique de la religion",desc:"Marx s'inspire directement de Feuerbach — mais lui reproche de rester abstrait : il faut analyser les conditions sociales qui produisent la projection religieuse."},{dir:"oppose",auteur:"Augustin",sujet:"essence du divin",desc:"Augustin : Dieu est l'absolu vers lequel l'âme humaine s'élève ; Feuerbach renverse : Dieu est la projection des qualités humaines absolutisées."}]},
"Kierkegaard":{bio:"Philosophe et théologien danois (1813–1855), considéré comme le père de l'existentialisme. Sa pensée explore la subjectivité, l'angoisse, le désespoir et le saut de la foi face à l'absurde.",courant:"Existentialisme chrétien",periode:"XIXe siècle",themes:["foi","angoisse","saut","stades existentiels","subjectivité","absurde","chevalier de la foi"],dialogues:[{dir:"oppose",auteur:"Hegel",sujet:"subjectivité vs système",desc:"Kierkegaard refuse le système hégélien : la vérité est subjectivité, l'existence singulière échappe à la totalité dialectique."},{dir:"prolonge",auteur:"Pascal",sujet:"angoisse et foi",desc:"Kierkegaard prolonge l'augustinisme pascalien : la foi n'est pas tranquille certitude mais saut dans l'angoisse, en l'absence de toute preuve rationnelle."},{dir:"oppose",auteur:"Kant",sujet:"morale et foi",desc:"Kant subordonne la foi à la morale ; Kierkegaard affirme que la foi peut <em>suspendre</em> l'éthique générale au profit d'un absolu personnel (Abraham et Isaac)."}]},
"Durkheim":{bio:"Sociologue français (1858–1917), fondateur de la sociologie française moderne. Son analyse du sacré, du suicide et de la division du travail établit la sociologie comme science autonome.",courant:"Sociologie positiviste",periode:"XIXe–XXe siècle",themes:["sacré/profane","fait social","conscience collective","anomie","solidarité organique","forme élémentaire de la vie religieuse"],dialogues:[{dir:"prolonge",auteur:"Comte",sujet:"sociologie scientifique",desc:"Durkheim réalise le programme positiviste de Comte : faire de la sociologie une science autonome traitant les faits sociaux « comme des choses »."},{dir:"oppose",auteur:"Freud",sujet:"origine de la religion",desc:"Freud explique la religion par des dynamiques inconscientes individuelles (meurtre du père) ; Durkheim par des dynamiques collectives (la société qui s'adore elle-même)."},{dir:"prolonge",auteur:"Marx",sujet:"fonction sociale",desc:"Comme Marx, Durkheim cherche la fonction sociale de la religion — mais il l'analyse comme cohésion (solidarité), non comme aliénation à dépasser."}]},
"Bachelard":{bio:"Philosophe et épistémologue français (1884–1962), philosophe à la fois des sciences et de l'imagination poétique. Penseur de la rupture épistémologique et des obstacles à la connaissance.",courant:"Épistémologie historique / Phénoménologie poétique",periode:"XXe siècle",themes:["obstacle épistémologique","rupture épistémologique","nouvel esprit scientifique","imagination matérielle","rationalisme appliqué"],dialogues:[{dir:"prolonge",auteur:"Kuhn",sujet:"révolutions scientifiques",desc:"Bachelard anticipe Kuhn : il analyse les ruptures dans l'histoire des sciences (passage de la chimie pré-lavoisienne à la chimie moderne) avant que Kuhn ne formalise la notion de révolution paradigmatique."},{dir:"oppose",auteur:"Locke",sujet:"empirisme naïf",desc:"Locke fonde la connaissance sur l'expérience sensible immédiate ; Bachelard montre au contraire que la science exige une <em>rupture</em> avec l'expérience commune et l'opinion."},{dir:"prolonge",auteur:"Popper",sujet:"science contre l'opinion",desc:"Bachelard et Popper convergent : la science n'est pas accumulation de certitudes mais dépassement perpétuel — Bachelard par la rupture, Popper par la réfutation."}]},
"Lipovetsky":{bio:"Philosophe et sociologue français (né en 1944). Analyste des mutations de la « modernité tardive » : individualisme démocratique, hyperconsommation, culture du <em>léger</em> et de l'éphémère. Ses ouvrages — <em>L'Ère du vide</em> (1983), <em>L'Empire de l'éphémère</em> (1987), <em>Le Bonheur paradoxal</em> (2006), <em>De la légèreté</em> (2015) — diagnostiquent une société qui a remplacé les grands récits religieux et politiques par la consommation, le bien-être personnel et la recherche d'identités fluides.",courant:"Sociologie de la consommation / Hypermodernité",periode:"XXe–XXIe siècle",themes:["hyperconsommation","nouvel opium","bonheur paradoxal","individualisme démocratique","éphémère","léger"],dialogues:[{dir:"prolonge",auteur:"Marx",sujet:"opium et aliénation",desc:"Lipovetsky transpose Marx : la consommation a remplacé la religion dans la fonction d'opium — anesthésier la souffrance sociale et détourner de la révolte."},{dir:"prolonge",auteur:"Baudrillard",sujet:"société de consommation",desc:"Lipovetsky hérite de Baudrillard l'analyse de la marchandise comme signe — mais insiste davantage sur les bénéfices ambivalents (autonomie individuelle, démocratisation des plaisirs)."},{dir:"repond",auteur:"Tocqueville",sujet:"individualisme démocratique",desc:"Tocqueville craignait le repli sur la sphère privée dans les démocraties ; Lipovetsky le diagnostique à grande échelle dans l'hyperconsommation contemporaine."}]},
"Comte":{bio:"Philosophe français (1798–1857), fondateur du <strong>positivisme</strong> et inventeur du mot « sociologie ». Sa <em>loi des trois états</em> (théologique → métaphysique → positif) propose une philosophie de l'histoire où la science finit par remplacer la religion et la métaphysique dans l'explication du monde. Cours de philosophie positive (1830-1842), Système de politique positive (1851-1854).",courant:"Positivisme",periode:"XIXe siècle",themes:["positivisme","loi des trois états","hiérarchie des sciences","sociologie","religion de l'Humanité"],dialogues:[{dir:"oppose",auteur:"Stephen Jay Gould",sujet:"science et religion",desc:"Comte voit la science remplacer la religion (loi des trois états) ; Gould plaide au contraire pour une coexistence des magistères (NOMA)."},{dir:"prolonge",auteur:"Durkheim",sujet:"sociologie scientifique",desc:"Durkheim réalise le programme positiviste de Comte en fondant une sociologie autonome traitant les faits sociaux « comme des choses »."},{dir:"oppose",auteur:"Bachelard",sujet:"linéarité du progrès",desc:"Comte décrit une marche linéaire vers le savoir positif ; Bachelard montre que la science avance par <em>ruptures</em> avec ses propres états antérieurs, non par accumulation."}]},
"Tisseron":{bio:"Psychiatre et psychanalyste français (né en 1948), spécialiste des images, des écrans et de la subjectivité contemporaine. Ses travaux portent sur l'<em>intimité surexposée</em> et la mutation narcissique du sujet à l'ère des réseaux sociaux. Ouvrages : <em>L'Intimité surexposée</em> (2001), <em>Subir ou choisir</em> (2008), <em>3-6-9-12 : apprivoiser les écrans et grandir</em> (2013).",courant:"Psychanalyse / Psychologie des médias",periode:"XXe–XXIe siècle",themes:["narcissisme contemporain","intimité surexposée","réseaux sociaux","besoin de reconnaissance","écrans"],dialogues:[{dir:"prolonge",auteur:"Freud",sujet:"évolution du sujet",desc:"Tisseron prolonge Freud en montrant que le sujet structuré par Œdipe (loi/culpabilité) a cédé la place à un sujet narcissique (visibilité/reconnaissance)."},{dir:"repond",auteur:"Lipovetsky",sujet:"hyperindividualisme",desc:"Tisseron et Lipovetsky convergent : l'individu contemporain est moins divisé par les anciennes structures (religion, loi, classe) que par la quête de reconnaissance et l'éphémère."}]},
"Leguil":{bio:"Philosophe et psychanalyste française (née en 1974), professeure à Paris VIII. Lectrice de Freud et Lacan, elle analyse les figures contemporaines de la subjectivité — identités, traumatisme, féminisme, toxicité. Ouvrages : <em>« Je », une traversée des identités</em> (2018), <em>Céder n'est pas consentir</em> (2021), <em>L'Ère du toxique</em> (2024).",courant:"Psychanalyse lacanienne / Philosophie clinique",periode:"XXIe siècle",themes:["traumatisme","subjectivation","identités","consentement","toxicité"],dialogues:[{dir:"prolonge",auteur:"Freud",sujet:"trauma et subjectivation",desc:"Leguil prolonge la pensée freudienne du trauma (Au-delà du principe de plaisir) en l'appliquant aux violences contemporaines (attentats, agressions, deuils brutaux)."},{dir:"repond",auteur:"Tisseron",sujet:"sujet contemporain",desc:"Comme Tisseron, Leguil refuse la psychanalyse close sur ses propres concepts : il faut penser les nouvelles façons dont le sujet contemporain souffre — narcissisme blessé, traumatismes répétés, identités fragiles."}]},
"Ansermet":{bio:"Pédopsychiatre et psychanalyste suisse (né en 1949), professeur honoraire à l'université de Genève. Spécialiste des liens entre psychanalyse, neurosciences et philosophie. Ses travaux croisent Freud, Lacan et les sciences cognitives. Ouvrages : <em>À chacun son cerveau</em> (avec Pierre Magistretti, 2004), <em>La Fabrication des enfants</em> (2015).",courant:"Psychanalyse / Neuropsychanalyse",periode:"XXe–XXIe siècle",themes:["plasticité neuronale","pulsion de mort","origine de la violence","périnatalité","neurosciences"],dialogues:[{dir:"prolonge",auteur:"Freud",sujet:"pulsion de mort et guerre",desc:"Ansermet reprend l'hypothèse freudienne (Pourquoi la guerre ?, 1933) à la lumière des neurosciences : la pulsion d'agression a des bases neurobiologiques, mais reste subjectivable par le travail psychique."}]},
"Linhart":{bio:"Sociologue française du travail (née en 1947), directrice de recherche émérite au CNRS. Spécialiste de la transformation des organisations du travail et du management contemporain. Ouvrages : <em>La Modernisation des entreprises</em> (1991), <em>Travailler sans les autres ?</em> (2009), <em>La Comédie humaine du travail</em> (2015).",courant:"Sociologie du travail",periode:"XXe–XXIe siècle",themes:["taylorisme","individualisation","management","souffrance au travail","évaluation"],dialogues:[{dir:"prolonge",auteur:"Marx",sujet:"aliénation contemporaine",desc:"Linhart prolonge l'analyse marxiste de l'aliénation en montrant comment le management moderne individualise la contrainte au lieu de la supprimer."},{dir:"repond",auteur:"Nietzsche",sujet:"travail comme contrôle",desc:"Le diagnostic nietzschéen (« le travail comme meilleure des polices ») se vérifie aujourd'hui sous forme d'auto-contrôle managérial."}]},
"Méda":{bio:"Sociologue et philosophe française (née en 1962), professeure à Paris-Dauphine. Travaux sur le sens du travail, le PIB et les indicateurs de richesse, la transition écologique. Ouvrages : <em>Le Travail. Une valeur en voie de disparition ?</em> (1995), <em>La Mystique de la croissance</em> (2013), <em>Reconvertir l'économie</em> (2024).",courant:"Sociologie du travail / Économie écologique",periode:"XXe–XXIe siècle",themes:["sens du travail","transition écologique","richesse","temps libre","reconversion"],dialogues:[{dir:"prolonge",auteur:"Hannah Arendt",sujet:"distinction travail/œuvre/action",desc:"Méda reprend la distinction arendtienne pour penser la place excessive accordée au travail (labor) dans nos sociétés."},{dir:"repond",auteur:"Lafargue",sujet:"culte du travail",desc:"Comme Lafargue (Le Droit à la paresse), Méda interroge l'évidence du « travail-valeur » centrale de nos sociétés."}]},
"Perez":{bio:"Économiste française (née en 1972), enseignante à Paris I. Spécialiste de l'économie du travail, des conditions d'emploi et des transformations technologiques. Co-autrice avec Thomas Coutrot de <em>Redonner du sens au travail. Une aspiration révolutionnaire</em> (2022).",courant:"Économie du travail",periode:"XXIe siècle",themes:["sens du travail","IA et emploi","conditions de travail","concertation","démocratie économique"],dialogues:[{dir:"prolonge",auteur:"Simondon",sujet:"culture technique",desc:"Perez prolonge Simondon : la maîtrise des technologies passe par leur compréhension et leur appropriation collective, non par leur subissement."}]},
"Palier":{bio:"Politiste français (né en 1965), directeur de recherche CNRS à Sciences Po. Spécialiste comparatif des États-providence et des politiques sociales en Europe. Critique du « modèle français du low cost ». Ouvrages : <em>Gouverner la sécurité sociale</em> (2002), <em>La Réforme des systèmes de santé</em> (2017), <em>Que sait-on du travail ?</em> (dir., 2023).",courant:"Politique sociale comparée",periode:"XXe–XXIe siècle",themes:["modèle social","low cost","qualité du travail","État-providence","comparaison européenne"],dialogues:[{dir:"prolonge",auteur:"Méda",sujet:"qualité du travail",desc:"Palier et Méda convergent : la quantité d'emploi ne suffit pas — il faut un travail de qualité, doté de sens et de protection."}]},
"Barthes":{bio:"Sémiologue, critique et théoricien de la littérature français (1915–1980). Héritier de Saussure, il étend l'analyse des signes à toute la culture (Mythologies, 1957) avant d'explorer, dans une écriture plus intime, le sujet et ses affects (Fragments d'un discours amoureux, 1977 ; La Chambre claire, 1980).",courant:"Structuralisme / Sémiologie",periode:"XXe siècle",themes:["sémiologie","mythologies","discours amoureux","temps vécu de l'attente","écriture"],dialogues:[{dir:"prolonge",auteur:"Saussure",sujet:"science des signes",desc:"Barthes étend la linguistique de Saussure à tous les systèmes de signification (mode, publicité, mythes modernes) : la sémiologie devient une lecture critique de la culture."},{dir:"prolonge",auteur:"Bergson",sujet:"temps vécu",desc:"L'attente amoureuse décrite par Barthes illustre la durée bergsonienne : un temps qualitatif, étiré ou contracté par l'affect, irréductible au temps mesuré de l'horloge."}]},
"Hartmut Rosa":{bio:"Sociologue et philosophe allemand (né en 1965), héritier de la théorie critique de l'École de Francfort. Il diagnostique l'<strong>accélération sociale</strong> comme trait central de la modernité tardive (Accélération, 2005) et lui oppose la <strong>résonance</strong> — un rapport vibrant et réciproque au monde — comme remède à l'aliénation contemporaine (Résonance, 2016).",courant:"Théorie critique / Sociologie",periode:"XXe–XXIe siècle",themes:["accélération sociale","résonance","aliénation","modernité tardive","rapport au monde"],dialogues:[{dir:"prolonge",auteur:"Marx",sujet:"aliénation",desc:"Rosa renouvelle la critique marxiste : ce n'est plus seulement le travail qui aliène, mais l'accélération généralisée, qui nous prive d'un rapport vivant — résonant — au monde, aux autres et à soi."},{dir:"oppose",auteur:"Sénèque",sujet:"maîtrise du temps",desc:"Sénèque croit qu'une sagesse individuelle suffit à bien user du temps ; Rosa montre que l'accélération est une contrainte sociale systémique qu'aucune discipline personnelle ne désamorce vraiment."}]},
"Sénèque":{bio:"Philosophe stoïcien, dramaturge et homme d'État romain (v. 4 av. J.-C.–65 ap. J.-C.), précepteur de Néron. Ses traités et ses Lettres à Lucilius font du stoïcisme une sagesse pratique : bien user du temps, se rendre maître de ses jugements, habiter le présent (De la brièveté de la vie).",courant:"Stoïcisme",periode:"Antiquité romaine",themes:["brièveté de la vie","usage du temps","présent","tranquillité de l'âme","sagesse stoïcienne"],dialogues:[{dir:"prolonge",auteur:"Épictète",sujet:"sagesse stoïcienne",desc:"Sénèque et Épictète partagent le stoïcisme romain : la sagesse consiste à distinguer ce qui dépend de nous (nos jugements, l'usage de notre temps) de ce qui n'en dépend pas."},{dir:"prolonge",auteur:"Pascal",sujet:"agitation et fuite de soi",desc:"Sénèque dénonce les occupations vaines où l'on dilapide sa vie ; Pascal radicalisera l'analyse avec le divertissement — l'agitation comme fuite devant soi-même."}]},
"Camus":{bio:"Écrivain, dramaturge et philosophe français (1913–1960), prix Nobel de littérature 1957. Penseur de l'<strong>absurde</strong> (Le Mythe de Sisyphe, 1942) puis de la <strong>révolte</strong> (L'Homme révolté, 1951), il refusait l'étiquette d'« existentialiste ». Aussi romancier (L'Étranger, 1942 ; La Peste, 1947).",courant:"Philosophie de l'absurde",periode:"XXe siècle",themes:["absurde","suicide","révolte","Sisyphe","sens de l'existence"],dialogues:[{dir:"oppose",auteur:"Pascal",sujet:"l'espérance face au tragique",desc:"Là où Pascal mise sur Dieu et voit dans le divertissement une fuite, Camus refuse tout « saut » dans l'espérance religieuse : il faut vivre l'absurde avec lucidité, par la révolte, sans au-delà."},{dir:"prolonge",auteur:"Nietzsche",sujet:"affirmation tragique de la vie",desc:"Comme Nietzsche avec l'amor fati et l'éternel retour, Camus invite à dire oui à une existence sans arrière-monde : « Il faut imaginer Sisyphe heureux. »"}]},
"Sextus Empiricus":{bio:"Médecin et philosophe grec (v. 160–210), principal témoin du <strong>scepticisme pyrrhonien</strong>. Ses <em>Esquisses pyrrhoniennes</em> exposent les « tropes » (modes) qui mènent à la <strong>suspension du jugement</strong> (<em>épochè</em>) : faute de pouvoir trancher entre thèses opposées, le sceptique s'abstient — et y gagne la tranquillité de l'âme (<em>ataraxie</em>).",courant:"Scepticisme",periode:"Antiquité grecque",themes:["scepticisme","tropes d'Agrippa","suspension du jugement","époché","ataraxie"],dialogues:[{dir:"oppose",auteur:"Aristote",sujet:"la certitude des principes",desc:"Aristote fonde la science sur des principes premiers, certains par eux-mêmes ; Sextus objecte la régression à l'infini (tout fondement en réclame un autre) et le cercle (diallèle) — d'où la suspension du jugement."},{dir:"oppose",auteur:"Descartes",sujet:"le doute",desc:"Le doute sceptique est un point d'arrêt (on suspend l'assentiment) ; le doute cartésien, lui, est méthodique et provisoire — un moyen d'atteindre une première certitude (le cogito)."}]},
"Leibniz":{bio:"Philosophe, mathématicien et savant allemand (1646–1716), co-inventeur du calcul infinitésimal. <strong>Rationaliste</strong>, il fonde tout raisonnement sur deux grands principes : la <strong>non-contradiction</strong> et la <strong>raison suffisante</strong> (« rien n'est sans raison »). Auteur de la <em>Monadologie</em> (1714) et de la thèse du « meilleur des mondes possibles », que Voltaire raillera dans <em>Candide</em>.",courant:"Rationalisme",periode:"XVIIe–XVIIIe siècle",themes:["principe de raison suffisante","non-contradiction","monade","calcul","meilleur des mondes"],dialogues:[{dir:"prolonge",auteur:"Descartes",sujet:"le rationalisme",desc:"Leibniz prolonge le rationalisme cartésien mais ne se contente pas de l'évidence : tout ce qui est vrai a une raison — la raison suffisante gouverne les vérités de fait comme la non-contradiction gouverne les vérités de raison."},{dir:"oppose",auteur:"Hume",sujet:"la causalité",desc:"Pour Leibniz tout fait a une raison nécessaire et déterminée ; Hume objecte que le lien de cause à effet n'est pas saisi par la raison mais né de l'habitude."}]}
};

/* ── D. DONNÉES — GLOSSAIRE DE CONCEPTS ─────────────────────────────
   const CONCEPTS : ~70 concepts philosophiques clés, distincts des notions.
   Accessibles via l'onglet "Concepts" de la sidebar.
   Chaque concept contient :
     id       → identifiant unique (utilisé pour les liens .cterm)
     term     → terme affiché
     cat      → catégorie (Linguistique, Épistémologie, Éthique…)
     def      → définition HTML
     auteur   → auteur(s) associé(s) (chaîne, peut contenir " / ")
     tensions → paires de tensions conceptuelles ["A ≠ B", …]
     notions  → clés de D auxquelles ce concept est rattaché
   Les concepts dont l'id commence par "notion-" sont des raccourcis
   qui redirigent directement vers la notion du programme correspondante.  */
const CONCEPTS=[
{new:true,id:'existentialisme',term:'Existentialisme',cat:'Ontologie',def:"Doctrine selon laquelle l'être humain n'est pas déterminé d'avance par une <strong>essence</strong>, mais <strong>libre et responsable</strong> de son existence : « l'<em>existence précède l'essence</em> » (Sartre). On distingue l'existentialisme <strong>chrétien</strong> (Jaspers, Gabriel Marcel) et l'existentialisme <strong>athée</strong> (Heidegger, Sartre) ; leur point commun est de faire de l'homme un projet qui se choisit lui-même. <em>Ex.</em> la « mauvaise foi » : se prendre pour une chose déterminée afin de fuir l'angoisse de la liberté.",auteur:"Sartre",notions:["conscience","liberte","verite"],relations:[{to:'absurde',type:'prolonge',desc:"L'absurde de Camus prolonge le constat d'un monde sans essence ni sens donnés d'avance."},{type:'distinction',desc:"« L'existence précède l'essence » ≠ essentialisme, pour qui une nature humaine serait fixée d'avance."}]},
{new:true,id:'solipsisme',term:'Solipsisme',cat:'Métaphysique',def:"Thèse selon laquelle il n'y aurait, pour le sujet pensant, d'autre réalité que <strong>lui-même</strong> : le monde et autrui ne seraient que des représentations de ma propre conscience. Position limite née du <em>doute</em> et du primat du « je pense », elle rend l'existence d'autrui indémontrable. <em>Ex.</em> poussé à bout, le cogito risque d'enfermer le sujet en lui-même.",auteur:"",notions:["conscience"],relations:[{to:'intersubjectivite',type:'distinction',desc:"Le monde se réduit à ma conscience individuelle ≠ intersubjectivité, où la réalité se constitue entre des consciences qui se reconnaissent."}]},
{new:true,id:'absurde',term:'Absurde',cat:'Existentialisme',def:"Chez <strong>Camus</strong>, l'absurde n'est ni dans l'homme ni dans le monde, mais dans leur <em>rencontre</em> : le divorce entre l'exigence humaine de sens et le « silence déraisonnable du monde ». Il ne commande ni le suicide ni l'espérance d'un au-delà, mais la <strong>révolte</strong> — vivre lucidement, sans appel. <em>Ex.</em> Sisyphe, condamné à rouler éternellement son rocher : « Il faut imaginer Sisyphe heureux. »",auteur:"Camus",notions:["temps","bonheur"]},
{new:true,id:'scepticisme',term:'Scepticisme',cat:'Épistémologie',def:"Position selon laquelle aucune connaissance certaine n'est possible : « à tout argument s'oppose un argument de force égale » (<em>isosthénie</em>). Le scepticisme <strong>pyrrhonien</strong> (Sextus Empiricus) en tire la <strong>suspension du jugement</strong> (<em>épochè</em>), source de tranquillité de l'âme. À distinguer du doute <em>méthodique</em> de Descartes, provisoire et orienté vers la certitude. <em>Ex.</em> les cinq tropes d'Agrippa.",auteur:"Sextus Empiricus",notions:["raison","verite","science"]},
{new:true,id:'dogmatisme',term:'Dogmatisme',cat:'Épistémologie',def:"Attitude qui pose des thèses comme certaines <strong>sans les examiner</strong> ni admettre la discussion ; le dogmatique « part de quelque chose qu'il n'établit pas » (Sextus). En ce sens, vouloir avoir raison à tout prix est dogmatique. À distinguer du <em>dogmatisme social</em> — ces croyances communes admises « sans les discuter » que Tocqueville juge nécessaires à toute vie collective. S'oppose à l'esprit critique.",auteur:"",notions:["raison","verite","religion"]},
{new:true,id:'obstacle-epistemologique',term:'Obstacle épistémologique',cat:'Épistémologie',def:"Chez <strong>Bachelard</strong>, ce qui, dans l'esprit même, freine la connaissance : opinions, images et intuitions premières séduisantes mais fausses. On ne connaît pas en s'ajoutant à un savoir vierge, mais « <strong>contre</strong> une connaissance antérieure », en la détruisant — d'où la nécessité d'une « psychanalyse de la raison ». <em>Ex.</em> l'intuition qui prête une « activité » au corps qui flotte.",auteur:"Bachelard",notions:["raison","science"]},
{new:true,id:'falsifiabilite',term:'Falsifiabilité (réfutabilité)',cat:'Épistémologie',def:"Critère de scientificité chez <strong>Popper</strong> : une théorie est scientifique non parce qu'elle est <em>vérifiable</em>, mais parce qu'elle est <strong>réfutable</strong> — elle interdit certains faits et s'expose donc à un test qui pourrait la démentir. Une thèse qu'aucune observation ne pourrait contredire (qu'on « immunise ») n'est pas scientifique. La science avance par conjectures et réfutations.",auteur:"Popper",notions:["science","raison","verite"]},
{new:true,id:'sophisme',term:'Sophisme',cat:'Logique',def:"Raisonnement qui a l'<strong>apparence</strong> de la rigueur logique mais qui est trompeur — soit que ses prémisses soient fausses, soit par une faille cachée de l'inférence. Aristote l'appelle raisonnement <em>éristique</em>. La validité de la <em>forme</em> ne garantit jamais la vérité : on peut « bien » déduire à partir du faux. <em>Ex.</em> « Tous les animaux sont des chiens… ».",auteur:"Aristote",notions:["raison","verite"]},
{new:true,id:'syllogisme',term:'Syllogisme',cat:'Logique',def:"Raisonnement <strong>déductif</strong> formalisé par <strong>Aristote</strong> : « un discours dans lequel, certaines choses étant posées, une autre en résulte nécessairement ». Ex. « Tout homme est mortel ; or Socrate est un homme ; donc Socrate est mortel. » Il est <em>démonstratif</em> si ses prémisses sont vraies et premières, <em>dialectique</em> si elles sont seulement probables, <em>éristique</em> si elles ne le paraissent qu'en apparence.",auteur:"Aristote",notions:["raison"]},
{id:'langage-def',term:'Langage',cat:'Linguistique',def:'Tout système ou ensemble de signes permettant l\'expression ou la communication. Le langage humain se distingue par la <strong>double articulation</strong> (monèmes + phonèmes) — il peut produire un nombre illimité d\'énoncés avec ~40 sons.',auteur:'Saussure',tensions:['Langage (général) ≠ Langue (propre à une communauté)','Langage ≠ Parole (acte individuel)','Signal ≠ Symbole (Benveniste)'],notions:['langage']},
{id:'langue',term:'Langue',cat:'Linguistique',def:'Instrument de communication propre à une communauté humaine. Produit social de la faculté du langage — ensemble institué et stable de symboles verbaux ou écrits. Système de différences : chaque terme n\'a de valeur que par rapport aux autres.',auteur:'Saussure',tensions:['Langue ≠ Parole (social vs individuel)','Langue ≠ Langage (particulier vs général)'],notions:['langage']},
{id:'parole',term:'Parole',cat:'Linguistique',def:'Acte individuel par lequel s\'exerce la fonction linguistique — appropriation d\'une langue par un individu. Manière singulière dont chacun s\'empare d\'une langue commune. Fondement de la créativité linguistique (néologismes, style).',auteur:'Saussure',tensions:['Parole ≠ Langue (individuel vs social)','Parole créatrice ≠ code figé'],notions:['langage','art']},
{id:'signifiant-signifie',term:'Signifiant / Signifié',cat:'Linguistique',def:'Le <strong>signifiant</strong> est l\'image acoustique (le son du mot). Le <strong>signifié</strong> est le concept mental associé. Lien <strong>arbitraire</strong> (pas de nécessité naturelle entre le son "arbre" et l\'idée d\'arbre) mais <strong>inséparable</strong> (comme recto/verso d\'une feuille).',auteur:'Saussure',tensions:['Signifiant ≠ Référent (le mot ≠ la chose réelle)','Lien arbitraire → mais il faut l\'apprendre'],notions:['langage']},
{id:'referent',term:'Référent',cat:'Linguistique',def:'L\'objet, phénomène ou être de la réalité objective que désigne le signe linguistique. La licorne : signifiant (le son) + signifié (le concept d\'animal à corne unique) mais <em>référent absent</em> — preuve que le langage peut fonctionner sans ancrage réel.',auteur:'Saussure',tensions:['Signe sans référent → le langage dépasse la pure utilité','Référent imaginaire → fiction, mythe, abstraction'],notions:['langage','art']},
{id:'signal-symbole',term:'Signal / Symbole',cat:'Linguistique',def:'Le <strong>signal</strong> est un fait physique lié à un autre par rapport naturel ou conventionnel — l\'animal y réagit par réflexe conditionné (Pavlov). Le <strong>symbole</strong> est institué par l\'homme et doit être interprété : l\'animal exprime ses émotions, il ne les dénomme pas.',auteur:'Benveniste',tensions:['Animal = signal / Homme = signal ET symbole','Expression (animal) ≠ dénomination (homme)'],notions:['langage','nature','conscience']},
{id:'logos-phone',term:'Logos / Phone',cat:'Linguistique',def:'<strong>Phone</strong> : la voix, cri, expression sonore des émotions — partagée avec l\'animal. <strong>Logos</strong> : parole rationnelle, discours structuré permettant de délibérer du juste et de l\'injuste. Aristote : seul l\'homme possède le logos, ce qui fait de lui un <em>animal politique</em>. Cassin : logos = à la fois raison ET discours (intraduisible).',auteur:'Aristote / Cassin',tensions:['Phone → expression / Logos → argumentation et délibération','Logos ≠ raison pure (il est aussi rhétorique, persuasion)'],notions:['langage','raison','etat']},
{id:'double-articulation',term:'Double articulation',cat:'Linguistique',def:'Propriété distinctive du langage humain (Martinet) : (1) articulation en <strong>monèmes</strong> (unités de son ET de sens minimales) ; (2) articulation en <strong>phonèmes</strong> (unités de son pur, sans sens, en nombre fini ~40). Combinatoire illimitée à partir d\'éléments finis.',auteur:'Martinet / Saussure',tensions:['Double articulation → richesse infinie ≠ code animal (nombre fini de messages)'],notions:['langage']},
{id:'performatif',term:'Performatif / Constatif',cat:'Philosophie du langage',def:'Austin : un énoncé <strong>constatif</strong> décrit et peut être vrai/faux ("Il pleut"). Un énoncé <strong>performatif</strong> <em>accomplit</em> ce qu\'il énonce — dire c\'est faire. "Je vous déclare mari et femme" : la réalité est modifiée par la parole. Conditions de félicité : statut du locuteur, reconnaissance institutionnelle.',auteur:'Austin',tensions:['Performatif ≠ Constatif (action vs description)','Langage comme moyen ≠ Langage comme action constitutive du réel'],notions:['langage','travail','etat']},
{id:'novlangue',term:'Novlangue',cat:'Politique / Linguistique',def:'Dans <em>1984</em> d\'Orwell : langue artificielle réduisant le vocabulaire pour réduire le pensable. Si un mot disparaît, la pensée correspondante disparaît. Exemple : "crimepensée" remplace toute idée hérétique — un seul mot empêche d\'articuler une pensée complexe.',auteur:'Orwell',tensions:['Novlangue → le langage peut supprimer la liberté de pensée','Langue appauvrie ≠ langue enrichissante (Cassin)'],notions:['langage','liberte','etat']},
{id:'fonctions-langage',term:'6 fonctions du langage',cat:'Linguistique',def:'Jakobson : <strong>émotive</strong> (je — interjections), <strong>conative</strong> (tu — impératif, persuasion), <strong>référentielle</strong> (il — décrire le contexte), <strong>phatique</strong> (maintenir le contact), <strong>métalinguistique</strong> (parler du code), <strong>poétique</strong> (le message pour lui-même — rythme, sonorités). Une phrase combine rarement une seule fonction.',auteur:'Jakobson',tensions:['Communication ≠ seule fonction','Fonction poétique → langage comme fin en soi ≠ moyen'],notions:['langage','art']},
{id:'injonction-paradoxale',term:'Injonction paradoxale',cat:'Pragmatique',def:'"Soyez spontané !" — contradiction performative : pour obéir, il faudrait être spontané par obéissance, donc sans spontanéité. Watzlawick : ces paradoxes sont au cœur de la communication pathologique (double bind de Bateson). Révèlent les limites structurelles de la communication.',auteur:'Watzlawick',tensions:['Le langage peut se retourner contre sa fonction de communication','Injonction paradoxale → souffrance psychique, névrose'],notions:['langage','conscience']},
{id:'cogito',term:'Cogito',cat:'Épistémologie',def:'<em>Cogito ergo sum</em> — "je pense donc je suis" (Descartes, <em>Méditations métaphysiques</em>, 1641). Première certitude après le doute hyperbolique. Fondement du rationalisme moderne. Critiques : Nietzsche ("ça pense"), Hume (pas de moi stable), Freud (l\'inconscient contredit la transparence du cogito).',auteur:'Descartes',tensions:['Cogito → conscience transparente à elle-même','Freud : le moi n\'est pas maître en sa propre maison — cogito illusoire ?'],notions:['conscience','raison','liberte','langage']},
{id:'mauvaise-foi',term:'Mauvaise foi',cat:'Existentialisme',def:'Sartre : attitude qui consiste à se croire déterminé comme une chose, à nier sa liberté radicale en "jouant un rôle". Exemple : le garçon de café qui "joue" à être garçon de café. ≠ mensonge (on se ment à soi-même conscient de sa liberté).',auteur:'Sartre',tensions:['Mauvaise foi ≠ mensonge (auto-illusion)','Mauvaise foi ↔ authenticité (assumer sa liberté)'],notions:['conscience','liberte']},
{id:'dialectique-maitre-esclave',term:'Dialectique Maître/Esclave',cat:'Idéalisme',def:'Hegel (<em>Phénoménologie de l\'Esprit</em>, 1807) : la conscience de soi ne s\'obtient que dans la <strong>reconnaissance</strong> par une autre conscience. Le maître exige la reconnaissance de l\'esclave qu\'il nie — reconnaissance creuse. L\'esclave se réalise dans le travail et accède à une vraie conscience de soi.',auteur:'Hegel',tensions:['Domination → reconnaissance vide','Travail de l\'esclave → émancipation paradoxale'],notions:['conscience','liberte','travail']},
{id:'determinisme',term:'Déterminisme',cat:'Métaphysique',def:'Doctrine : tout événement, y compris les actes humains, est la conséquence nécessaire de causes antérieures. D\'Holbach : l\'homme est "une machine". Spinoza et Engels : compatibilisme — la liberté est la nécessité comprise. Différent du fatalisme (qui nie l\'action).',auteur:"D'Holbach / Spinoza / Engels",tensions:['Déterminisme strict ≠ libre arbitre','Compatibilisme : déterminisme + liberté possible'],notions:['liberte','conscience','nature','science']},
{id:'libre-arbitre',term:'Libre arbitre',cat:'Métaphysique',def:'Capacité à choisir librement entre plusieurs possibles, indépendamment de toute détermination. Descartes : la liberté est "la plus grande perfection de l\'homme". Sartre : "nous sommes condamnés à être libres". Remis en cause par le déterminisme et la psychanalyse (inconscient).',auteur:'Descartes / Sartre',tensions:['Libre arbitre ≠ liberté spinoziste (nécessité comprise)','Libre arbitre ≠ caprice / indéterminisme'],notions:['liberte','conscience','devoir']},
{id:'alienation',term:'Aliénation',cat:'Philosophie sociale',def:'Marx : le travailleur est étranger à son produit (qui lui échappe), à son activité (imposée), à son espèce (déshumanisé), à ses semblables (concurrence). Hegel : l\'esprit s\'aliène dans le monde avant de se retrouver. Simondon : aliénation par méconnaissance des machines.',auteur:'Marx / Hegel / Simondon',tensions:['Aliénation économique (Marx) ≠ aliénation de l\'Esprit (Hegel)','Travail aliéné ≠ travail libre (créateur)'],notions:['travail','liberte','conscience','technique']},
{id:'labor-work-action',term:'Labor / Work / Action',cat:'Philosophie politique',def:'Arendt (<em>Condition de l\'homme moderne</em>, 1958) : <strong>Labor</strong> (cycle biologique, sans durée — corvée) ; <strong>Work/Œuvre</strong> (fabrication d\'un monde durable — artisan, artiste) ; <strong>Action</strong> (activité politique libre entre égaux — seule vraiment humaine). La modernité réduit tout au labor.',auteur:'Arendt',tensions:['Labor (animal laborans) ≠ Work (homo faber) ≠ Action (politique)','Modernité : tout devient labor — appauvrissement'],notions:['travail','art','liberte','etat']},
{id:'plus-value',term:'Plus-value',cat:'Économie politique',def:'Marx : écart entre la valeur produite par le travailleur et le salaire reçu. Fondement de l\'exploitation capitaliste. Journée divisée en <strong>temps nécessaire</strong> (reproduit le salaire) et <strong>surtravail</strong> (produit la plus-value pour le capitaliste).',auteur:'Marx',tensions:['Plus-value → le travail crée la valeur mais le travailleur ne la reçoit pas','≠ profit (qui peut avoir d\'autres sources)'],notions:['travail','justice']},
{id:'contrat-social',term:'Contrat social',cat:'Philosophie politique',def:'Théorie de la légitimité politique par accord entre individus. <strong>Hobbes</strong> : abandon total des droits au souverain absolu pour la sécurité. <strong>Locke</strong> : contrat révocable si les droits naturels sont violés. <strong>Rousseau</strong> : aliénation à la volonté générale — "en obéissant à la loi qu\'on s\'est prescrite, on est libre".',auteur:'Hobbes / Locke / Rousseau',tensions:['Sécurité (Hobbes) ≠ droits naturels (Locke) ≠ liberté civile (Rousseau)','Contrat fictif ou historique ?'],notions:['etat','liberte','justice']},
{id:'volonte-generale',term:'Volonté générale',cat:'Philosophie politique',def:'Rousseau : volonté du corps politique visant le bien commun. ≠ "volonté de tous" (somme des intérêts particuliers). Inaliénable et indivisible. Base de la souveraineté populaire. Peut légitimer la contrainte de l\'individu au nom du bien commun.',auteur:'Rousseau',tensions:['Volonté générale ≠ volonté de tous (arithmétique)','Peut-elle justifier la tyrannie de la majorité ?'],notions:['etat','liberte','justice']},
{id:'etat-de-nature',term:'État de nature',cat:'Philosophie politique',def:'Fiction philosophique : condition humaine avant tout ordre politique. <strong>Hobbes</strong> : guerre de tous contre tous ("vie solitaire, pauvre, brutale et brève"). <strong>Locke</strong> : état pacifique mais fragile. <strong>Rousseau</strong> : bonheur naturel, égalité, pas encore corrompu par la propriété.',auteur:'Hobbes / Locke / Rousseau',tensions:['Violent (Hobbes) ≠ Pacifique (Locke) ≠ Heureux (Rousseau)','Fiction conceptuelle ≠ fait historique'],notions:['etat','nature','liberte']},
{id:'ataraxie',term:'Ataraxie',cat:'Éthique antique',def:'Terme épicurien : état de paix de l\'âme, absence de trouble et d\'inquiétude. Joint à l\'<strong>aponie</strong> (absence de douleur corporelle), elle constitue le bonheur épicurien. S\'obtient par le calcul des désirs : désirs naturels et nécessaires > naturels non nécessaires > vains.',auteur:'Épicure',tensions:['Ataraxie (paix, repos) ≠ eudaimonia (activité, vertu — Aristote)','Ataraxie → bonheur passif ≠ bonheur actif'],notions:['bonheur']},
{id:'eudaimonia',term:'Eudaimonia',cat:'Éthique antique',def:'Terme aristotélicien traduit par "bonheur" ou "félicité". Littéralement : "avoir un bon démon". Pour Aristote, c\'est l\'<strong>activité de l\'âme conforme à la vertu</strong> la plus haute. Ce n\'est pas un état passif mais une <em>energeia</em> (actualisation de ses capacités).',auteur:'Aristote',tensions:['Eudaimonia (activité) ≠ ataraxie (repos — Épicure)','Eudaimonia ≠ hedone (plaisir sensoriel pur)'],notions:['bonheur','travail']},
{id:'habitus',term:'Habitus',cat:'Sociologie',def:'Bourdieu : système de dispositions durables acquises dans la socialisation — façons d\'agir, de penser, de percevoir incorporées. Génère des pratiques adaptées aux structures sociales sans calcul conscient. Le goût esthétique est un habitus de classe.',auteur:'Bourdieu',tensions:['Habitus → déterminisme social mais non absolu (il peut être transformé)','Habitus ≠ habitude (structure profonde vs comportement répété)'],notions:['bonheur','art','nature','liberte']},
{id:'imperatif-categorique',term:'Impératif catégorique',cat:'Éthique kantienne',def:'Kant : commandement moral qui s\'impose inconditionnellement, sans égard aux conséquences ou aux désirs. Trois formulations : (1) <em>Universalisation</em> : "Agis seulement selon la maxime qui peut devenir loi universelle" ; (2) <em>Humanité comme fin</em> ; (3) <em>Législation universelle</em>.',auteur:'Kant',tensions:['Impératif catégorique ≠ hypothétique ("si tu veux X, fais Y")','Devoir inconditionnel ≠ utilitarisme (Mill) — les conséquences ne comptent pas'],notions:['devoir','liberte','justice']},
{id:'banalite-du-mal',term:'Banalité du mal',cat:'Philosophie politique',def:'Arendt (<em>Eichmann à Jérusalem</em>, 1963) : le mal radical ne suppose pas de monstruosité mais l\'<strong>absence de pensée</strong> — obéissance sans jugement. Eichmann exécutait des ordres sans réfléchir à leur sens moral. La pensée est une condition de résistance au mal.',auteur:'Arendt',tensions:['Mal banal (absence de pensée) ≠ mal radical (intentions diaboliques)','Obéissance sans pensée ≠ devoir moral kantien (autonomie)'],notions:['devoir','etat','conscience']},
{id:'ready-made',term:'Ready-made',cat:'Art contemporain',def:'Duchamp (<em>La Fontaine</em>, 1917) : objet manufacturé ordinaire promu au statut d\'œuvre d\'art par désignation institutionnelle. Ce n\'est pas le geste technique qui crée l\'œuvre mais l\'acte de désignation. O\'Doherty : c\'est l\'espace de la galerie qui fait l\'art.',auteur:'Duchamp',tensions:['Ready-made → l\'art ≠ maîtrise technique','Valeur esthétique ≠ valeur commerciale','Art institutionnel ≠ art comme expression singulière'],notions:['art','travail','technique']},
{id:'genie',term:'Génie',cat:'Esthétique',def:'Kant (<em>Critique de la faculté de juger</em>, 1790) : talent de produire ce dont on ne peut donner de règle déterminée. L\'originalité est sa première qualité. Ses productions doivent être exemplaires. Nietzsche critique le mythe du génie inné : c\'est l\'ignorance et la paresse qui font croire au "don".',auteur:'Kant / Nietzsche',tensions:['Génie inné (mythe romantique) ≠ travail acharné (Nietzsche)','Génie ≠ simple habileté technique'],notions:['art','travail','liberte']},
{id:'beau-sans-concept',term:'Beau sans concept',cat:'Esthétique',def:'Kant : le jugement de goût ("c\'est beau") est un <strong>universel sans concept</strong> — on attend l\'accord universel sans pouvoir le justifier par une règle. Bourdieu critique : ce prétendu universel cache un habitus de classe. Le "goût" dominant est celui de la classe dominante.',auteur:'Kant / Bourdieu',tensions:['Universalité esthétique (Kant) ≠ relativisme de classe (Bourdieu)','Jugement de goût ≠ jugement moral ≠ jugement de connaissance'],notions:['art','bonheur']},
{id:'autonomie',term:'Autonomie',cat:'Éthique kantienne',def:'Kant : se donner sa propre loi (auto-nomos). L\'<strong>autonomie</strong> morale est la capacité à agir selon des principes que l\'on s\'est soi-même donnés par la raison. ≠ hétéronomie (obéir à une loi extérieure). C\'est le fondement de la dignité humaine.',auteur:'Kant',tensions:['Autonomie ≠ hétéronomie (contrainte extérieure, désir, Dieu)','Autonomie ≠ liberté arbitraire (c\'est la raison qui légifère)'],notions:['devoir','liberte','conscience']},
{id:'servitude-volontaire',term:'Servitude volontaire',cat:'Philosophie politique',def:'La Boétie (<em>Discours de la servitude volontaire</em>, ~1548) : mystère politique — pourquoi des millions d\'hommes obéissent-ils librement à un seul tyran ? Par habitude, coutume, peur. La tyrannie repose non sur la force mais sur le consentement. Résistance = cesser d\'obéir.',auteur:'La Boétie',tensions:['Servitude volontaire → complicité des dominés','Résistance passive ≠ révolution armée'],notions:['etat','liberte','devoir']},
{id:'intersubjectivite',term:'Intersubjectivité',cat:'Phénoménologie',def:'Relation entre sujets par laquelle chacun reconnaît l\'autre comme une autre conscience. Fondement du monde commun et de l\'objectivité. Husserl : la réalité partagée se constitue par l\'intersubjectivité. Sartre : "l\'enfer, c\'est les autres" — mais aussi la condition de la conscience de soi.',auteur:'Husserl / Sartre / Merleau-Ponty',tensions:['Intersubjectivité → monde commun ≠ solipsisme','Autrui comme menace (Sartre) ≠ autrui comme condition (Merleau-Ponty)'],notions:['conscience','langage','etat']},
{id:'elan-vital',term:'Élan vital',cat:'Vitalisme',def:'Bergson (<em>L\'Évolution créatrice</em>, 1907) : principe de la vie — force créatrice qui s\'exprime à travers l\'évolution des espèces. Imprévisible, créateur, non téléologique (≠ finalisme). L\'homme est la pointe de cet élan vital grâce à l\'intelligence et à l\'intuition.',auteur:'Bergson',tensions:['Élan vital ≠ mécanisme (déterministe)','Élan vital ≠ finalisme (un but préétabli)'],notions:['nature','temps','liberte']},
{id:'physis',term:'Physis',cat:'Philosophie antique',def:'Terme grec désignant la nature comme processus de croissance spontané (de <em>phuein</em> : pousser, naître). ≠ <em>nomos</em> (la loi, la convention humaine). La physis est ce qui s\'engendre de soi-même sans artifice humain. Aristote : la physis a une finalité interne.',auteur:'Aristote / Héraclite',tensions:['Physis ≠ tekhnê (nature ≠ art/technique)','Physis ≠ nomos (nature ≠ loi humaine)'],notions:['nature','technique','art']},

/* ── Notions comme concepts (redirigent vers la notion) ─────── */
{id:'notion-conscience',term:'Conscience',cat:'Notion — Terminale',def:'La conscience est la présence à soi et au monde. On distingue la <strong>conscience immédiate</strong> (perception du monde) et la <strong>conscience réflexive</strong> (retour sur soi). La psychanalyse remet en cause sa transparence.',auteur:'Descartes / Freud / Sartre',tensions:['Conscience immédiate ≠ conscience réflexive','Conscience (Descartes) ≠ inconscient (Freud)'],notions:['conscience']},
{id:'notion-liberté',term:'Liberté',cat:'Notion — Terminale',def:'La liberté est la capacité d\'agir selon sa propre volonté, sans contrainte extérieure ni intérieure. On distingue la liberté naturelle, la liberté civile (Rousseau), la liberté morale (Kant) et la liberté existentielle (Sartre).',auteur:'Kant / Sartre / Rousseau',tensions:['Liberté de faire ≠ liberté d\'être','Liberté (Sartre : absolue) ≠ liberté (Spinoza : nécessité comprise)'],notions:['liberte']},
{id:'notion-justice',term:'Justice',cat:'Notion — Terminale',def:'La justice est le principe selon lequel chacun reçoit ce qui lui est dû. On distingue la justice commutative (égalité stricte) et la justice distributive (selon les mérites ou les besoins). Rawls : équité et voile d\'ignorance.',auteur:'Aristote / Rawls / Marx',tensions:['Justice formelle ≠ justice réelle','Mérite ≠ besoin comme critère de justice'],notions:['justice']},
{id:'notion-etat',term:'État',cat:'Notion — Terminale',def:'L\'État est l\'institution politique souveraine qui détient le monopole de la violence légitime (Weber) sur un territoire délimité. Il naît d\'un contrat social (Hobbes, Locke, Rousseau) censé garantir la paix civile et les droits des citoyens.',auteur:'Weber / Hobbes / Rousseau',tensions:['État comme protecteur ≠ État comme oppresseur','État libéral (Locke) ≠ État absolu (Hobbes)'],notions:['etat']},
{id:'notion-travail',term:'Travail',cat:'Notion — Terminale',def:'Le travail est l\'activité par laquelle l\'homme transforme la nature pour satisfaire ses besoins. Il peut aliéner (Marx) ou libérer (Hegel). Arendt distingue labor (biologique), work (création durable) et action (politique).',auteur:'Marx / Hegel / Arendt',tensions:['Travail aliénant (Marx) ≠ travail libérateur (Hegel)','Labor (cyclique) ≠ Work (durable) ≠ Action (politique)'],notions:['travail']},
{id:'notion-technique',term:'Technique',cat:'Notion — Terminale',def:'La technique est l\'ensemble des procédés rationnels visant à transformer la nature. Elle pose la question de la maîtrise : maîtrisons-nous la technique ou est-ce elle qui nous maîtrise ? Simondon propose une culture technique.',auteur:'Heidegger / Simondon / Descartes',tensions:['Technique comme libération (Descartes) ≠ technique comme domination (Heidegger)','Technophobie ≠ culture technique (Simondon)'],notions:['technique']},
{id:'notion-nature',term:'Nature',cat:'Notion — Terminale',def:'La nature désigne l\'ensemble du réel non produit par l\'homme, mais aussi l\'essence d\'un être (sa nature profonde). Elle peut être modèle (Rousseau), objet de domination (Descartes) ou sujet de droits (Jonas, Stone).',auteur:'Rousseau / Jonas / Descartes',tensions:['Nature comme norme ≠ sophisme naturaliste','Nature-objet ≠ nature-sujet de droits'],notions:['nature']},
{id:'notion-bonheur',term:'Bonheur',cat:'Notion — Terminale',def:'Le bonheur est un état durable de satisfaction complète, distinct du plaisir (fugace) et du contentement passager. Aristote : eudaimonia (activité vertueuse). Épicure : ataraxie + aponie. Kant : mériter d\'être heureux.',auteur:'Aristote / Épicure / Kant',tensions:['Bonheur (durable) ≠ plaisir (fugace)','Bonheur et morale : accord (Mill) ≠ séparation (Kant)'],notions:['bonheur']},
{id:'notion-art',term:'Art',cat:'Notion — Terminale',def:'L\'art est une activité créatrice produisant des œuvres qui visent le beau ou l\'expression. Platon : imitation (mimésis). Kant : beau sans concept, génie. Hegel : l\'art incarne l\'Esprit. Duchamp : le ready-made remet en cause la définition même de l\'art.',auteur:'Platon / Kant / Hegel / Duchamp',tensions:['Art comme imitation (Platon) ≠ art comme création libre (Kant)','Art ≠ technique (finalité désintéressée)'],notions:['art']},
{id:'notion-temps',term:'Temps',cat:'Notion — Terminale',def:'Le temps est la dimension dans laquelle se succèdent les événements du passé, présent et futur. Bergson oppose le temps vécu (durée) au temps spatialisé de la science. Heidegger : l\'être-vers-la-mort comme horizon de toute temporalité.',auteur:'Bergson / Heidegger / Augustin',tensions:['Temps objectif (science) ≠ durée vécue (Bergson)','Temps linéaire ≠ éternel retour (Nietzsche)'],notions:['temps']},
{id:'notion-langage',term:'Langage',cat:'Notion — Terminale',def:'Le langage est tout système de signes permettant la communication et la pensée. Il est propre à l\'homme (logos vs phone). Saussure : langue/parole. Wittgenstein : les limites de mon langage sont les limites de mon monde.',auteur:'Saussure / Wittgenstein / Benveniste',tensions:['Langage comme outil ≠ langage comme constitutif de la pensée','Langue commune ≠ parole individuelle'],notions:['langage']},
{id:'notion-raison',term:'Raison',cat:'Notion — Terminale',def:'La raison est la faculté humaine de penser de manière logique et d\'établir des vérités. Kant distingue raison théorique (connaître) et raison pratique (agir moralement). Pascal : le cœur a ses raisons que la raison ne connaît point.',auteur:'Kant / Pascal / Descartes',tensions:['Raison théorique (connaître) ≠ raison pratique (agir)','Raison ≠ passion / sentiment'],notions:['raison']},
{id:'notion-science',term:'Science',cat:'Notion — Terminale',def:'La science est un ensemble de connaissances méthodiques visant à expliquer le réel. Popper : une théorie est scientifique si elle est falsifiable. Kuhn : la science progresse par révolutions de paradigmes, non de façon linéaire.',auteur:'Popper / Kuhn / Bachelard',tensions:['Science (vérifiable) ≠ pseudoscience','Progrès cumulatif (Popper) ≠ révolutions paradigmatiques (Kuhn)'],notions:['raison']},
{id:'notion-religion',term:'Religion',cat:'Notion — Terminale',def:'La religion est un ensemble de croyances et de pratiques relatives au sacré. Elle articule vision du monde, morale et rites. Freud : illusion. Marx : opium du peuple. Pascal : pari raisonnable face à l\'infini.',auteur:'Freud / Marx / Pascal',tensions:['Foi ≠ raison (mais dialogue possible)','Religion comme consolation ≠ religion comme vérité'],notions:['religion']},
{id:'notion-verite',term:'Vérité',cat:'Notion — Terminale',def:'La vérité est l\'adéquation d\'un énoncé à la réalité (conception classique). Descartes : certitude par le doute. Nietzsche : la vérité est une métaphore usée. Popper : on ne prouve pas la vérité, on réfute l\'erreur.',auteur:'Descartes / Nietzsche / Popper',tensions:['Vérité objective ≠ vérité subjective','Certitude ≠ vérité'],notions:['verite']},
{id:'notion-inconscient',term:'Inconscient',cat:'Notion — Terminale',def:'L\'inconscient freudien désigne les représentations refoulées qui continuent d\'agir sur le psychisme à notre insu. Topique : Ça / Moi / Surmoi. Il se manifeste dans les rêves, les actes manqués, les lapsus. Remet en cause la souveraineté du moi.',auteur:'Freud / Jung / Lacan',tensions:['Inconscient (Freud) ≠ conscience (Descartes)','Inconscient ≠ simple méconnaissance (c\'est du refoulé actif)'],notions:['inconscient']},

/* ── Concepts philosophiques manquants ───────────────────────── */
{id:'désir',term:'Désir',cat:'Anthropologie philosophique',def:'Mouvement vers ce qui manque, vers un objet qui n\'est pas encore possédé. Platon (<em>Banquet</em>) : le désir est manque — Éros est fils de Pénia (pauvreté). Spinoza : le désir est l\'essence même de l\'homme (conatus). Freud : le désir naît du refoulement pulsionnel.',auteur:'Platon / Spinoza / Freud',tensions:['Désir comme manque (Platon) ≠ désir comme puissance (Spinoza)','Satisfaire le désir ≠ supprimer le désir'],notions:['bonheur','inconscient','liberte']},
{id:'plaisir',term:'Plaisir',cat:'Éthique',def:'État affectif positif lié à la satisfaction d\'un besoin ou d\'un désir. Épicure distingue les plaisirs stables (katastématiques — ataraxie) et les plaisirs mobiles (en mouvement). Mill distingue plaisirs inférieurs (corporels) et supérieurs (intellectuels).',auteur:'Épicure / Mill / Aristote',tensions:['Plaisir (fugace) ≠ bonheur (durable)','Plaisirs inférieurs ≠ plaisirs supérieurs (Mill)'],notions:['bonheur']},
{id:'refoulement',term:'Refoulement',cat:'Psychanalyse',def:'Freud : mécanisme par lequel le Moi repousse dans l\'inconscient les représentations liées à des pulsions inacceptables. Le refoulé n\'est pas détruit — il agit en retour sous forme de symptômes, rêves, actes manqués. Fondement de la névrose.',auteur:'Freud',tensions:['Refoulement ≠ simple oubli (le refoulé persiste et agit)','Refoulement ≠ répression consciente'],notions:['inconscient','conscience','liberte']},
{id:'pulsion',term:'Pulsion',cat:'Psychanalyse',def:'Freud : force représentant une exigence de travail pour le psychisme, à la frontière du corporel et du psychique. Pulsions de vie (Éros) vs pulsions de mort (Thanatos). La pulsion est une poussée constante — ≠ instinct (réponse fixe à un stimulus).',auteur:'Freud',tensions:['Pulsion (psychique) ≠ instinct (biologique fixe)','Éros (vie) ≠ Thanatos (mort, destruction)'],notions:['inconscient','nature']},
{id:'catharsis',term:'Catharsis',cat:'Esthétique antique',def:'Aristote (<em>Poétique</em>) : la tragédie opère une purification des émotions (pitié et crainte) par leur représentation dramatique. Le spectateur ressent et décharge ses passions de manière sécurisée. Controversée : s\'agit-il de purgation ou de purification morale ?',auteur:'Aristote',tensions:['Catharsis (Aristote) ≠ mimésis dangereuse (Platon)','Art thérapeutique ≠ art purement esthétique'],notions:['art','bonheur']},
{id:'mimesis',term:'Mimésis',cat:'Esthétique antique',def:'Imitation ou représentation du réel dans les arts. Platon (<em>République</em>) : la mimésis est une copie de copie — l\'artiste imite un objet sensible qui lui-même imite une Idée. L\'art est au troisième degré de la vérité et peut tromper. Aristote réhabilite la mimésis : elle est un apprentissage du réel.',auteur:'Platon / Aristote',tensions:['Mimésis condamnée (Platon) ≠ mimésis réhabilitée (Aristote)','Art comme copie ≠ art comme création'],notions:['art']},
{id:'sublime',term:'Sublime',cat:'Esthétique',def:'Kant (<em>Critique de la faculté de juger</em>) : sentiment produit par ce qui dépasse notre faculté de représentation — la nature immense ou terrifiante. Différent du beau (harmonieux, fini). Le sublime mathématique (infini) et le sublime dynamique (puissance). Notre raison triomphe de l\'écrasement.',auteur:'Kant / Burke / Longin',tensions:['Sublime ≠ beau (dépasse la forme, effraie)','Sublime naturel ≠ sublime artistique'],notions:['art','nature']},
{id:'volonte-puissance',term:'Volonté de puissance',cat:'Philosophie nietzschéenne',def:'Nietzsche : principe fondamental de la vie — non pas désir de dominer autrui mais force expansive, créatrice, qui cherche à se dépasser elle-même. Le surhomme (<em>Übermensch</em>) est celui qui assume sa volonté de puissance et crée de nouvelles valeurs après la mort de Dieu.',auteur:'Nietzsche',tensions:['Volonté de puissance (créer) ≠ volonté de domination','Volonté de puissance ≠ ressentiment (morale des esclaves)'],notions:['liberte','travail','art']},
{id:'paradigme',term:'Paradigme',cat:'Épistémologie',def:'Kuhn (<em>La Structure des révolutions scientifiques</em>, 1962) : ensemble de présupposés, méthodes et exemples partagés par une communauté scientifique. La science normale travaille dans un paradigme. Une révolution scientifique est un changement de paradigme (ex : Copernic, Darwin, Einstein).',auteur:'Kuhn',tensions:['Paradigme dominant ≠ science alternative','Science normale ≠ révolution scientifique'],notions:['raison']},
{id:'falsifiabilite',term:'Falsifiabilité',cat:'Épistémologie',def:'Popper : critère de démarcation entre science et non-science. Une théorie est scientifique si elle peut, en principe, être réfutée par l\'expérience. Ex : "Tous les corbeaux sont noirs" est falsifiable (un corbeau blanc suffit à l\'infirmer). La psychanalyse et le marxisme sont non-falsifiables selon Popper.',auteur:'Popper',tensions:['Falsifiable ≠ vrai (une théorie peut être falsifiable et fausse)','Falsifiabilité ≠ vérifiabilité (positivisme logique)'],notions:['raison','verite']},
{id:'contrat-nature',term:'Contrat naturel',cat:'Philosophie de l\'environnement',def:'Serres (<em>Le Contrat naturel</em>, 1990) : face au parasitisme humain sur la nature, étendre le contrat social à la nature. Le droit de symbiose remplace le droit de maîtrise : chacun doit à l\'autre. La nature devient partenaire du contrat, non objet de domination.',auteur:'Serres',tensions:['Contrat naturel ≠ contrat social classique (entre humains)','Symbiose ≠ parasitisme'],notions:['nature','etat','devoir']},
{id:'principe-responsabilite',term:'Principe responsabilité',cat:'Éthique',def:'Jonas (<em>Le Principe responsabilité</em>, 1979) : "Agis de façon que les effets de ton action soient compatibles avec la permanence d\'une vie authentiquement humaine sur Terre." La responsabilité s\'étend aux générations futures et à la biosphère. L\'heuristique de la peur : anticiper la catastrophe pour guider l\'action.',auteur:'Jonas',tensions:['Responsabilité future ≠ responsabilité rétrospective','Précaution ≠ immobilisme'],notions:['devoir','nature','technique']},
{id:'divertissement',term:'Divertissement',cat:'Anthropologie philosophique',def:'Pascal (<em>Pensées</em>) : l\'homme fuit la pensée de sa condition (misère, finitude, mort) en se jetant dans l\'action et le divertissement. Le roi chasseur préfère la chasse à la possession du lièvre. Le divertissement est l\'anesthésie de l\'angoisse existentielle.',auteur:'Pascal',tensions:['Divertissement ≠ repos (il est une fuite, non une pause)','Occuper son esprit ≠ être heureux'],notions:['bonheur','travail','temps']},
{id:'heuristique-peur',term:'Heuristique de la peur',cat:'Éthique',def:'Jonas : face à l\'incertitude des effets de la technique, donner la priorité aux prophéties de malheur sur celles de bonheur. Mieux vaut se tromper par excès de prudence que par optimisme. Principe de précaution étendu à la biosphère et aux générations futures.',auteur:'Jonas',tensions:['Peur comme boussole ≠ peur comme paralysie','Précaution ≠ refus du progrès'],notions:['devoir','technique','nature']},
{id:'culture-technique',term:'Culture technique',cat:'Philosophie de la technique',def:'Simondon : dépasser la technophobie et l\'enthousiasme naïf par la connaissance réelle du fonctionnement des machines. L\'aliénation vient de la méconnaissance — comprendre les objets techniques, c\'est les coordonner comme un chef d\'orchestre. La culture doit intégrer la réalité humaine contenue dans les machines.',auteur:'Simondon',tensions:['Technophobie (ignorance) ≠ technolatrie (enthousiasme aveugle)','Culture technique ≠ simple utilisation'],notions:['technique','travail','art']},
{id:'tabula-rasa',term:'Tabula rasa',cat:'Épistémologie empiriste',def:'Locke : l\'esprit humain est à la naissance une "table rase" — il n\'y a pas d\'idées innées. Toute connaissance vient de l\'expérience sensible. S\'oppose à Descartes (idées innées) et à Leibniz (monades). Fondement de l\'empirisme.',auteur:'Locke',tensions:['Tabula rasa (tout vient de l\'expérience) ≠ idées innées (Descartes, Platon)'],notions:['raison','conscience']},
{id:'elan-vital2',term:'Élan vital',cat:'Vitalisme',def:'Bergson (<em>L\'Évolution créatrice</em>, 1907) : principe de la vie — force créatrice imprévisible qui s\'exprime à travers l\'évolution des espèces. ≠ mécanisme (déterministe) et ≠ finalisme (but préétabli). L\'homme est la pointe de cet élan grâce à l\'intelligence et à l\'intuition.',auteur:'Bergson',tensions:['Élan vital ≠ mécanisme (déterministe)','Élan vital ≠ finalisme (un but préétabli)'],notions:['nature','liberte']},
{id:'duree',term:'Durée',cat:'Philosophie du temps',def:'Bergson : le temps vécu intérieurement, flux continu et qualitatif — ≠ temps de la physique (homogène, spatialisé, quantifiable). La conscience est durée : ses états se fondent les uns dans les autres. L\'introspection révèle cette durée irréductible au chronomètre.',auteur:'Bergson',tensions:['Durée (qualitatif, vécu) ≠ temps physique (quantitatif, mesurable)','Durée ≠ instant'],notions:['temps','conscience']},
{id:'eternel-retour',term:'Éternel retour',cat:'Philosophie du temps',def:'Nietzsche (<em>Le Gai savoir</em>, §341, « Le plus grand poids ») : et si un démon t\'annonçait que tu devras revivre ta vie une infinité de fois, à l\'identique, jusqu\'au moindre détail ? L\'éternel retour n\'est pas d\'abord une thèse cosmologique mais une <strong>épreuve existentielle</strong> : aimes-tu assez ta vie pour en vouloir l\'éternel recommencement ? Y répondre « oui », c\'est l\'<em>amor fati</em> — aimer son destin. Le temps cyclique de l\'affirmation s\'oppose au temps linéaire (création → salut) qui dévalue l\'ici-bas au profit d\'un arrière-monde.',auteur:'Nietzsche',relations:[{to:'volonte-puissance',type:'prolonge',desc:'L\'éternel retour est l\'épreuve suprême de la volonté de puissance : vouloir le retour de chaque instant, c\'est créer de la valeur par pure affirmation, sans recours à un arrière-monde.'},{type:'distinction',desc:'Éternel retour (temps cyclique, affirmation de la vie) ≠ temps linéaire chrétien (création, jugement, salut).'},{term:'amor fati',type:'implique',desc:'L\'éternel retour ne se supporte que comme amor fati : aimer son destin au point d\'en vouloir la répétition infinie.'}],notions:['temps','liberte','bonheur'],new:true},
{id:'acceleration-resonance',term:'Accélération / Résonance',cat:'Philosophie du temps',def:'Hartmut Rosa : la <strong>modernité tardive</strong> est marquée par une <strong>accélération</strong> à trois niveaux — technique (transports, communication), du <em>changement social</em> (métiers, institutions, modes se renouvellent toujours plus vite) et du <em>rythme de vie</em> (on en fait toujours plus par unité de temps, alors même que la technique promettait d\'en faire gagner : c\'est le paradoxe). Cette fuite en avant engendre une nouvelle <strong>aliénation</strong> : un rapport muet et distant au monde. La <strong>résonance</strong> est le remède proposé — un rapport vibrant et réciproque (à une œuvre, à la nature, à autrui) où le monde nous « répond » au lieu de rester inerte.',auteur:'Hartmut Rosa',relations:[{type:'distinction',desc:'Accélération (rapport muet, aliéné, au monde) ≠ résonance (rapport vibrant et réciproque où le monde « répond »).'},{to:'alienation',type:'prolonge',desc:'Rosa déplace l\'aliénation marxiste : ce n\'est plus seulement le travail qui aliène, mais l\'accélération généralisée, qui rend le monde étranger.'},{to:'duree',type:'complete',desc:'Là où Bergson oppose la durée vécue au temps mesuré, Rosa montre comment l\'accélération sociale écrase la possibilité même d\'une durée pleine et résonante.'}],notions:['temps','travail','bonheur'],new:true},
{id:'etre-vers-mort',term:'Être-vers-la-mort',cat:'Phénoménologie existentiale',def:'Heidegger : la mort est la possibilité la plus propre, inconditionnelle et certaine du Dasein (être-là). L\'angoisse face à la mort révèle l\'authenticité — elle arrache à la "déchéance" dans le "on" (das Man). Assumer sa finitude, c\'est exister authentiquement.',auteur:'Heidegger',tensions:['Authenticité (assumer la mort) ≠ déchéance (fuir dans le "on")','Être-vers-la-mort ≠ désir de mourir'],notions:['temps','conscience','liberte']},
{id:'fonds-disponible',term:'Fonds disponible',cat:'Philosophie de la technique',def:'Heidegger (<em>La Question de la technique</em>, 1954) : la technique moderne dévoile le réel comme un stock d\'énergie exploitable (Bestand). Le Rhin devient "centrale électrique", non fleuve majestueux. Ce mode de dévoilement menace d\'effacer tous les autres.',auteur:'Heidegger',tensions:['Dévoilement technique (fonds) ≠ dévoilement artistique (poiêsis)','Technique moderne ≠ technique artisanale'],notions:['technique','nature','art']},
{id:'eudaimonia2',term:'Eudaimonia',cat:'Éthique antique',def:'Terme aristotélicien : bonheur au sens d\'<em>activité de l\'âme conforme à la vertu</em>. Ce n\'est pas un état passif mais une energeia (actualisation). Exige les vertus morales ET intellectuelles (phronesis) ET des biens extérieurs. Fin ultime de l\'existence humaine.',auteur:'Aristote',tensions:['Eudaimonia (activité) ≠ ataraxie (repos, Épicure)','Eudaimonia ≠ hedone (plaisir sensoriel)'],notions:['bonheur','travail']},
{id:'honte-prométhéenne',term:'Honte prométhéenne',cat:'Philosophie de la technique',def:'Anders : l\'homme éprouve de la honte face à ses propres machines — sa fragilité biologique est humiliante comparée à leurs performances. Nous sommes devenus "antiqués" par rapport à nos productions. Conséquence : l\'homme risque de se modéliser sur ses machines.',auteur:'Anders',tensions:['Honte prométhéenne → aliénation inverse (la machine domine le créateur)','Anders ≠ Simondon (peur des machines ≠ culture technique)'],notions:['technique','travail','nature']},
{id:'desobeissance-civile',term:'Désobéissance civile',cat:'Philosophie politique',def:'Thoreau (<em>La Désobéissance civile</em>, 1849) : refus public, non-violent et assumé d\'une loi injuste. Légitime lorsque la loi viole la conscience morale. Rawls la formalise : acte non-violent, public, adressé au sens de la justice de la majorité.',auteur:'Thoreau / Rawls / Gandhi',tensions:['Désobéissance civile ≠ révolution armée','Résistance individuelle ≠ résistance collective'],notions:['justice','etat','devoir']},
{id:'identite-narrative',term:'Identité narrative',cat:'Herméneutique',def:'Ricœur : l\'identité personnelle n\'est ni substance fixe (idem) ni flux incohérent (Hume), mais <strong>ipse</strong> — identité narrative. C\'est en racontant notre vie que nous nous constituons comme sujet. Les récits culturels que nous appliquons à notre vie font notre identité.',auteur:'Ricœur',tensions:['Identité narrative (ipse) ≠ identité substantielle (idem)','Narration de soi ≠ fiction de soi'],notions:['conscience','temps','langage']},
{id:'jugement-reflexissant',term:'Jugement de goût',cat:'Esthétique kantienne',def:'Kant (<em>Critique de la faculté de juger</em>) : le jugement esthétique ("c\'est beau") prétend à l\'universalité sans se fonder sur un concept. Il est désintéressé (≠ agréable), libre (≠ parfait) et communicable. On postule l\'accord universel sans pouvoir le prouver.',auteur:'Kant',tensions:['Jugement de goût (universalité sans concept) ≠ jugement de connaissance (concept déterminant)','Beau ≠ agréable (subjectif) ≠ parfait (conceptuel)'],notions:['art','bonheur']},
{id:'travail-hegel',term:'Travail et reconnaissance',cat:'Phénoménologie',def:'Hegel : l\'esclave se libère par le travail. En transformant la matière, il s\'y reconnaît et forme sa conscience de soi. Le maître, dépendant de l\'esclave pour ses besoins, perd sa liberté. Le travail est le chemin de l\'émancipation par la résistance de la matière.',auteur:'Hegel',tensions:['Travail de l\'esclave → émancipation paradoxale','Travail libre (expression de soi) ≠ travail forcé (aliénation)'],notions:['travail','liberte','conscience']},

/* ── Concepts pour Religion / Vérité / Science (ajouts récents) ─── */
{id:'foi',term:'Foi',cat:'Religion',def:'Du latin <em>fides</em>, « confiance ». <strong>Adhésion totale</strong> à des vérités tenues pour révélées, qui restent en partie un mystère pour la raison. Pour Descartes, la foi n\'est pas un acte de l\'intelligence mais un acte de la <strong>volonté</strong> ; pour Pascal, c\'est le « cœur » qui croit, non la raison ; pour Kierkegaard, la foi est un <em>saut</em> dans l\'angoisse, en l\'absence de toute certitude rationnelle. Loin d\'être une croyance naïve, elle peut se vivre dans l\'angoisse et l\'incertitude.',auteur:'Pascal / Descartes / Kierkegaard',tensions:['Foi (volonté, cœur) ≠ savoir (raison, démonstration)','Foi tranquille ≠ saut dans l\'angoisse (Kierkegaard)','Foi ≠ croyance naïve (engage tout l\'individu)'],notions:['religion','verite','raison']},

{id:'sacre',term:'Sacré',cat:'Religion / Sociologie',def:'Du latin <em>sacer</em>, « séparé, mis à part ». Catégorie qui qualifie ce qui relève d\'un ordre supérieur — objets, êtres, lieux ou moments concentrant la signification du réel. Durkheim : la « forme élémentaire de la vie religieuse » est l\'opposition <strong>sacré / profane</strong>. Le sacré est ambivalent : à la fois bénédiction et interdit, fascinant et terrible. Subsiste dans les sociétés laïcisées (drapeau, mémoriaux, fêtes nationales — sacré civique).',auteur:'Durkheim / Eliade',tensions:['Sacré ≠ profane (Durkheim)','Sacré comme réalité surnaturelle (croyant) ≠ projection collective (Durkheim)','Sacré religieux ≠ sacré civique (laïcité)'],notions:['religion','etat','art']},

{id:'profane',term:'Profane',cat:'Religion / Sociologie',def:'Du latin <em>pro-fanum</em>, « devant le temple, hors du temple ». Désigne la <strong>réalité ordinaire</strong>, insignifiante, qui ne se définit que par opposition au sacré. Durkheim : le profane est le quotidien banal, le sacré est ce qui le transcende. Toute religion établit cette frontière. Une société entièrement profane (sans aucun sacré) est sociologiquement peu probable — il y a toujours des résidus de sacralité.',auteur:'Durkheim',tensions:['Profane (ordinaire) ≠ sacré (extraordinaire)','Profane ≠ profanation (transgression du sacré)','Sécularisation ≠ disparition complète du sacré'],notions:['religion','etat']},

{id:'transcendance',term:'Transcendance',cat:'Métaphysique / Religion',def:'Du latin <em>transcendere</em>, « passer au-delà ». Désigne ce qui <strong>dépasse l\'ordre naturel ou sensible</strong> — Dieu pour les religions monothéistes, le « tout autre » de l\'expérience du sacré. S\'oppose à l\'<em>immanence</em> (ce qui reste dans le monde). Augustin : l\'expérience du sacré met l\'homme face à un « tout autre, à la fois terrible et fascinant ». Spinoza renverse : Dieu = la Nature (<em>Deus sive Natura</em>) — il n\'y a que de l\'immanence absolue.',auteur:'Augustin / Spinoza / Kant',tensions:['Transcendance (Dieu au-delà du monde) ≠ immanence (Dieu dans le monde — Spinoza)','Expérience de la finitude → ouverture à la transcendance','Transcendance religieuse ≠ transcendantal kantien (conditions de l\'expérience)'],notions:['religion','conscience','liberte']},

{id:'revelation',term:'Révélation',cat:'Religion',def:'Du latin <em>revelare</em>, « dévoiler, ôter le voile ». Communication directe d\'une vérité divine aux hommes — par un prophète, une écriture sainte ou une expérience mystique. La <strong>religion révélée</strong> (judaïsme, christianisme, islam) repose sur une révélation historique. S\'oppose à la <strong>religion naturelle</strong> (Lumières) qui prétend atteindre Dieu par la seule raison. Les vérités révélées (Trinité, Incarnation) excèdent la raison sans la contredire (Thomas d\'Aquin).',auteur:'Thomas d\'Aquin / Pascal',tensions:['Vérités révélées ≠ vérités démontrées (raison)','Religion révélée ≠ religion naturelle (Lumières)','Foi en la révélation ≠ déisme rationnel'],notions:['religion','verite','raison']},

{id:'anamnese',term:'Réminiscence',cat:'Épistémologie platonicienne',def:'Du grec <em>anamnêsis</em>, « ressouvenir ». Théorie platonicienne (<em>Ménon</em>, <em>Phédon</em>) : connaître, c\'est <strong>re-connaître</strong> ce que l\'âme a contemplé avant la naissance et qu\'elle a oublié. Réponse au <strong>paradoxe sophistique de l\'apprentissage</strong> : si l\'on sait, il n\'y a pas à chercher ; si l\'on ignore, on ne saurait ce qu\'on cherche. Démonstration : Socrate fait découvrir un théorème à un jeune esclave par les seules questions. Réinsère ignorance et connaissance dans un processus continu d\'apprentissage.',auteur:'Platon',tensions:['Réminiscence (savoir intérieur) ≠ tabula rasa (Locke — savoir extérieur)','Connaissance comme découverte ≠ connaissance comme retrouvaille','Apprendre ≠ recevoir un savoir extérieur'],notions:['verite','conscience','raison']},

{id:'episteme',term:'Épistémé',cat:'Épistémologie antique',def:'Terme grec désignant la <strong>connaissance scientifique vraie</strong> — universelle, nécessaire, théorique. Pour les Grecs, l\'<em>épistémé</em> s\'oppose à la <em>doxa</em> (opinion, croyance non justifiée). C\'est la « science suprême » que vise la philosophie. Foucault donnera au terme un sens élargi : l\'<em>épistémé</em> d\'une époque est l\'ensemble des structures inconscientes qui rendent possible un savoir donné.',auteur:'Platon / Aristote / Foucault',tensions:['Épistémé (savoir vrai universel) ≠ doxa (opinion contingente)','Épistémé (théorique) ≠ technê (savoir-faire pratique)','Épistémé d\'une époque (Foucault) ≠ idée intemporelle de la science'],notions:['raison','verite']},

{id:'doxa',term:'Doxa',cat:'Épistémologie antique',def:'Terme grec : <strong>opinion</strong>, croyance non justifiée. S\'oppose à l\'<em>épistémé</em> (savoir vrai). La <em>doxa</em> peut être vraie par hasard, mais elle n\'est pas un savoir car elle n\'est pas justifiée par la raison (<em>logos</em>). Bachelard radicalise : « L\'opinion pense mal ; elle ne pense pas : elle traduit des besoins en connaissances. » L\'opinion est un obstacle épistémologique à détruire pour fonder la science.',auteur:'Platon / Bachelard',tensions:['Doxa (opinion) ≠ épistémé (savoir)','Doxa = obstacle (Bachelard) ≠ point de départ (sens commun)','Opinion vraie par hasard ≠ savoir justifié'],notions:['verite','raison']},

{id:'obstacle-epistemologique',term:'Obstacle épistémologique',cat:'Épistémologie',def:'Bachelard (<em>La Formation de l\'esprit scientifique</em>, 1938) : ce qui <strong>empêche la connaissance scientifique</strong> de se constituer — non l\'inconnu, mais le <em>déjà-connu</em> faussement. L\'opinion, l\'expérience première, l\'image substantialiste, la généralisation hâtive sont autant d\'obstacles. La science doit rompre avec eux par une <strong>rupture épistémologique</strong>. Le « nouvel esprit scientifique » assume cette discontinuité avec l\'expérience naïve.',auteur:'Bachelard',tensions:['Obstacle épistémologique ≠ ignorance simple (c\'est un faux savoir)','Continuité empirique ≠ rupture scientifique','Sens commun ≠ science'],notions:['raison','verite']},

{id:'rupture-epistemologique',term:'Rupture épistémologique',cat:'Épistémologie',def:'Bachelard : passage <strong>discontinu</strong> d\'un mode de connaissance à un autre — par exemple de la chimie pré-lavoisienne (théorie du phlogistique) à la chimie moderne (théorie de l\'oxygène). La science ne progresse pas par accumulation continue mais par <em>ruptures</em>. Anticipe Kuhn et ses <em>révolutions paradigmatiques</em>. Implique que la vérité scientifique n\'est pas le prolongement raffiné du sens commun.',auteur:'Bachelard / Kuhn',tensions:['Rupture (discontinuité) ≠ continuité accumulative (positivisme)','Science ≠ sens commun raffiné','Ruptures locales (Bachelard) ≠ révolutions globales (Kuhn)'],notions:['raison','verite']},

{id:'noma',term:'NOMA',cat:'Philosophie des sciences',def:'Stephen Jay Gould (<em>Et Dieu dit : « Que Darwin soit ! »</em>, 1999) : <em>Non-Overlapping Magisteria</em>. Science et religion sont deux <strong>magistères distincts qui ne se recouvrent pas</strong> : la science traite du <em>comment</em> (faits, mécanismes, lois empiriques) ; la religion traite du <em>pourquoi</em> (sens, valeurs, finalité ultime). Pas de conflit possible si chacun reste dans son domaine. Les conflits (créationnisme, scientisme) résultent de <em>transgressions de frontières</em>.',auteur:'Stephen Jay Gould',tensions:['NOMA (séparation) ≠ concordisme (recherche d\'accords)','NOMA (deux magistères) ≠ scientisme (un seul magistère = la science)','Comment (science) ≠ pourquoi (religion)'],notions:['religion','verite','raison'],
liens:{religion:'Pour la notion Religion, NOMA est la thèse contemporaine de référence sur la coexistence : la religion garde un domaine propre (le sens, les valeurs) que la science n\'a pas vocation à occuper. Elle s\'oppose donc à la réduction de la religion à une illusion à éliminer.',science:'Pour la notion Science, NOMA fixe une limite à l\'ambition explicative : la science répond au « comment », pas au « pourquoi » ultime. Refuser cette limite, c\'est verser dans le scientisme (faire de la science la seule source de sens).'},
relations:[{to:'illusion',type:'oppose',desc:'Gould refuse la réduction freudienne de la religion à une illusion : ce serait laisser la science déborder sur le magistère du sens, donc transgresser les frontières.'},{to:'verites-coeur',type:'prolonge',desc:'Les trois ordres de Pascal (corps / esprits / charité) anticipent la séparation des magistères : vouloir prouver Dieu comme un théorème, c\'est se tromper d\'ordre.'}],modified:true},

{id:'aletheia',term:'Alètheia',cat:'Philosophie de la vérité',def:'Terme grec souvent traduit par « vérité ». Étymologie : <em>a-lèthe</em>, « non-oubli, non-occultation ». Heidegger insiste sur ce sens originaire : la vérité comme <strong>dévoilement</strong> (<em>Unverborgenheit</em>) — l\'être qui sort de la cachette pour se montrer. Plus ancien et plus fondamental que la vérité-adéquation (jugement/réalité). La science empirique opère une vérité <em>dérivée</em> qui présuppose une vérité originaire (alètheia) qu\'elle ne thématise pas (« la science ne pense pas »).',auteur:'Heidegger',tensions:['Alètheia (dévoilement) ≠ vérité-adéquation (correspondance)','Vérité comme événement ≠ vérité comme propriété d\'un jugement','Pensée philosophique ≠ savoir scientifique'],notions:['verite','langage']},

{id:'aliénation-religieuse',term:'Aliénation religieuse',cat:'Critique de la religion',def:'Feuerbach (<em>L\'Essence du christianisme</em>, 1842) : Dieu n\'est rien d\'autre que la <strong>projection</strong> hors de soi des aspirations humaines (puissance, sagesse, amour) que l\'expérience de notre finitude borne. L\'homme s\'aliène en Dieu parce qu\'en lui il se réalise dans un <em>autre imaginaire</em>. Marx prolonge : il faut analyser les conditions sociales (oppression, frustration) qui produisent cette projection. Critiquer la religion sans transformer la société = inutile.',auteur:'Feuerbach / Marx',tensions:['Aliénation religieuse (projection) ≠ révélation (Dieu comme réalité)','Critique anthropologique (Feuerbach) ≠ critique sociale (Marx)','Religion comme aliénation ≠ religion comme expérience authentique'],notions:['religion','liberte','conscience'],
liens:{religion:'Pour la notion Religion, c\'est la matrice de toute la critique moderne : la religion n\'est pas jugée vraie ou fausse, elle est expliquée comme projection d\'un manque humain. Feuerbach ouvre la voie à Marx (critique sociale) et à Freud (illusion du désir).'},modified:true},
{id:'religion-naturelle',term:'Religion naturelle',cat:'Religion',def:'Concept des Lumières du XVIIIe siècle : religion qui s\'oppose à la fois aux religions <em>positives</em> (instituées) et aux religions <em>révélées</em>. Prône un rapport immédiat à Dieu sans intermédiaire ecclésiastique. Repère la divinité dans les <strong>lois de la nature</strong> (« le grand livre du monde ») plutôt que dans la Bible. <strong>Naturelle = aussi rationnelle</strong> (Kant, <em>La Religion dans les limites de la simple raison</em>, 1793). Voisin du <em>déisme</em>.',auteur:'Kant / Voltaire',tensions:['Religion naturelle ≠ religion révélée (Bible)','Religion naturelle ≠ religion positive (instituée)','Naturelle (rationnelle) ≠ surnaturelle (miracles)'],notions:['religion','raison','nature']},

{id:'religion-civile',term:'Religion civile',cat:'Philosophie politique / Religion',def:'Rousseau (<em>Du contrat social</em>, IV, 8) : religion instituée par le souverain dans l\'État républicain pour conférer un caractère sacré aux institutions de convention. Comporte un petit nombre de <strong>dogmes positifs</strong> : croyance en une divinité bienveillante, châtiment pour les méchants, justice pour les meilleurs. <em>Tolère tous les cultes... sauf l\'intolérance.</em> Modèle pour la laïcité républicaine et le sacré civique.',auteur:'Rousseau',tensions:['Religion civile (instituée par l\'État) ≠ religion révélée','Tolérance générale ≠ tolérance de l\'intolérance','Sacré religieux ≠ sacré civique'],notions:['religion','etat','liberte']},

{id:'theologie',term:'Théologie',cat:'Religion',def:'Du grec <em>theos</em> (Dieu) + <em>logos</em> (discours). <strong>Discours rationnel sur Dieu</strong> et les choses divines, à partir des données de la révélation. Thomas d\'Aquin la place au sommet des savoirs : la philosophie est sa <em>servante</em> (<em>ancilla theologiae</em>). Se distingue de la <em>religion</em> (pratique, foi vécue) et de la <em>philosophie de la religion</em> (qui n\'engage pas la foi). Feuerbach renverse : « la théologie est anthropologie ».',auteur:'Thomas d\'Aquin / Feuerbach',tensions:['Théologie (discours rationnel) ≠ religion (pratique, foi vécue)','Philosophia ancilla theologiae (Thomas) ≠ autonomie de la raison (Descartes)','Théologie ≠ anthropologie (renversement de Feuerbach)'],notions:['religion','raison']},

{id:'positivisme',term:'Positivisme',cat:'Philosophie des sciences',def:'Doctrine d\'Auguste Comte (<em>Cours de philosophie positive</em>, 1830-1842) : seules les connaissances <strong>positives</strong> (vérifiables empiriquement) ont valeur scientifique. La métaphysique et la théologie sont des stades dépassés (loi des trois états : théologique, métaphysique, positif). Étendu aux sciences humaines (sociologie comme « physique sociale »). Critiqué par Bachelard (positivisme naïf, sans rupture épistémologique) et Popper (manque de critère de démarcation par la falsifiabilité).',auteur:'Comte',tensions:['Positivisme ≠ métaphysique (rejetée)','Positivisme (cumulatif) ≠ ruptures épistémologiques (Bachelard)','Sciences positives ≠ herméneutique (sciences de l\'esprit, Dilthey)'],notions:['raison','verite']},

{id:'hermeneutique',term:'Herméneutique',cat:'Philosophie',def:'Du grec <em>hermêneutikê</em>, « art d\'interpréter ». Théorie de l\'<strong>interprétation</strong> des textes (initialement les textes sacrés). Dilthey (<em>Introduction à l\'étude des sciences humaines</em>, 1883) : les sciences humaines (histoire, sociologie, philosophie) ne procèdent pas par <em>explication</em> causale (comme les sciences de la nature) mais par <strong>compréhension</strong> (<em>Verstehen</em>) — interprétation des intentions humaines. Heidegger et Ricœur étendent l\'herméneutique à toute compréhension de soi et du monde.',auteur:'Dilthey / Heidegger / Ricœur',tensions:['Comprendre (Verstehen, herméneutique) ≠ expliquer (Erklären, sciences naturelles)','Sciences de la nature ≠ sciences de l\'esprit (Dilthey)','Texte ≠ intentions (interprétation toujours partielle)'],notions:['langage','raison','verite','conscience']},

{id:'verites-coeur',term:'Vérités du cœur',cat:'Philosophie pascalienne',def:'Pascal (<em>Pensées</em>) : il existe des <strong>vérités du cœur</strong> que la raison seule ne peut atteindre — elles sont l\'objet d\'une révélation, non d\'une démonstration. Pascal distingue trois <em>ordres</em> irréductibles : (1) ordre des corps (matière) ; (2) ordre des esprits (pensée, démonstration) ; (3) ordre de la <strong>charité</strong> (foi, amour de Dieu). Vouloir prouver Dieu comme un théorème = se tromper d\'ordre. « Le cœur a ses raisons que la raison ne connaît point. »',auteur:'Pascal',tensions:['Vérités du cœur (révélation) ≠ vérités de la raison (démonstration)','Trois ordres irréductibles : corps ≠ esprits ≠ charité','Cœur ≠ sentimentalité (le cœur a ses « raisons », sa logique propre)'],notions:['verite','religion','raison','conscience']},

{id:'angoisse',term:'Angoisse',cat:'Existentialisme / Religion',def:'Pour Kierkegaard (<em>Le Concept d\'angoisse</em>, 1844 ; <em>Crainte et Tremblement</em>, 1843) : sentiment fondamental qui révèle la <strong>liberté humaine</strong> face au possible — non peur d\'un objet précis, mais vertige devant l\'indétermination de l\'existence. L\'angoisse est <em>formatrice</em> : elle met à nu nos illusions et ouvre à la foi authentique (« le saut »). Heidegger reprend : l\'angoisse révèle l\'<em>être-pour-la-mort</em>, condition de l\'authenticité.',auteur:'Kierkegaard / Heidegger / Sartre',tensions:['Angoisse ≠ peur (sans objet déterminé)','Angoisse formatrice (Kierkegaard) ≠ angoisse paralysante','Angoisse comme épreuve spirituelle ≠ angoisse comme pathologie'],notions:['religion','liberte','conscience','temps']},

{id:'pari-pascalien',term:'Pari pascalien',cat:'Philosophie de la religion',def:'Pascal (<em>Pensées</em>, fragment 233) : <strong>argument pragmatique</strong> en faveur de la croyance en Dieu, face à l\'incertitude rationnelle. Calcul des gains/pertes : si Dieu existe et qu\'on croit → gain infini ; si Dieu n\'existe pas et qu\'on croit → perte minime ; si Dieu existe et qu\'on ne croit pas → perte infinie. Donc rationnellement il faut parier que Dieu existe. Critique : suppose qu\'on choisit ses croyances, et qu\'un Dieu accepterait une foi calculée.',auteur:'Pascal',tensions:['Pari pragmatique (Pascal) ≠ démonstration rationnelle classique','Foi calculée ≠ foi authentique (Kierkegaard)','Rationalité (calcul) au service de la foi'],notions:['religion','verite','liberte']},

{id:'illusion',term:'Illusion',cat:'Philosophie / Psychanalyse',def:'À distinguer de l\'erreur (qu\'on peut corriger) et du mensonge (intentionnel). Une <strong>illusion</strong> est une croyance fausse motivée par un <em>désir</em>. Freud (<em>L\'Avenir d\'une illusion</em>, 1927) : la religion est l\'illusion universelle obsessionnelle de l\'humanité — non nécessairement fausse, mais motivée par le désir infantile d\'un père protecteur. Marx élargit : toute idéologie peut être une illusion qui exprime et compense un manque réel.',auteur:'Freud / Marx / Feuerbach',tensions:['Illusion (motivée par le désir) ≠ erreur (corrigible)','Illusion ≠ hallucination (pathologique)','Critique de l\'illusion ≠ destruction de l\'expérience qui la motive'],notions:['religion','conscience','inconscient'],
liens:{religion:'Pour la notion Religion, l\'illusion est l\'angle critique : la religion ne serait pas démontrée fausse, mais expliquée par le désir (un père protecteur). C\'est exactement ce que refuse NOMA, qui interdit à la science de juger le magistère religieux.'},
relations:[{to:'aliénation-religieuse',type:'prolonge',desc:'Feuerbach (Dieu = projection des aspirations humaines) puis Marx fournissent le socle critique que Freud reprend et déplace vers le désir inconscient.'}],modified:true},

{id:'lumieres',term:'Lumières',cat:'Histoire de la philosophie',def:'Mouvement philosophique européen du XVIIIe siècle (<em>Aufklärung</em>, <em>Enlightenment</em>) qui place la <strong>raison</strong> au cœur du progrès humain. « <em>Sapere aude !</em> Aie le courage de te servir de ton propre entendement » (Kant, <em>Qu\'est-ce que les Lumières ?</em>, 1784). Critique de l\'autorité (religieuse, politique), promotion de la science, de la tolérance, de l\'éducation universelle. Côté religieux : développe le déisme et la religion naturelle, critique des dogmes révélés.',auteur:'Kant / Voltaire / Diderot',tensions:['Lumières (raison) ≠ tradition (autorité)','Religion naturelle des Lumières ≠ religion révélée','Émancipation par la raison ≠ confiance dans l\'autorité'],notions:['raison','liberte','religion']},

{id:'theisme-deisme',term:'Théisme / Déisme',cat:'Religion',def:'<strong>Théisme</strong> : croyance en un Dieu personnel, créateur et providentiel, qui intervient dans le monde et entretient une relation avec les hommes (judaïsme, christianisme, islam). <strong>Déisme</strong> : croyance en un Dieu créateur qui ne se révèle pas, n\'agit pas providentiellement, accessible par la seule raison (sans révélation). Le déisme est typique des Lumières (Voltaire). S\'opposent à l\'<em>athéisme</em> (négation de toute divinité) et à l\'<em>agnosticisme</em> (suspension du jugement).',auteur:'Voltaire / Rousseau',tensions:['Théisme (Dieu personnel) ≠ déisme (Dieu impersonnel)','Théisme/déisme (avec Dieu) ≠ athéisme (sans Dieu)','Déisme (raison) ≠ révélation'],notions:['religion','raison']},

{id:'dogme',term:'Dogme',cat:'Religion',def:'Du grec <em>dogma</em>, « opinion, décision ». Vérité fondamentale d\'une religion ou d\'une doctrine, présentée comme <strong>indiscutable</strong> et requérant l\'assentiment du fidèle (Trinité, Incarnation pour le christianisme). Par extension, toute croyance imposée sans démonstration. Les Lumières (et Kant) critiquent les dogmes au nom de l\'autonomie de la raison. Mais le dogme religieux n\'est pas <em>nécessairement</em> irrationnel : il marque la limite que la raison atteint sans pouvoir la franchir.',auteur:'Thomas d\'Aquin / Kant',tensions:['Dogme (donné, indiscutable) ≠ thèse philosophique (argumentée)','Dogme ≠ vérité scientifique (toujours révisable, Popper)','Dogmatisme ≠ scepticisme'],notions:['religion','raison','verite']},

{id:'experimentation',term:'Expérimentation',cat:'Méthodologie scientifique',def:'Procédure méthodique consistant à <strong>provoquer un phénomène</strong> dans des conditions contrôlées pour le mesurer et tester une hypothèse. Distincte de la simple <em>observation</em> (passive) : l\'expérimentation construit son objet, isole les variables, vise la reproductibilité. Pour Popper, c\'est le critère opérationnel de la science : une théorie est scientifique si l\'on peut concevoir une expérimentation qui pourrait la <em>réfuter</em>. Bachelard : la nature étudiée par la science est une nature « <em>technicisée</em> », jamais brute.',auteur:'Bacon / Popper / Bachelard',tensions:['Expérimentation (construite) ≠ observation (passive)','Sciences expérimentales ≠ sciences formelles (déduction pure)','Reproductibilité ≠ témoignage unique'],notions:['raison','verite','technique']},

{id:'epistemologie',term:'Épistémologie',cat:'Philosophie des sciences',def:'Du grec <em>épistémé</em> (savoir) + <em>logos</em> (discours). <strong>Théorie de la connaissance scientifique</strong> : ses fondements, sa méthode, ses limites. Pose plusieurs problèmes : (1) la <em>démarcation</em> science / non-science (Popper : falsifiabilité) ; (2) l\'<em>unité</em> de la science (une méthode, plusieurs objets) ; (3) la <em>classification</em> des sciences (Comte) ; (4) la <em>genèse</em> de la connaissance (Bachelard, Kuhn). Distincte de la gnoséologie (théorie générale de la connaissance, incluant la connaissance commune).',auteur:'Comte / Popper / Bachelard / Kuhn',tensions:['Épistémologie (sciences) ≠ gnoséologie (connaissance en général)','Épistémologie continue (positivisme) ≠ discontinue (Bachelard, Kuhn)','Théorie de la science ≠ pratique scientifique'],notions:['raison','verite']},

{id:'induction',term:'Induction',cat:'Logique / Épistémologie',def:'Forme de <strong>raisonnement</strong> consistant à se baser sur un ensemble d\'expériences <em>particulières</em> pour aboutir à une conclusion <em>générale</em>. Exemple : « il a fait beau les jours précédents, donc il fera beau demain. » Caractéristique des sciences expérimentales. <strong>Problème de l\'induction</strong> (Hume, Russell) : aucune accumulation finie d\'observations ne prouve une loi universelle — la conclusion reste seulement <em>probable</em>. Popper en déduira la falsifiabilité comme critère de scientificité.',auteur:'Aristote / Hume / Russell / Popper',tensions:['Induction (particulier → général) ≠ déduction (général → particulier)','Vérité conjecturale (probable) ≠ démonstration nécessaire','Sciences empiriques (induction) ≠ sciences formelles (déduction)'],notions:['raison','verite','science']},

{id:'deduction',term:'Déduction',cat:'Logique',def:'Forme de raisonnement consistant à faire <em>découler</em> d\'une théorie ou d\'un principe général des conclusions particulières. Exemple : « Tous les nombres divisibles par 2 sont pairs ; 4 est divisible par 2 ; donc 4 est pair. » Caractéristique des <strong>mathématiques</strong> et de la logique formelle. La validité déductive ne garantit pas la vérité matérielle des conclusions : si les prémisses sont fausses, le raisonnement reste valide mais ne <em>démontre</em> rien (sophisme).',auteur:'Aristote',tensions:['Déduction (du général au particulier) ≠ induction (du particulier au général)','Validité formelle ≠ vérité matérielle','Démonstration ≠ raisonnement'],notions:['raison','verite']},

{id:'rationnel-raisonnable',term:'Rationnel / Raisonnable',cat:'Théorie de la raison',def:'Distinction classique. Le <strong>rationnel</strong> renvoie au rôle de la raison dans la <em>connaissance</em> : se conformer aux principes de la logique (non-contradiction) pour produire des raisonnements valides et congruents. Le <strong>raisonnable</strong> renvoie à l\'ordre de l\'<em>action</em> : être conforme aux normes socio-culturelles, paraître sensé. On peut être logiquement rationnel sans être moralement raisonnable, et inversement.',auteur:'Kant',tensions:['Rationnel (logique) ≠ raisonnable (sage)','Raison théorique (connaître) ≠ raison pratique (agir)','Universalité logique ≠ universalité normative'],notions:['raison','devoir']},

{id:'raison-instrumentale',term:'Raison instrumentale',cat:'Critique de la raison',def:'Raison qui calcule les <strong>moyens efficaces</strong> pour atteindre des fins sans s\'interroger sur les fins elles-mêmes. Caractéristique de la modernité technique. Critiquée par <strong>Hans Jonas</strong> (<em>Le Principe responsabilité</em>) : son pouvoir d\'agir excède notre capacité morale. <strong>Günther Anders</strong> (<em>L\'Obsolescence de l\'homme</em>) : « honte prométhéenne » — la bombe atomique excède notre imagination morale. <strong>Aimé Césaire</strong> (<em>Discours sur le colonialisme</em>) : le colonialisme comme raison instrumentale appliquée à des humains.',auteur:'Jonas / Anders / Césaire',tensions:['Raison instrumentale (moyens) ≠ raison essentielle (fins)','Efficacité technique ≠ légitimité morale','Pouvoir d\'agir ≠ pouvoir de prévoir et de répondre'],notions:['raison','technique','devoir']},

{id:'metriopathie',term:'Métriopathie',cat:'Éthique antique',def:'Du grec <em>metrios</em> (mesuré) + <em>pathos</em> (affection). Pour Épicure (<em>Lettre à Ménécée</em>) : <strong>calcul rationnel des plaisirs et des peines</strong> qui permet de hiérarchiser les désirs (naturels et nécessaires > naturels non nécessaires > vains) et d\'atteindre l\'<em>ataraxie</em>. La raison y joue un rôle essentiel : on n\'est pas heureux par accumulation de plaisirs mais par leur juste mesure. Distincte de l\'<em>apatheia</em> stoïcienne (absence totale de passion) : la métriopathie modère les passions, ne les supprime pas.',auteur:'Épicure',tensions:['Métriopathie (mesure des passions) ≠ apatheia (suppression des passions, stoïcisme)','Calcul rationnel ≠ ascétisme','Bonheur quantitatif ≠ qualitatif'],notions:['bonheur','raison']},

{id:'tetrapharmakon',term:'Tetrapharmakon',cat:'Éthique antique',def:'Du grec <em>tettara</em> (quatre) + <em>pharmakon</em> (remède). <strong>Quadruple remède</strong> épicurien contre les quatre grandes peurs qui troublent l\'âme : (1) <em>les dieux ne s\'occupent pas de nous</em> (donc inutile de les craindre) ; (2) <em>la mort n\'est rien pour nous</em> (quand elle est, nous ne sommes plus) ; (3) <em>le plaisir est facile à obtenir</em> (par des désirs naturels et nécessaires) ; (4) <em>la douleur est facile à supporter</em> (intense = brève ; longue = supportable). La raison thérapeutique libère l\'âme par <em>argumentation</em>, non par mystique.',auteur:'Épicure / Philodème',tensions:['Tetrapharmakon (raison guérissante) ≠ révélation religieuse','Philosophie comme médecine ≠ contemplation pure'],notions:['bonheur','raison']},

{id:'idee-rude',term:'Idée rude (représentation)',cat:'Stoïcisme',def:'Pour les Stoïciens (Épictète, <em>Manuel</em>) : <strong>représentation immédiate</strong> et non examinée qui s\'impose à l\'esprit (« cet homme m\'a insulté », « la mort est un mal »). Elle saisit l\'âme avant tout jugement rationnel. La raison doit <em>tester</em> cette représentation par la <em>prosochè</em> (attention) : suspendre l\'assentiment, distinguer ce qui dépend de nous (notre jugement) de ce qui n\'en dépend pas (les événements), corriger la représentation si elle est erronée. Exercice rationnel constant qui rend le sage invulnérable au trouble.',auteur:'Épictète',tensions:['Idée rude (immédiate) ≠ idée examinée (raison)','Assentiment immédiat ≠ assentiment réfléchi','Stoïcisme (correction par la raison) ≠ scepticisme (suspension permanente)'],notions:['raison','bonheur','conscience']},

{id:'principe-non-contradiction',term:'Principe de non-contradiction',cat:'Logique',def:'Principe fondamental de la logique (Aristote, <em>Métaphysique</em>, livre Γ) : <strong>il est impossible que le même attribut appartienne et n\'appartienne pas en même temps au même sujet et sous le même rapport</strong>. Formalisé : ¬(A ∧ ¬A). Principe « le plus ferme de toute démonstration » selon Aristote — celui qu\'on ne peut pas refuser sans le présupposer (qui dit « il y a contradiction » s\'appuie sur lui). Critère de la <em>vérité-cohérence</em> : une théorie est vraie si elle n\'est pas contradictoire.',auteur:'Aristote',tensions:['Non-contradiction (logique classique) ≠ logiques paraconsistantes (admettant des contradictions)','Principe formel ≠ contradiction dialectique (Hegel : la contradiction motrice du devenir)'],notions:['raison','verite']},

{id:'pragmatisme',term:'Pragmatisme',cat:'Philosophie',def:'Du grec <em>pragma</em> (action). Courant philosophique américain (Peirce, James, Dewey) fin XIXe – début XXe siècle. Thèse centrale : la valeur d\'une idée se mesure à ses <strong>conséquences pratiques</strong>, non à sa correspondance abstraite avec un réel. Une idée est vraie en tant qu\'elle « marche », qu\'elle est utile et féconde. Le pragmatisme refuse les questions métaphysiques que la pratique ne peut trancher. <em>Maxime pragmatique</em> (Peirce) : « Pour clarifier une idée, considérer ses effets pratiques. »',auteur:'Peirce / James / Dewey',tensions:['Pragmatisme (vérité-utilité) ≠ correspondance (vérité-adéquation)','Conséquences pratiques ≠ vérité abstraite','Refus de la métaphysique stérile ≠ relativisme'],notions:['verite','science','raison']},

{id:'verite-correspondance',term:'Vérité-correspondance',cat:'Théorie de la vérité',def:'Conception classique : une proposition est vraie si elle <strong>correspond</strong> (s\'accorde) avec le réel qu\'elle décrit. « La neige est blanche » est vrai ssi la neige est blanche (Tarski). Critère <em>externe</em> : la vérité est un rapport entre langage et monde. Difficulté : comment vérifier l\'accord ? Le réel ne se donne jamais « brut » mais à travers un langage. Aristote : « Dire de ce qui est qu\'il est, et de ce qui n\'est pas qu\'il n\'est pas, c\'est dire le vrai. »',auteur:'Aristote / Tarski',tensions:['Correspondance (externe) ≠ cohérence (interne)','Adéquation au réel ≠ utilité pratique (pragmatisme)','Vérité (du jugement) ≠ réalité (de la chose)'],notions:['verite','langage']},

{id:'verite-coherence',term:'Vérité-cohérence',cat:'Théorie de la vérité',def:'Conception <em>interne</em> de la vérité : un système de propositions est vrai si ses énoncés sont mutuellement <strong>compatibles</strong> (ne se contredisent pas). Critère du <em>principe de non-contradiction</em>. Caractéristique des sciences formelles (mathématiques, logique) où les axiomes engendrent un système cohérent. Limite : la cohérence est nécessaire mais non suffisante — un système cohérent peut être faux par rapport au réel (une fiction cohérente reste fictive).',auteur:'Spinoza / Hegel / Leibniz',tensions:['Cohérence (interne) ≠ correspondance (externe)','Système cohérent ≠ système vrai','Nécessaire (non-contradiction) ≠ suffisant (vérification)'],notions:['verite','raison','science']},

{id:'verite-instrumentale',term:'Vérité instrumentale',cat:'Pragmatisme',def:'Théorie pragmatique de la vérité (William James, <em>Le Pragmatisme</em>, 1907) : une idée est vraie en tant qu\'elle <strong>fonctionne</strong>, qu\'elle nous met efficacement en rapport avec d\'autres expériences. La vérité n\'est pas adéquation contemplative mais <em>processus de vérification</em> : « Le vrai consiste tout simplement dans ce qui est avantageux pour notre pensée. » Idées et théories sont des <em>outils</em> évalués par leur fécondité — comme un instrument se juge à son efficacité, non à sa beauté.',auteur:'William James / Dewey',tensions:['Vérité instrumentale (utilité) ≠ vérité correspondance (adéquation)','Vérité-processus ≠ vérité-état','Pragmatisme ≠ relativisme (la vérité reste contraignante par ses effets)'],notions:['verite','science']},
{new:true,id:'rasoir-ockham',term:'Rasoir d\'Ockham',cat:'Épistémologie / Logique',def:'Principe de <strong>parcimonie</strong> (ou d\'économie, de simplicité), du nom du franciscain <em>Guillaume d\'Ockham</em> (XIV<sup>e</sup> siècle). Formulation latine : <em>« Pluralitas non est ponenda sine necessitate »</em> — « la pluralité ne doit pas être posée sans nécessité ». Règle méthodologique : face à plusieurs explications concurrentes d\'un même phénomène, préférer celle qui mobilise le <strong>moins d\'hypothèses ou d\'entités</strong>. La formule plus célèbre <em>« Entia non sunt multiplicanda praeter necessitatem »</em> (« les entités ne doivent pas être multipliées au-delà du nécessaire ») lui est attribuée mais ne figure pas dans ses écrits. Ce n\'est pas un critère de vérité — le plus simple n\'est pas toujours le vrai — mais un critère de <em>choix rationnel</em> entre théories : c\'est à ce titre que James en fait l\'un des critères (la « simplicité ») d\'une idée tenue pour vraie.',auteur:'Guillaume d\'Ockham',notions:['science','verite','raison'],relations:[{to:'verite-instrumentale',type:'complete',desc:'La simplicité est l\'un des critères pragmatiques (James) d\'une idée qui fonctionne.'},{to:'falsifiabilite',type:'complete',desc:'Deux règles méthodologiques d\'évaluation et de choix entre théories scientifiques.'},{type:'distinction',desc:'Simplicité (économie d\'hypothèses) ≠ vérité (le plus simple n\'est pas nécessairement le vrai).'}]},

{id:'theiere-russell',term:'Théière de Russell',cat:'Épistémologie',def:'Argument forgé par Bertrand Russell (<em>Is There a God?</em>, 1952) : « Si je suggérais qu\'entre la Terre et Mars se trouve une théière de porcelaine en orbite elliptique autour du Soleil, trop petite pour être détectée par nos plus puissants télescopes, personne ne serait à même de réfuter mon allégation. » Mais l\'irréfutabilité n\'est pas une preuve. La <strong>charge de la preuve</strong> incombe à celui qui affirme l\'existence d\'une entité, non au sceptique. Argument transposé : Dieu, comme la théière, est une hypothèse infalsifiable dont l\'irréfutabilité ne justifie pas la croyance.',auteur:'Russell',tensions:['Irréfutable ≠ vrai','Charge de la preuve (sur l\'affirmateur) ≠ charge de la réfutation (sur le sceptique)','Théière privée ≠ théière sacrée (variable culturelle)'],notions:['religion','science','verite']},
{new:true,id:'agnosticisme',term:'Agnosticisme',cat:'Philosophie de la religion',def:'Position qui consiste à <strong>suspendre son jugement</strong> sur l\'existence de Dieu, faute de preuve décisive dans un sens ou dans l\'autre (terme forgé par T. H. Huxley en 1869, du grec <em>a-gnôsis</em>, « sans connaissance »). À distinguer de l\'<strong>athéisme</strong> (qui affirme que Dieu n\'existe pas) et du <strong>théisme</strong> (qui affirme qu\'il existe) : l\'agnostique ne tranche pas, jugeant la question indécidable. Russell (<em>Is There a God ?</em>, 1952) s\'en réclame en pratique : l\'existence de Dieu étant une hypothèse <em>infalsifiable</em> (cf. la théière) et la <strong>charge de la preuve</strong> incombant à qui affirme une existence, le doute est l\'attitude rationnelle par défaut. Prolonge l\'<em>épochè</em> sceptique (suspension du jugement).',auteur:'Huxley / Russell',notions:['religion','verite'],relations:[{to:'theiere-russell',type:'prolonge',desc:'Faute de preuve, et la charge incombant à l\'affirmateur, on suspend le jugement.'},{to:'scepticisme',type:'prolonge',desc:'Application à la question de Dieu de la suspension sceptique du jugement.'},{to:'epoche',type:'complete',desc:'L\'agnostique pratique l\'épochè sur l\'existence divine.'},{type:'distinction',desc:'Agnosticisme (« je ne sais pas ») ≠ athéisme (« Dieu n\'existe pas ») ≠ théisme (« Dieu existe »).'}]},

{id:'probleme-induction',term:'Problème de l\'induction',cat:'Épistémologie',def:'Problème logique posé par Hume et radicalisé par <strong>Russell</strong> (<em>Problèmes de Philosophie</em>, 1912) : aucune accumulation finie d\'observations passées ne <em>prouve</em> qu\'une régularité se maintiendra à l\'avenir. « Le soleil s\'est levé chaque jour » ne démontre pas qu\'il se lèvera demain. Toute connaissance empirique est donc <em>conjecturale</em>, non nécessaire. Conséquence majeure : les sciences expérimentales reposent sur un acte de foi inductif. Popper en tire la <strong>falsifiabilité</strong> : si l\'induction ne prouve rien, c\'est la <em>réfutation</em> (et non la confirmation) qui définit la science.',auteur:'Hume / Russell / Popper',tensions:['Conclusion inductive ≠ démonstration déductive','Probabilité ≠ certitude','Confirmation (illusoire) ≠ réfutation (cruciale)'],notions:['raison','science','verite']},

{id:'religiosite-cosmique',term:'Religiosité cosmique',cat:'Philosophie de la religion',def:'Concept einsteinien (<em>Comment je vois le monde</em>, 1934) : sentiment religieux qui ne porte pas sur un Dieu personnel mais sur l\'<strong>admiration extasiée de l\'harmonie de la nature</strong>. Le savant remplace l\'espoir de la sollicitude divine par l\'émerveillement devant l\'<em>intelligibilité</em> du cosmos. Religiosité <em>compatible avec</em> et <em>nourrie par</em> la pratique scientifique — c\'est le « Dieu de Spinoza » : la nécessité harmonieuse du tout. Pas de prière efficace ni de providence, mais une forme de gratitude métaphysique.',auteur:'Einstein / Spinoza',tensions:['Religiosité cosmique ≠ religion personnelle (Dieu providentiel)','Émerveillement scientifique ≠ scientisme (qui prétendrait épuiser le sens)','Spinozisme ≠ athéisme strict'],notions:['religion','science','nature'],
liens:{religion:'Pour la notion Religion, ce concept déplace la frontière du religieux : la religiosité n\'est plus la croyance en un Dieu personnel (la « religion de l\'homme simple », anthropomorphique), mais une attitude d\'émerveillement devant l\'ordre du monde — la « religiosité du savant ».',science:'Pour la notion Science, Einstein montre que l\'activité scientifique peut reposer sur une forme de foi : la conviction que l\'univers est ordonné et intelligible précède et soutient la recherche. Une « religiosité » sans dogme ni providence.'},
relations:[{to:'noma',type:'prolonge',desc:'Comme Gould, Einstein articule science et religion sans conflit ; mais là où NOMA les sépare en deux magistères, Einstein les unit dans une même attitude d\'émerveillement devant l\'intelligibilité du cosmos.'},{to:'illusion',type:'oppose',desc:'La religiosité cosmique du savant n\'est pas l\'illusion freudienne du père protecteur : elle ne console pas, elle n\'attend rien d\'un Dieu personnel — elle contemple la nécessité harmonieuse du tout.'}]},

{id:'pari-pascalien-religion',term:'Pari pascalien (décisionnel)',cat:'Philosophie de la religion',def:'Argument décisionnel de <strong>Pascal</strong> (<em>Pensées</em>, 1670) face à l\'incertitude rationnelle sur l\'existence de Dieu. « Il faut parier ; cela n\'est pas volontaire, vous êtes embarqué. » Quatre issues : (1) Dieu existe et je crois → gain infini ; (2) Dieu existe et je ne crois pas → perte infinie ; (3) Dieu n\'existe pas et je crois → perte finie ; (4) Dieu n\'existe pas et je ne crois pas → gain fini. L\'<em>espérance mathématique</em> est en faveur de la croyance. <strong>« Gagez donc qu\'il est, sans hésiter. »</strong> Premier exemple historique de raisonnement décisionnel sous incertitude.',auteur:'Pascal',tensions:['Pari (décision pratique) ≠ démonstration (preuve théorique)','Croire par calcul ≠ croire par foi','Argument décisionnel ≠ argument ontologique'],notions:['religion','raison','verite']},

{id:'sophisme',term:'Sophisme',cat:'Logique',def:'Raisonnement qui a <em>l\'apparence</em> de la rigueur logique mais conduit à des conclusions absurdes ou trompeuses, soit par fausseté des prémisses, soit par vice de raisonnement. Exemple : « Tous les animaux sont des chiens. Toutes les chaises sont des nombres premiers. Donc tous les animaux sont des nombres premiers. » La forme est valide ; les prémisses sont fausses. Au sens historique, désigne aussi les <strong>Sophistes</strong> grecs (Protagoras, Gorgias) que Platon critique : maîtres de rhétorique qui enseignaient à faire triompher n\'importe quelle thèse sans souci de vérité.',auteur:'Aristote / Platon',tensions:['Raisonnement valide ≠ démonstration vraie','Apparence (rhétorique) ≠ rigueur (logique)','Persuasion ≠ argumentation honnête'],notions:['raison','langage','verite']},

{id:'rationalisme',term:'Rationalisme',cat:'Théorie de la connaissance',def:'Doctrine selon laquelle la <strong>raison</strong> est la source principale (voire unique) de la connaissance vraie. Le rationalisme affirme l\'existence d\'<em>idées innées</em> et de vérités <em>a priori</em> que l\'esprit possède indépendamment de l\'expérience sensible — les sens étant trompeurs. Figures majeures : Descartes (le <em>cogito</em> et les idées claires et distinctes), Spinoza, Leibniz. S\'oppose à l\'empirisme. Kant en proposera la synthèse : la connaissance combine la matière sensible (expérience) et les formes <em>a priori</em> du sujet.',auteur:'Descartes / Spinoza / Leibniz',tensions:['Rationalisme ≠ empirisme (raison vs expérience)','Idées innées ≠ tabula rasa (Locke)','Vérités a priori ≠ vérités a posteriori'],notions:['raison','verite','science','conscience']},

{id:'empirisme',term:'Empirisme',cat:'Théorie de la connaissance',def:'Doctrine selon laquelle toute connaissance dérive de l\'<strong>expérience</strong> sensible — il n\'y a pas d\'idées innées. L\'esprit à la naissance est une <em>tabula rasa</em> (table rase) sur laquelle l\'expérience inscrit ses données (Locke). Hume radicalise : même la causalité n\'est qu\'une habitude psychologique, non une nécessité rationnelle. Figures majeures : Locke, Hume, Berkeley. S\'oppose au rationalisme. Kant dépassera l\'opposition : « toute connaissance commence avec l\'expérience, mais elle ne dérive pas toute de l\'expérience ».',auteur:'Locke / Hume / Berkeley',tensions:['Empirisme ≠ rationalisme (expérience vs raison)','Tabula rasa ≠ idées innées (Descartes)','Connaissance a posteriori ≠ a priori'],notions:['verite','science','raison','conscience']},
{id:'scepticisme',term:'Scepticisme',cat:'Théorie de la connaissance',def:'Position philosophique qui doute de la possibilité d’atteindre une vérité certaine et recommande la suspension du jugement (épochè). Pyrrhon, Sextus Empiricus, Montaigne (« Que sais-je ? »).',auteur:'Montaigne',notions:['verite','raison','religion'],relations:[{to:'epoche',type:'implique',desc:'Le doute mène à la suspension du jugement.'},{to:'dogme',type:'oppose',desc:'Le sceptique refuse toute affirmation dogmatique.'},{to:'doxa',type:'prolonge',desc:'Faute de savoir certain, on en reste à l’opinion.'}]},
{id:'epoche',term:'Épochè',cat:'Épistémologie antique',def:'Suspension du jugement. Chez les sceptiques, refus d’affirmer ou de nier pour atteindre la tranquillité ; chez Husserl, « mise entre parenthèses » du monde naturel pour décrire les phénomènes tels qu’ils apparaissent à la conscience.',auteur:'Husserl',notions:['verite','conscience','bonheur'],relations:[{to:'scepticisme',type:'prolonge',desc:'Outil central du scepticisme antique.'},{to:'ataraxie',type:'implique',desc:'La suspension du jugement conduit à l’absence de trouble.'}]},
{id:'scientisme',term:'Scientisme',cat:'Philosophie des sciences',def:'Idéologie selon laquelle la science, et elle seule, peut répondre à toutes les questions humaines — y compris morales, métaphysiques et religieuses. Absolutisation de la méthode scientifique, qui outrepasse son domaine de validité.',notions:['science','religion','verite'],relations:[{to:'positivisme',type:'prolonge',desc:'Radicalisation idéologique du positivisme.'},{to:'noma',type:'oppose',desc:'Le NOMA limite la science à son magistère et refuse le scientisme.'},{term:'concordisme',type:'distinction',desc:'Le scientisme absolutise la science ; le concordisme veut accorder science et religion.'}]},
{id:'concordisme',term:'Concordisme',cat:'Philosophie de la religion',def:'Tentative de faire concorder les énoncés des textes religieux avec les découvertes scientifiques, en lisant la science dans les Écritures (ou inversement). Confond les deux registres au lieu de les distinguer.',notions:['religion','science'],relations:[{to:'noma',type:'oppose',desc:'Le NOMA sépare les magistères, le concordisme les superpose.'},{to:'religion-naturelle',type:'distinction',desc:'La religion naturelle se fonde sur la raison ; le concordisme sur l’accord avec les textes révélés.'}]},
{id:'relativisme',term:'Relativisme',cat:'Théorie de la vérité',def:'Doctrine selon laquelle la vérité, le bien ou le beau sont toujours relatifs à un individu, une culture ou une époque : il n’existe pas de vérité universelle. « L’homme est la mesure de toute chose » (Protagoras).',auteur:'Protagoras',notions:['verite','justice','art'],relations:[{to:'doxa',type:'prolonge',desc:'Réduit la vérité à l’opinion variable.'},{to:'scepticisme',type:'prolonge'},{term:'universalisme',type:'oppose',desc:'L’universalisme affirme des vérités valables pour tous.'}]},
{id:'dualisme',term:'Dualisme',cat:'Métaphysique',def:'Thèse métaphysique de l’existence de deux substances distinctes et irréductibles — typiquement l’âme (pensée) et le corps (étendue) chez Descartes, ou l’esprit et la matière.',auteur:'Descartes',notions:['conscience','inconscient'],relations:[{to:'cogito',type:'prolonge',desc:'Le cogito (substance pensante) se distingue du corps étendu.'},{to:'materialisme',type:'oppose'},{term:'monisme',type:'oppose',desc:'Le monisme ne reconnaît qu’une seule substance.'}]},
{id:'materialisme',term:'Matérialisme',cat:'Métaphysique',def:'Doctrine selon laquelle seule la matière existe : la pensée et la conscience sont des produits de l’organisation matérielle. Démocrite (atomisme), Marx (matérialisme historique : les conditions matérielles déterminent les idées).',auteur:'Marx',notions:['conscience','nature','travail'],relations:[{to:'idealisme',type:'oppose',desc:'La matière première (matérialisme) contre l’esprit premier (idéalisme).'},{to:'dualisme',type:'oppose'},{to:'plus-value',type:'prolonge',desc:'Le matérialisme historique de Marx part de l’économie réelle.'}]},
{id:'idealisme',term:'Idéalisme',cat:'Idéalisme',def:'Doctrine selon laquelle la réalité véritable est d’ordre idéel ou spirituel : les Idées (Platon), l’esprit ou la conscience précèdent et fondent le monde sensible. Platon, Berkeley, Hegel.',auteur:'Platon',notions:['conscience','verite'],relations:[{to:'materialisme',type:'oppose'},{to:'anamnese',type:'prolonge',desc:'Connaître, c’est se ressouvenir des Idées.'}]},
{id:'nihilisme',term:'Nihilisme',cat:'Philosophie nietzschéenne',def:'Processus de dévalorisation des valeurs supérieures : « les valeurs suprêmes se dévalorisent ». Avec la « mort de Dieu », le monde paraît privé de sens et de fondement. Nietzsche le diagnostique pour mieux le dépasser.',auteur:'Nietzsche',notions:['religion','liberte','verite'],relations:[{to:'volonte-puissance',type:'oppose',desc:'La volonté de puissance, création de valeurs nouvelles, surmonte le nihilisme.'},{to:'transcendance',type:'oppose',desc:'« Mort de Dieu » : effondrement de l’arrière-monde transcendant.'}]},
{id:'metaphysique',term:'Métaphysique',cat:'Métaphysique',def:'Partie de la philosophie qui étudie ce qui est au-delà du physique : l’être en tant qu’être, Dieu, l’âme, la liberté. « Science des premiers principes et des premières causes » (Aristote). Kant en interroge la possibilité comme science.',auteur:'Aristote',notions:['raison','religion','verite'],relations:[{to:'physis',type:'distinction',desc:'La métaphysique va au-delà de la nature (physis).'},{to:'transcendance',type:'prolonge'}]},
{id:'finalite',term:'Finalité',cat:'Métaphysique',def:'Explication d’un être ou d’un phénomène par sa fin (cause finale, « ce en vue de quoi »), par opposition à l’explication par des causes mécaniques. La nature semble agir en vue d’une fin (téléologie).',auteur:'Aristote',notions:['nature','technique','science'],relations:[{to:'determinisme',type:'oppose',desc:'Cause finale (pourquoi) contre cause efficiente / mécanisme (comment).'},{term:'mécanisme',type:'oppose'}]},
{id:'immanence',term:'Immanence',cat:'Métaphysique / Religion',def:'Caractère de ce qui a son principe en soi-même et reste intérieur au monde, sans cause extérieure ou supérieure. Chez Spinoza, Dieu est immanent à la nature (« Deus sive Natura »).',auteur:'Spinoza',notions:['religion','nature'],relations:[{to:'transcendance',type:'oppose',desc:'L’immanent reste dans le monde ; le transcendant le dépasse.'}]},
{id:'laicite',term:'Laïcité',cat:'Philosophie politique / Religion',def:'Principe de séparation des Églises et de l’État garantissant la neutralité de l’État en matière religieuse et la liberté de conscience de chacun. Distingue l’espace public commun et les convictions privées.',notions:['etat','religion'],relations:[{to:'religion-civile',type:'distinction',desc:'La laïcité neutralise l’État ; la religion civile lui donne un culte commun.'},{to:'contrat-social',type:'prolonge'}]},
{id:'utilitarisme',term:'Utilitarisme',cat:'Éthique',def:'Doctrine morale conséquentialiste qui juge une action selon son utilité, c’est-à-dire sa capacité à produire le plus grand bonheur pour le plus grand nombre. Bentham (calcul des plaisirs), Mill.',auteur:'Mill',notions:['bonheur','justice','devoir'],relations:[{to:'imperatif-categorique',type:'oppose',desc:'Conséquentialisme (utilitarisme) contre déontologie du devoir (Kant).'},{to:'eudaimonia',type:'distinction'}]},
{id:'hedonisme',term:'Hédonisme',cat:'Éthique antique',def:'Doctrine qui fait du plaisir le souverain bien et le but de la vie. L’hédonisme raisonné d’Épicure recherche les plaisirs stables (absence de douleur, ataraxie) plutôt que les plaisirs intenses et inquiets.',auteur:'Épicure',notions:['bonheur'],relations:[{to:'plaisir',type:'prolonge'},{to:'ataraxie',type:'complete',desc:'Le plaisir véritable est l’absence de trouble.'},{to:'eudaimonia',type:'distinction',desc:'Bonheur comme plaisir (hédonisme) vs comme accomplissement (eudaimonia).'}]},
{id:'ideologie',term:'Idéologie',cat:'Philosophie sociale',def:'Chez Marx, système d’idées et de représentations qui présente les intérêts de la classe dominante comme universels et naturels, masquant ainsi les rapports réels de domination.',auteur:'Marx',notions:['etat','travail','justice'],relations:[{to:'alienation',type:'prolonge',desc:'L’idéologie entretient l’aliénation en voilant l’exploitation.'},{to:'plus-value',type:'complete'}]},
{id:'maieutique',term:'Maïeutique',cat:'Philosophie antique',def:'Art socratique d’« accoucher les esprits » : par un jeu de questions, Socrate aide son interlocuteur à mettre au jour la vérité qu’il porte sans le savoir, et à reconnaître son ignorance.',auteur:'Socrate',notions:['raison','verite','langage'],relations:[{to:'anamnese',type:'prolonge',desc:'Accoucher l’âme, c’est l’aider à se ressouvenir.'},{to:'doxa',type:'oppose',desc:'Dépasser l’opinion vers le savoir.'}]},
{id:'humanisme',term:'Humanisme',cat:'Histoire de la philosophie',def:'Courant de pensée qui place l’homme, sa dignité et sa liberté au centre, avec confiance dans la raison et l’éducation. À la Renaissance (Pic de la Mirandole), puis chez Sartre (« l’existentialisme est un humanisme »).',auteur:'Sartre',notions:['liberte','conscience'],relations:[{to:'mauvaise-foi',type:'distinction',desc:'L’humanisme existentialiste assume la liberté que la mauvaise foi fuit.'},{term:'transhumanisme',type:'oppose',desc:'Le transhumanisme veut augmenter l’homme par la technique.'}]},
{id:'monisme',term:'Monisme',cat:'Métaphysique',def:'Thèse métaphysique selon laquelle il n’existe qu’une seule substance ou un seul principe ultime du réel, par opposition au dualisme. Chez Spinoza, il n’y a qu’une substance infinie, Dieu ou la Nature (« Deus sive Natura »), dont l’esprit et le corps sont deux attributs.',auteur:'Spinoza',notions:['conscience','nature','religion'],relations:[{to:'dualisme',type:'oppose',desc:'Une seule substance (monisme) contre deux (dualisme).'},{to:'immanence',type:'prolonge',desc:'Spinoza : une substance unique et immanente au monde.'}]},
{id:'mecanisme',term:'Mécanisme',cat:'Philosophie des sciences',def:'Doctrine qui explique tous les phénomènes, y compris le vivant, par des causes matérielles et des lois physiques, comme une machine — excluant les causes finales. Descartes réduit l’animal à une « machine » (animal-machine).',auteur:'Descartes',notions:['nature','science','technique'],relations:[{to:'finalite',type:'oppose',desc:'Le mécanisme explique par les causes efficientes, non par les fins.'},{to:'determinisme',type:'prolonge'},{to:'elan-vital',type:'oppose',desc:'Le vitalisme (élan vital) refuse de réduire le vivant à une machine.'}]},
{id:'universalisme',term:'Universalisme',cat:'Théorie de la vérité',def:'Position selon laquelle certaines vérités, valeurs ou droits valent pour tous les hommes, indépendamment des cultures et des époques. S’oppose au relativisme. Fondement des droits de l’homme et de la morale kantienne.',auteur:'Kant',notions:['verite','justice','devoir'],relations:[{to:'relativisme',type:'oppose',desc:'Vérités valables pour tous (universalisme) contre vérités relatives (relativisme).'},{to:'imperatif-categorique',type:'prolonge',desc:'La loi morale vaut universellement.'}]},
{id:'reification',term:'Réification',cat:'Philosophie sociale',def:'Fait de transformer des rapports humains et sociaux en rapports entre choses, et de traiter une personne comme un simple objet. Liée chez Marx au « fétichisme de la marchandise » ; développée par Lukács.',auteur:'Marx',notions:['travail','justice','conscience'],relations:[{to:'alienation',type:'prolonge',desc:'La réification est une forme d’aliénation.'},{to:'plus-value',type:'complete'}]},
{id:'providence',term:'Providence',cat:'Philosophie de la religion',def:'Gouvernement du monde par Dieu, qui dirige le cours des choses vers une fin bonne. Soulève le problème du mal : comment concilier un Dieu bon et tout-puissant avec l’existence du mal (théodicée) ?',notions:['religion','nature','temps'],relations:[{to:'finalite',type:'prolonge',desc:'Le monde est ordonné en vue d’une fin voulue par Dieu.'},{to:'transcendance',type:'prolonge'},{term:'théodicée',type:'implique',desc:'Justifier la bonté de Dieu face au mal.'}]},
{id:'a-priori-posteriori',term:'A priori / a posteriori',cat:'Théorie de la connaissance',def:'Distinction kantienne : est <em>a priori</em> ce qui est indépendant de l’expérience (ex. les vérités mathématiques, universelles et nécessaires) ; est <em>a posteriori</em> ce qui en dérive (les connaissances empiriques, particulières et contingentes).',auteur:'Kant',notions:['raison','science','verite'],relations:[{to:'rationalisme',type:'prolonge',desc:'Le rationalisme valorise la connaissance a priori.'},{to:'empirisme',type:'distinction',desc:'L’empirisme fonde tout sur l’a posteriori.'}]},
{id:'inne-acquis',term:'Inné / acquis',cat:'Anthropologie philosophique',def:'Opposition entre ce qui est présent dès la naissance (inné) et ce qui résulte de l’apprentissage et du milieu (acquis). Au cœur du débat nature / culture sur ce qui définit l’homme.',notions:['nature','conscience','liberte'],relations:[{to:'tabula-rasa',type:'prolonge',desc:'Pour Locke, l’esprit est vierge : tout est acquis.'},{term:'idées innées',type:'oppose',desc:'Le rationalisme défend des idées innées.'}]},
{id:'contingence-necessite',term:'Contingence / nécessité',cat:'Métaphysique',def:'Est <strong>nécessaire</strong> ce qui ne peut pas ne pas être (et ne peut être autrement) ; est <strong>contingent</strong> ce qui peut être ou ne pas être, ce qui aurait pu être autrement. La liberté suppose une part de contingence.',notions:['liberte','nature','temps'],relations:[{to:'determinisme',type:'distinction',desc:'Le déterminisme rend tout nécessaire ; la contingence ouvre du possible.'},{to:'libre-arbitre',type:'implique'}]},
{id:'finitude',term:'Finitude',cat:'Phénoménologie existentiale',def:'Caractère de l’existence humaine limitée, mortelle et temporelle. L’homme est un être fini, conscient de ses limites et de sa mort, ce qui donne sens et urgence à son existence.',auteur:'Heidegger',notions:['temps','conscience','religion'],relations:[{to:'etre-vers-mort',type:'prolonge',desc:'L’existence est un « être-vers-la-mort ».'},{to:'angoisse',type:'implique',desc:'La conscience de la finitude suscite l’angoisse.'}]},
{id:'sublimation',term:'Sublimation',cat:'Psychanalyse',def:'Mécanisme par lequel une pulsion (notamment sexuelle) est détournée de son but premier vers une activité socialement valorisée — art, science, création. Forme « réussie » de transformation des pulsions, distincte du refoulement.',auteur:'Freud',notions:['inconscient','art','travail'],relations:[{to:'pulsion',type:'prolonge',desc:'La sublimation réoriente l’énergie pulsionnelle.'},{to:'refoulement',type:'distinction',desc:'Le refoulement bloque la pulsion ; la sublimation la réoriente.'},{to:'catharsis',type:'complete'}],new:true},
{new:true,id:'post-verite',term:'Post-vérité',cat:'Théorie de la vérité',def:'Néologisme élu « mot de l’année » par l’Oxford English Dictionary en 2016 (<em>post-truth</em>) : situation où, dans le débat public, les faits objectifs comptent moins, dans la formation de l’opinion, que l’appel à l’émotion et aux croyances personnelles. Le préfixe « post » ne signifie pas « après la vérité » mais « la vérité <em>n’est plus pertinente</em> ». Cas d’école : campagne pour le Brexit (2016), discours de Trump (« faits alternatifs »), désinformation algorithmique sur les réseaux sociaux. Lecture nietzschéenne (Emmanuel Salanevris) : la post-vérité prolonge le diagnostic de Nietzsche selon lequel « il n’y a pas de faits, seulement des interprétations » — la « volonté de vérité » a perdu son autorité régulatrice, et avec elle l’horizon commun qui rendait possible le débat rationnel.',auteur:'Nietzsche (héritage) / Salanevris',notions:['verite','raison','etat','langage'],relations:[{to:'verite-correspondance',type:'oppose',desc:'La post-vérité abandonne l’exigence d’adéquation aux faits.'},{to:'relativisme',type:'prolonge',desc:'Forme contemporaine et politique du relativisme.'},{to:'nihilisme',type:'prolonge',desc:'Effondrement de la valeur régulatrice du vrai diagnostiqué par Nietzsche.'},{to:'sophisme',type:'prolonge',desc:'Comme les sophistes antiques, séduire l’opinion plutôt que démontrer.'},{to:'novlangue',type:'complete',desc:'La novlangue appauvrit le pensable, la post-vérité disqualifie le vrai.'}]},
{new:true,id:'ressentiment',term:'Ressentiment',cat:'Philosophie nietzschéenne',def:'Concept central de Nietzsche (<em>Généalogie de la morale</em>, 1887) : impuissance vengeresse de qui ne peut <em>agir</em> et qui, à défaut, <em>réagit</em> en dévalorisant le fort et en érigeant sa propre faiblesse en vertu (« morale d’esclaves »). Le ressentiment retourne contre l’autre une haine qu’il ne peut décharger par l’action. Mécanisme inversé : ce que l’aristocrate appelle <em>bon</em> (puissance, joie, affirmation), l’homme du ressentiment l’appelle <em>mal</em> ; sa propre impuissance devient <em>bonté</em>. Diagnostic contemporain (Martine Béland) : la culture du <em>like</em>, la culpabilisation moralisatrice et l’indignation permanente sur les réseaux sociaux rejouent la structure du ressentiment.',auteur:'Nietzsche',notions:['liberte','justice','devoir','etat'],relations:[{to:'volonte-puissance',type:'oppose',desc:'La volonté de puissance affirme ; le ressentiment réagit.'},{to:'transvaluation-valeurs',type:'implique',desc:'Le ressentiment opère une première transvaluation (bon/mauvais → bien/mal).'},{to:'nihilisme',type:'prolonge',desc:'La morale du ressentiment prépare le nihilisme passif.'}]},
{new:true,id:'transvaluation-valeurs',term:'Transvaluation des valeurs',cat:'Philosophie nietzschéenne',def:'Programme nietzschéen (<em>Umwertung aller Werte</em>, « renversement de toutes les valeurs ») : retourner l’étiquette morale donnée aux valeurs régnantes pour libérer la vie. Première transvaluation, déjà accomplie dans l’histoire selon Nietzsche : l’aristocratique « <em>bon vs mauvais</em> » (fort/faible, noble/vil) a été renversé par la « morale des esclaves » en « <em>bien vs mal</em> » (humilité/orgueil, charité/égoïsme). Tâche du surhumain : opérer une <em>seconde</em> transvaluation, par-delà bien et mal, qui rende leur valeur aux forces affirmatives de la vie. Programme inséparable de la « mort de Dieu » : sans garantie transcendante, c’est à l’homme de créer ses propres valeurs.',auteur:'Nietzsche',notions:['liberte','devoir','religion','verite'],relations:[{to:'ressentiment',type:'prolonge',desc:'La première transvaluation est l’œuvre du ressentiment.'},{to:'surhumain',type:'implique',desc:'La seconde transvaluation est la tâche du surhumain.'},{to:'volonte-puissance',type:'complete'},{to:'nihilisme',type:'oppose',desc:'Créer de nouvelles valeurs contre l’effondrement nihiliste.'}]},
{new:true,id:'surhumain',term:'Surhumain (Übermensch)',cat:'Philosophie nietzschéenne',def:'Figure centrale d’<em>Ainsi parlait Zarathoustra</em> (1883–1885) — traduit aussi par « surhomme », mais le terme allemand <em>Übermensch</em> dit littéralement « <em>par-dessus</em> l’homme » : non un super-humain biologique, mais l’homme qui se <em>dépasse</em> lui-même. « L’homme est quelque chose qui doit être surmonté. » Le surhumain assume la mort de Dieu, refuse les arrière-mondes religieux et le ressentiment, crée ses propres valeurs et dit oui à la vie y compris à l’éternel retour. Affinité, selon Dorian Astor, avec les <em>esprits libres</em> de la bohème : ceux qui supportent l’expérimentation, la dissonance, la solitude créatrice — non pas dominer autrui mais se rendre capable de soi.',auteur:'Nietzsche',notions:['liberte','art','religion'],relations:[{to:'volonte-puissance',type:'prolonge',desc:'Le surhumain réalise la volonté de puissance affirmative.'},{to:'transvaluation-valeurs',type:'implique',desc:'Le surhumain opère la seconde transvaluation.'},{to:'ressentiment',type:'oppose',desc:'Le surhumain a vaincu le ressentiment en lui.'},{to:'nihilisme',type:'oppose',desc:'Réponse affirmative au diagnostic du nihilisme.'}]},
{new:true,id:'gregarite',term:'Grégarité',cat:'Philosophie nietzschéenne',def:'Concept nietzschéen : tendance des hommes à se rassembler en « troupeau » (<em>Herde</em>) — à penser, sentir et juger comme tout le monde par peur de la solitude et de la dissonance. La morale grégaire est celle de l’uniformité, de la moyenne, du <em>conformisme</em>. Diagnostic contemporain (Stéphanie Floccari) : la « tyrannie du <em>like</em> » sur les réseaux sociaux est une grégarité moderne — chaque utilisateur s’aligne sur le plébiscite numérique du groupe, sacrifie la pluralité des points de vue à la quête de reconnaissance. La grégarité fait obstacle aux « esprits libres » et au surhumain.',auteur:'Nietzsche',notions:['liberte','etat','verite'],relations:[{to:'surhumain',type:'oppose',desc:'Le surhumain s’extrait du troupeau ; l’esprit grégaire s’y dissout.'},{to:'servitude-volontaire',type:'prolonge',desc:'La grégarité est servitude volontaire à l’opinion moyenne.'},{to:'ressentiment',type:'complete',desc:'La morale grégaire prolonge la morale du ressentiment.'}]},
{new:true,id:'fonction-fabulatrice',term:'Fonction fabulatrice',cat:'Philosophie de la religion',def:'Concept de Bergson (<em>Les Deux Sources de la morale et de la religion</em>, 1932) : faculté humaine spontanée à produire des récits, des mythes, des « représentations fantasmatiques » qui simulent une présence vivante là où il n’y a que des forces aveugles. Réponse de la nature à un risque vital : l’intelligence, en anticipant la mort et en révélant la passivité de la nature, menace la cohésion du groupe et la volonté de vivre — la fonction fabulatrice <em>contre-balance</em> ce risque en produisant des divinités, des esprits, des récits rassurants. Elle est à l’origine de la <strong>religion statique</strong> (de cohésion sociale et de défense), distincte de la <strong>religion dynamique</strong> des mystiques (élan créateur).',auteur:'Bergson',notions:['religion','nature','inconscient'],relations:[{to:'illusion',type:'prolonge',desc:'La fonction fabulatrice produit des illusions utiles à la vie.'},{to:'religion-statique-dynamique',type:'implique',desc:'Elle est à l’origine de la religion statique.'},{to:'aliénation-religieuse',type:'distinction',desc:'Pour Feuerbach/Marx, la religion aliène ; pour Bergson, elle est d’abord <em>défense vitale</em>.'}]},
{new:true,id:'religion-statique-dynamique',term:'Religion statique / dynamique',cat:'Philosophie de la religion',def:'Distinction bergsonienne (<em>Les Deux Sources</em>, 1932). <strong>Religion statique</strong> : produit de la fonction fabulatrice, fonction de cohésion sociale et de défense contre l’angoisse de la mort, figée dans les dogmes, les rites, les institutions — c’est elle que critiquent Marx (opium), Freud (illusion) et Durkheim (lien social). <strong>Religion dynamique</strong> : élan mystique des grands créateurs spirituels (saints, prophètes), expérience vivante du divin qui transforme l’humanité, non thématisable par les sciences humaines. Toute religion historique mêle les deux strates — mais la religion statique tend à étouffer la dynamique en l’enfermant dans des formules.',auteur:'Bergson',notions:['religion'],relations:[{to:'fonction-fabulatrice',type:'prolonge',desc:'La religion statique est l’œuvre de la fonction fabulatrice.'},{to:'illusion',type:'distinction',desc:'La religion <em>dynamique</em> n’est pas illusion : c’est une expérience irréductible.'},{to:'sacre',type:'complete'},{to:'foi',type:'complete'}]},
{new:true,id:'culte-morale',term:'Religion de simple culte / religion morale',cat:'Philosophie de la religion',def:'Distinction kantienne (<em>La Religion dans les limites de la simple raison</em>, 1793). Toutes les religions se ramènent à deux types. (1) <strong>Religion de simple culte</strong> : l’homme prie Dieu pour obtenir des faveurs (santé, salut, prospérité), sans rien <em>faire</em> pour devenir meilleur — superstition. (2) <strong>Religion morale</strong> : l’homme s’efforce de devenir meilleur par sa propre conduite, sans rien attendre en retour. Seule la seconde est conforme à la dignité du sujet rationnel et à l’<em>autonomie morale</em>. Kant ramène la religion vraie à la morale : tout culte sans œuvres est superstition.',auteur:'Kant',notions:['religion','devoir','liberte'],relations:[{to:'autonomie',type:'prolonge',desc:'La religion morale prolonge l’autonomie morale kantienne.'},{to:'imperatif-categorique',type:'complete',desc:'La religion vraie se ramène à la loi morale.'},{to:'religion-naturelle',type:'prolonge'},{to:'aliénation-religieuse',type:'oppose',desc:'Le culte sans œuvres aliène, la religion morale émancipe.'}]},
{new:true,id:'effet-barnum',term:'Effet Barnum',cat:'Psychologie / Critique des pseudo-sciences',def:'Biais cognitif (décrit par Paul Meehl en 1956, du nom du forain P. T. Barnum) : tendance à considérer comme étonnamment justes des descriptions de personnalité <em>générales et vagues</em> qui s’appliqueraient en réalité à n’importe qui. Mécanisme exploité par l’<strong>astrologie</strong>, les horoscopes, la <em>graphologie</em>, la voyance et la plupart des tests de personnalité non scientifiques. Une description « positive, plurivalente et flatteuse » sera reçue comme un portrait vrai. C’est l’une des raisons pour lesquelles ces disciplines sont des <em>pseudo-sciences</em> : leurs énoncés sont non-falsifiables parce qu’assez généraux pour s’adapter à tout cas particulier.',auteur:'Meehl / Forer',notions:['science','verite','raison'],relations:[{to:'falsifiabilite',type:'oppose',desc:'L’énoncé Barnum est non-falsifiable : il s’ajuste à tout cas.'},{to:'sophisme',type:'prolonge',desc:'Forme cognitive du sophisme — séduire par le général.'},{to:'doxa',type:'prolonge',desc:'L’opinion accepte le vague comme du vrai.'},{to:'theiere-russell',type:'complete',desc:'Pour Russell comme pour Meehl, la charge de la preuve incombe à qui affirme.'}]},
{new:true,id:'pastafarisme',term:'Pastafarisme',cat:'Philosophie de la religion',def:'« Église du Monstre en Spaghetti Volant » (<em>Flying Spaghetti Monster</em>), parodie de religion créée en 2005 par Bobby Henderson en réaction à l’<em>intelligent design</em> enseigné à l’école dans le Kansas. Argument : si l’on admet d’enseigner le créationnisme à parité avec l’évolution, alors n’importe quelle hypothèse de création divine non falsifiable mérite la même place — y compris celle d’un Monstre en Spaghetti Volant. Démonstration par l’absurde : on peut « faire une religion de n’importe quoi » si l’on ne retient pas l’exigence de falsifiabilité (Popper) et la charge de la preuve (Russell). Cousin contemporain de la théière de Russell.',auteur:'Henderson',notions:['religion','science','verite'],relations:[{to:'theiere-russell',type:'prolonge',desc:'Même argument que la théière : non-réfutable ≠ vrai.'},{to:'falsifiabilite',type:'complete',desc:'Démonstration <em>a contrario</em> du critère de Popper.'},{to:'concordisme',type:'oppose',desc:'Réponse satirique aux tentatives de mêler science et religion.'},{to:'noma',type:'complete',desc:'Plaide pour la séparation des magistères contre le créationnisme.'}]},
{new:true,id:'maitres-soupcon',term:'Maîtres du soupçon',cat:'Herméneutique',def:'Expression forgée par Paul Ricœur (<em>De l’interprétation. Essai sur Freud</em>, 1965) pour désigner conjointement <strong>Marx, Nietzsche et Freud</strong>. Tous trois rompent avec l’herméneutique classique de la confiance (le sens manifeste donne le vrai) au profit d’une <em>herméneutique du soupçon</em> : ce que la conscience croit dire est <em>l’envers</em> de ce qui se dit vraiment en elle. Marx soupçonne l’idéologie sous le discours politique ; Nietzsche, le ressentiment sous la morale ; Freud, le désir refoulé sous le discours du sujet. Trois variantes d’une même opération : démasquer une <em>fausse conscience</em> et restituer le sens latent.',auteur:'Ricœur',notions:['conscience','inconscient','religion','verite'],relations:[{to:'hermeneutique',type:'prolonge',desc:'Herméneutique du soupçon vs herméneutique de la confiance.'},{to:'aliénation-religieuse',type:'complete',desc:'La religion est l’un des objets privilégiés du soupçon.'},{to:'ideologie',type:'complete'},{to:'refoulement',type:'complete'}]},
{new:true,id:'consommation-opium',term:'Consommation comme nouvel opium',cat:'Philosophie sociale contemporaine',def:'Thèse de Gilles Lipovetsky (<em>Le Bonheur paradoxal</em>, 2006) : ce que la religion fut au XIX<sup>e</sup> siècle pour Marx (« opium du peuple »), l’<strong>hyperconsommation</strong> l’est devenue dans les sociétés démocratiques avancées. La consommation ne se contente plus de satisfaire des besoins ; elle vend des émotions, des identités, du sens — elle promet du <em>bonheur</em> mais entretient la frustration permanente, détourne de l’engagement politique et anesthésie la critique sociale. Mise à jour contemporaine de la critique marxiste : la marchandise a remplacé Dieu dans la fonction de compensation symbolique de la détresse.',auteur:'Lipovetsky',notions:['travail','justice','religion','bonheur'],relations:[{to:'aliénation-religieuse',type:'prolonge',desc:'Transposition contemporaine de l’opium religieux.'},{to:'alienation',type:'prolonge',desc:'Aliénation par la consommation, non plus seulement par le travail.'},{to:'reification',type:'complete',desc:'L’hyperconsommateur se traite lui-même comme un assemblage d’objets.'},{to:'plus-value',type:'complete'},{to:'ideologie',type:'complete'}]},
{new:true,id:'rep-absolu-relatif',term:'Absolu / Relatif',cat:'Repère',def:'<strong>Absolu</strong> : ce qui existe en soi et par soi, dont l\'existence et la valeur ne dépendent de rien d\'autre (étymologiquement « délié », sans relation). <strong>Relatif</strong> : ce dont l\'existence ou la valeur sont conditionnées par un élément extérieur, qui dépend d\'un point de vue. <br><em>Ex.</em> Dieu, conçu comme cause de soi, est absolu ; l\'être humain, créé et dépendant, est relatif.',notions:['verite','religion','liberte'],relations:[{type:'distinction',desc:'Absolu (en soi, inconditionné) ≠ Relatif (dépendant d\'autre chose ou d\'un point de vue).'}]},
{new:true,id:'rep-abstrait-concret',term:'Abstrait / Concret',cat:'Repère',def:'<strong>Abstrait</strong> : ce qui résulte d\'une opération intellectuelle détachant par la pensée une propriété ou une relation de son support. <strong>Concret</strong> : ce qui concerne la réalité perçue par les sens, saisie dans sa globalité. <br><em>Ex.</em> la loi de la chute des corps est abstraite ; la douleur ressentie au pied est concrète.',notions:['science','raison','art','conscience'],relations:[{type:'distinction',desc:'Abstrait (propriété isolée par la pensée) ≠ Concret (réalité sensible globale).'}]},
{new:true,id:'rep-acte-puissance',term:'En acte / En puissance',cat:'Repère',def:'Distinction aristotélicienne. <strong>En acte</strong> : ce qui existe réellement, pleinement réalisé. <strong>En puissance</strong> : ce qui n\'existe pas encore mais possède le potentiel de se réaliser. <br><em>Ex.</em> la maison construite existe en acte ; elle n\'était qu\'en puissance dans les plans de l\'architecte.',notions:['nature','liberte','technique'],relations:[{type:'distinction',desc:'En acte (réalisé) ≠ En puissance (réalisable, virtuel).'}]},
{new:true,id:'rep-analyse-synthese',term:'Analyse / Synthèse',cat:'Repère',def:'<strong>Analyse</strong> : décomposer un tout en ses éléments simples pour les examiner. <strong>Synthèse</strong> : recomposer le tout à partir de ses parties, du simple au complexe. <br><em>Ex.</em> Descartes (<em>Discours de la méthode</em>) recommande de diviser chaque difficulté (analyse), puis de conduire ses pensées par ordre du plus simple au plus composé (synthèse).',notions:['raison','science','conscience'],relations:[{type:'distinction',desc:'Analyse (décomposer le tout en parties) ≠ Synthèse (recomposer le tout à partir des parties).'}]},
{new:true,id:'rep-objectif-subjectif',term:'Objectif / Subjectif / Intersubjectif',cat:'Repère',def:'<strong>Objectif</strong> : ce qui ne dépend que de l\'objet, dont la validité est partageable par tous (domaine du savoir). <strong>Subjectif</strong> : ce qui dépend du sujet et varie d\'une personne à l\'autre (domaine de la croyance, du goût). <strong>Intersubjectif</strong> : accord construit entre plusieurs sujets par le dialogue. <br><em>Ex.</em> « la Terre tourne autour du Soleil » est objectif ; « ce plat est délicieux » est subjectif.',notions:['verite','science','conscience'],relations:[{type:'distinction',desc:'Objectif (dépend de l\'objet, universel) ≠ Subjectif (dépend du sujet, variable) ; l\'intersubjectif est l\'accord construit entre sujets.'}]},
{new:true,id:'rep-obligation-contrainte',term:'Obligation / Contrainte',cat:'Repère',def:'<strong>Obligation</strong> : devoir face auquel la volonté reste libre d\'adhérer ou non (contrainte morale, intérieure). <strong>Contrainte</strong> : ce qu\'on est forcé de faire sous la pression d\'une force extérieure à laquelle on ne peut résister. <br><em>Ex.</em> le panneau stop m\'oblige (je peux désobéir et en répondre) ; un barrage de police me contraint physiquement.',notions:['devoir','liberte','etat'],relations:[{type:'distinction',desc:'Obligation (devoir intérieur, la volonté reste libre) ≠ Contrainte (force extérieure qui supprime le choix).'}]},
{new:true,id:'rep-origine-fondement',term:'Origine / Fondement',cat:'Repère',def:'<strong>Origine</strong> : le commencement et la cause première dans le temps d\'un événement (« d\'où cela vient-il ? »). <strong>Fondement</strong> : ce qui rend raison d\'une chose, ce qui la justifie en droit (« qu\'est-ce qui la légitime ? »). <br><em>Ex.</em> la chute du mur de Berlin a une origine (faits, date) et des fondements (raisons économiques et politiques).',notions:['etat','justice','religion','science'],relations:[{type:'distinction',desc:'Origine (commencement de fait dans le temps) ≠ Fondement (justification en droit).'}]},
{new:true,id:'rep-persuader-convaincre',term:'Persuader / Convaincre',cat:'Repère',def:'<strong>Persuader</strong> : emporter l\'adhésion en s\'adressant aux sentiments et à l\'imagination, par la rhétorique. <strong>Convaincre</strong> : emporter l\'adhésion par des arguments rationnels et des preuves, valables pour tout esprit. <br><em>Ex.</em> l\'orateur persuade une foule ; le mathématicien convainc par une démonstration.',notions:['raison','langage','verite'],relations:[{type:'distinction',desc:'Persuader (par les sentiments, sans preuve) ≠ Convaincre (par la raison et la preuve).'},{to:'sophisme',type:'complete',desc:'La persuasion peut verser dans le sophisme : séduire sans prouver.'}]},
{new:true,id:'rep-principe-cause-fin',term:'Principe / Cause / Fin',cat:'Repère',def:'<strong>Principe</strong> : proposition de départ d\'où l\'on déduit (point de départ logique). <strong>Cause</strong> : phénomène antérieur qui produit ou détermine un effet (explique). <strong>Fin</strong> : but en vue duquel une action est accomplie (justifie). <br><em>Ex.</em> dans une expérience, on distingue le principe théorique, la cause d\'un phénomène et la fin poursuivie.',notions:['science','nature','raison'],relations:[{type:'distinction',desc:'Principe (point de départ logique) ≠ Cause (antécédent qui explique) ≠ Fin (but qui justifie).'}]},
{new:true,id:'rep-public-prive',term:'Public / Privé',cat:'Repère',def:'<strong>Public</strong> : ce qui est exposé au regard de tous, ou ce qui relève de l\'État et de l\'intérêt commun. <strong>Privé</strong> : ce qui échappe au regard d\'autrui, ou ce qui ne dépend pas de l\'État (intérêts particuliers). <br><em>Ex.</em> la laïcité impose la neutralité du fonctionnaire dans l\'espace public, non dans sa vie privée.',notions:['etat','justice','liberte'],relations:[{type:'distinction',desc:'Public (exposé à tous / sphère de l\'État) ≠ Privé (soustrait au regard / hors de l\'État).'}]},
{new:true,id:'rep-ressemblance-analogie',term:'Ressemblance / Analogie',cat:'Repère',def:'<strong>Ressemblance</strong> : similarité directe entre deux choses comparables (mêmes traits). <strong>Analogie</strong> : égalité de rapports entre quatre termes pris deux à deux (A est à B ce que C est à D). <br><em>Ex.</em> Paul ressemble à son frère (ressemblance) ; 4 est à 8 ce que 1 est à 2 (analogie).',notions:['raison','langage','science'],relations:[{type:'distinction',desc:'Ressemblance (similarité entre deux choses) ≠ Analogie (égalité de rapports entre quatre termes).'}]},
{new:true,id:'rep-theorie-pratique',term:'Théorie / Pratique',cat:'Repère',def:'<strong>Théorie</strong> : ensemble organisé d\'hypothèses, de connaissances vérifiées et de règles logiques — sa validité est d\'abord dans la pensée. <strong>Pratique</strong> : exercice concret d\'une activité, mise à l\'épreuve dans l\'expérience. <br><em>Ex.</em> la théorie physique prévoit ; la pratique technique réalise et vérifie.',notions:['science','travail','technique'],relations:[{type:'distinction',desc:'Théorie (savoir de pensée, contemplatif) ≠ Pratique (action effective dans l\'expérience).'}]},
{new:true,id:'rep-impossible-possible',term:'Impossible / Possible',cat:'Repère',def:'<strong>Impossible</strong> : ce qui implique une contradiction et ne peut donc se produire. <strong>Possible</strong> : ce qui n\'implique aucune contradiction et peut donc être ou ne pas être. <br><em>Ex.</em> un cercle carré est impossible ; un mort-vivant l\'est aussi (sauf dans la fiction).',notions:['liberte','raison','science'],relations:[{type:'distinction',desc:'Impossible (contradictoire) ≠ Possible (non contradictoire, peut être ou ne pas être).'}]},
{new:true,id:'rep-intuitif-discursif',term:'Intuitif / Discursif',cat:'Repère',def:'<strong>Intuitif</strong> : connu de manière immédiate, saisi d\'un seul coup sans raisonnement. <strong>Discursif</strong> : connu par une démarche intellectuelle, un enchaînement d\'étapes logiques que l\'on peut expliciter. <br><em>Ex.</em> on saisit intuitivement que les points d\'un cercle sont équidistants du centre ; on établit de façon discursive que la somme des angles d\'un triangle vaut 180°.',notions:['raison','conscience','verite'],relations:[{type:'distinction',desc:'Intuitif (saisi immédiatement) ≠ Discursif (établi par un enchaînement de raisonnements).'}]},
{new:true,id:'rep-legal-legitime',term:'Légal / Légitime',cat:'Repère',def:'<strong>Légal</strong> : conforme aux lois en vigueur (sa violation entraîne des sanctions juridiques). <strong>Légitime</strong> : conforme à un sentiment de justice ou à un droit supérieur (sa violation entraîne une désapprobation morale). <br><em>Ex.</em> aider un migrant, comme l\'a fait Cédric Herrou, peut être jugé légitime tout en étant illégal.',notions:['justice','etat','devoir'],relations:[{type:'distinction',desc:'Légal (conforme à la loi positive) ≠ Légitime (conforme à la justice ou à un droit supérieur).'}]},
{new:true,id:'rep-mediat-immediat',term:'Médiat / Immédiat',cat:'Repère',def:'<strong>Médiat</strong> : accessible seulement par l\'intermédiaire d\'un médiateur. <strong>Immédiat</strong> : accessible directement, sans intermédiaire. <br><em>Ex.</em> la pensée d\'autrui ne m\'est jamais immédiate : elle m\'est médiatisée par le langage et les signes.',notions:['conscience','langage','raison'],relations:[{type:'distinction',desc:'Médiat (par un intermédiaire) ≠ Immédiat (sans intermédiaire, direct).'}]},
{new:true,id:'rep-genre-espece-individu',term:'Genre / Espèce / Individu',cat:'Repère',def:'<strong>Genre</strong> : classe d\'êtres réunis par des traits communs (la plus grande extension). <strong>Espèce</strong> : subdivision d\'un genre, distinguée par une différence spécifique. <strong>Individu</strong> : être singulier appartenant à une espèce. <br><em>Ex.</em> l\'animal (genre), le cachalot (espèce), Moby Dick (individu).',notions:['nature','raison','science'],relations:[{type:'distinction',desc:'Genre (classe large) ⊃ Espèce (subdivision par différence) ⊃ Individu (être singulier).'}]},
{new:true,id:'rep-hypothese-consequence-conclusion',term:'Hypothèse / Conséquence / Conclusion',cat:'Repère',def:'<strong>Hypothèse</strong> : proposition avancée pour expliquer un problème, à vérifier. <strong>Conséquence</strong> : ce qui découle logiquement d\'un principe ou d\'une action. <strong>Conclusion</strong> : résultat final d\'un raisonnement. <br><em>Ex.</em> Galilée formule l\'hypothèse que tous les corps tombent à la même vitesse dans le vide, en tire des conséquences, puis conclut.',notions:['science','raison'],relations:[{type:'distinction',desc:'Hypothèse (point de départ supposé) ≠ Conséquence (ce qui en découle) ≠ Conclusion (résultat établi).'}]},
{new:true,id:'rep-ideal-reel',term:'Idéal / Réel',cat:'Repère',def:'<strong>Idéal</strong> : ce qui n\'existe qu\'en idée, modèle de perfection souvent inatteignable. <strong>Réel</strong> : ce qui existe effectivement et peut être objet d\'expérience. <br><em>Ex.</em> le Bonaparte héroïsé au pont d\'Arcole (idéalisé) contraste avec le réalisme de Courbet dans <em>Un enterrement à Ornans</em>.',notions:['art','bonheur','conscience'],relations:[{type:'distinction',desc:'Idéal (modèle qui n\'existe qu\'en idée) ≠ Réel (ce qui existe effectivement).'}]},
{new:true,id:'rep-identite-egalite-difference',term:'Identité / Égalité / Différence',cat:'Repère',def:'<strong>Identité</strong> : équivalence complète entre des choses indiscernables (le même). <strong>Égalité</strong> : équivalence quantitative entre des choses pourtant différentes. <strong>Différence</strong> : rapport de distinction entre des êtres. <br><em>Ex.</em> l\'égalité des citoyens devant la loi n\'efface ni leurs différences ni n\'en fait une seule identité.',notions:['justice','conscience','etat'],relations:[{type:'distinction',desc:'Identité (le même) ≠ Égalité (équivalence quantitative entre choses différentes) ≠ Différence (distinction).'}]},
{new:true,id:'rep-concept-image-metaphore',term:'Concept / Image / Métaphore',cat:'Repère',def:'<strong>Concept</strong> : représentation mentale abstraite et générale (la classe « table »). <strong>Image</strong> : représentation concrète et perceptible (telle table vue ou imaginée). <strong>Métaphore</strong> : figure qui désigne une chose par une autre qui lui ressemble. <br><em>Ex.</em> « mettre les points sur les i » est une métaphore.',notions:['langage','art','raison'],relations:[{type:'distinction',desc:'Concept (abstrait, général) ≠ Image (concrète, singulière) ≠ Métaphore (transfert de sens par ressemblance).'}]},
{new:true,id:'rep-contingent-necessaire',term:'Contingent / Nécessaire',cat:'Repère',def:'<strong>Contingent</strong> : ce qui peut ne pas être, ou être autrement qu\'il n\'est. <strong>Nécessaire</strong> : ce qui ne peut pas ne pas être. <br><em>Ex.</em> il est nécessaire de dormir, mais contingent de dormir jusqu\'à midi.',notions:['liberte','nature','religion'],relations:[{type:'distinction',desc:'Contingent (peut ne pas être ou être autrement) ≠ Nécessaire (ne peut pas ne pas être).'},{to:'determinisme',type:'complete',desc:'Le déterminisme tient tout événement pour nécessaire, enchaîné à ses causes.'}]},
{new:true,id:'rep-croire-savoir',term:'Croire / Savoir',cat:'Repère',def:'<strong>Croire</strong> : tenir pour vrai sans démonstration ni preuve suffisante (adhésion subjective). <strong>Savoir</strong> : disposer de connaissances rigoureuses fondées sur la démonstration ou l\'expérimentation. <br><em>Ex.</em> je crois qu\'il existe une vie extraterrestre ; je sais que ma côte est fêlée après la radiographie.',notions:['religion','science','verite','raison'],relations:[{type:'distinction',desc:'Croire (adhésion sans preuve) ≠ Savoir (connaissance fondée et démontrée).'},{to:'doxa',type:'complete',desc:'Croire relève de la doxa, l\'opinion non fondée.'},{to:'foi',type:'complete',desc:'La foi est une croyance qui s\'assume comme telle, sans prétendre au savoir.'}]},
{new:true,id:'rep-essentiel-accidentel',term:'Essentiel / Accidentel',cat:'Repère',def:'<strong>Essentiel</strong> : ce qui relève de l\'essence, qualités permanentes sans lesquelles la chose ne serait plus ce qu\'elle est. <strong>Accidentel</strong> : ce qui peut être modifié ou supprimé sans que l\'essence change. <br><em>Ex.</em> la rationalité est essentielle à l\'homme ; sa couleur de cheveux est accidentelle.',notions:['nature','verite','conscience'],relations:[{type:'distinction',desc:'Essentiel (constitue l\'essence, permanent) ≠ Accidentel (peut changer sans toucher l\'essence).'}]},
{new:true,id:'rep-exemple-preuve',term:'Exemple / Preuve',cat:'Repère',def:'<strong>Exemple</strong> : cas particulier qui illustre, éclaire ou fait comprendre une idée. <strong>Preuve</strong> : fait, résultat ou témoignage qui établit la vérité d\'une affirmation. <br><em>Ex.</em> des parents donnent l\'exemple à leurs enfants — mais un exemple n\'est jamais une preuve.',notions:['verite','science','raison'],relations:[{type:'distinction',desc:'Exemple (cas qui illustre, ne démontre pas) ≠ Preuve (ce qui établit la vérité).'}]},
{new:true,id:'rep-expliquer-comprendre',term:'Expliquer / Comprendre',cat:'Repère',def:'<strong>Expliquer</strong> : identifier les causes, dégager une loi à partir des faits (modèle des sciences de la nature). <strong>Comprendre</strong> : saisir le sens, se représenter de l\'intérieur une signification (modèle des sciences humaines). <br><em>Ex.</em> la psychanalyse explique un rêve par ses causes ; on comprend une œuvre d\'art en en saisissant le sens.',notions:['science','conscience','art'],relations:[{type:'distinction',desc:'Expliquer (par les causes et les lois) ≠ Comprendre (par le sens et la signification).'}]},
{new:true,id:'rep-fait-droit',term:'En fait / En droit',cat:'Repère',def:'<strong>En fait</strong> : ce qui existe réellement, tel qu\'on peut l\'observer. <strong>En droit</strong> : ce qui devrait être selon une norme ou un principe. <br><em>Ex.</em> les hommes naissent égaux en droit, mais des inégalités subsistent en fait.',notions:['justice','etat','devoir'],relations:[{type:'distinction',desc:'En fait (ce qui est observé) ≠ En droit (ce qui devrait être selon une norme).'}]},
{new:true,id:'rep-formel-materiel',term:'Formel / Matériel',cat:'Repère',def:'<strong>Formel</strong> : qui concerne la forme abstraite, indépendamment du contenu. <strong>Matériel</strong> : qui concerne la matière, le contenu concret qui remplit la forme. <br><em>Ex.</em> l\'égalité formelle devant la loi (juridique) se distingue de l\'égalité matérielle (accès réel aux ressources).',notions:['justice','etat','raison'],relations:[{type:'distinction',desc:'Formel (forme abstraite, sans contenu) ≠ Matériel (contenu concret qui remplit la forme).'}]},
{new:true,id:'rep-transcendant-immanent',term:'Transcendant / Immanent',cat:'Repère',def:'<strong>Transcendant</strong> : qui appartient à un ordre de réalité radicalement supérieur et n\'est pas directement accessible. <strong>Immanent</strong> : qui se tient dans le même ordre de réalité, présent et accessible. <br><em>Ex.</em> une justice transcendante (Dieu, idéal) se distingue d\'une justice immanente (les lois et institutions humaines).',notions:['religion','nature','etat'],relations:[{type:'distinction',desc:'Transcendant (ordre supérieur, au-delà) ≠ Immanent (présent dans le même ordre de réalité).'}]},
{new:true,id:'rep-universel-singulier',term:'Universel / Général / Particulier / Singulier',cat:'Repère',def:'<strong>Universel</strong> : vaut pour tous les individus d\'une catégorie, sans aucune exception. <strong>Général</strong> : vaut pour la plupart, en admettant quelques exceptions. <strong>Particulier</strong> : vaut pour quelques cas seulement. <strong>Singulier</strong> : vaut pour un seul cas. <br><em>Ex.</em> la loi de l\'attraction est universelle ; « l\'eau bout à 100 °C » est générale (exception en altitude).',notions:['raison','science','justice','etat'],relations:[{type:'distinction',desc:'Universel (tous, sans exception) ≠ Général (la plupart, avec exceptions) ≠ Particulier (quelques cas) ≠ Singulier (un seul cas).'}]},
{new:true,id:'rep-vrai-probable-certain',term:'Vrai / Probable / Certain',cat:'Repère',def:'<strong>Vrai</strong> : ce qui correspond exactement à la réalité (vérité de fait) ou ce qui n\'implique pas de contradiction (vérité de raison). <strong>Probable</strong> : ce qui est plus vraisemblable que son contraire. <strong>Certain</strong> : ce qui résiste au doute et offre toutes les garanties de fiabilité — mais reste subjectif. <br><em>Ex.</em> il est vrai que le réchauffement climatique est accéléré par l\'activité humaine ; il est probable qu\'il s\'amplifie ; je suis certain qu\'il préoccupera les générations futures.',notions:['verite','science','raison'],relations:[{type:'distinction',desc:'Vrai (conforme au réel, objectif) ≠ Certain (subjectif, résiste au doute) ≠ Probable (seulement vraisemblable).'},{to:'falsifiabilite',type:'complete',desc:'Une vérité scientifique se distingue par sa réfutabilité, non par la simple certitude subjective.'}]}
];
